window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["4028179"]={"book":{"id":4028179,"title":"怎么说孩子才会听如何听孩子才肯说","author":"苏豫","translator":"","publisher":"吉林大学","pubdate":"2009-1","isbn":"9787560146485","tags":["育儿","沟通","亲子教育","家庭教育","育儿的书","子女教育","心理学","儿童教育"],"memCount":6},"np":1,"pb":[24],"idx":[{"i":19453,"t":"描述式赞赏三步法\t","l":"TF3-1","c":"田娟","g":1,"p":1},{"i":17914,"t":"赞赏孩子的三个技巧","l":"TF1-2","c":"霍英霞","g":1,"p":1},{"i":17544,"t":"解决负面情绪沟通六法","l":"TF1-2","c":"刘彦奇","g":1,"p":1},{"i":17177,"t":"运用五个步骤解决复杂问题和冲突","l":"TF1-1","c":"霍英霞","g":1,"p":1},{"i":16621,"t":"“描述式赞赏”三步法","l":"TF3-1","c":"樊昊魁","g":1,"p":1},{"i":16062,"t":"谨防说太多的“不”","l":"TF1-1","c":"包不娴","g":1,"p":1},{"i":16002,"t":"用心倾听，畅享亲子沟通","l":"TF2-3","c":"海兰","g":1,"p":1},{"i":15927,"t":"如何帮助孩子客服依赖心理","l":"TF1-1","c":"朱齐琳","g":1,"p":1},{"i":15595,"t":"帮助孩子面对他们的感受","l":"TF2-1","c":"拆书家十八","g":1,"p":1},{"i":15372,"t":"如何让赞赏更走心","l":"TF3-2","c":"静Tina","g":1,"p":1},{"i":15329,"t":"五招让孩子愿意合作","l":"TF1-2","c":"俞三日","g":1,"p":1},{"i":15125,"t":"亲子沟通","l":"TF1-2","c":"京彩纷呈","g":1,"p":1},{"i":15077,"t":"有效赞赏孩子的三步法","l":"TF2-2","c":"静Tina","g":1,"p":1},{"i":13955,"t":"《解决问题的步骤》P106","l":"TF1-1","c":"雷丹虹","g":1,"p":1},{"i":11654,"t":"帮助孩子面对他们的感受","l":"TF2-1","c":"拆书家十八","g":1,"p":1},{"i":11302,"t":"三步赞赏法，让赞赏更真诚走心，提高沟通效果","l":"TF2-2","c":"李喜兰","g":1,"p":1},{"i":10590,"t":"怎样诚恳走心地夸奖别人","l":"TF2-1","c":"整理控文娟","g":1,"p":1},{"i":10492,"t":"如何用正确的方式代替惩罚","l":"TF2-1","c":"威威","g":1,"p":1},{"i":6609,"t":"如何帮助孩子面对感受","l":"TF1-1","c":"冯臻","g":0,"p":1},{"i":5863,"t":"用便签沟通法提升合作度","l":"TF3-1","c":"丹丁先生","g":1,"p":1},{"i":4496,"t":"如何提建议","l":"TF2-3","c":"姚莉","g":1,"p":1},{"i":4405,"t":"如何赞赏性表扬孩子","l":"TF1-1","c":"阿贞","g":0,"p":1},{"i":4403,"t":"如何描述性赞赏孩子","l":"TF1-1","c":"阿贞","g":1,"p":1},{"i":4392,"t":"帮助孩子面对感受","l":"TF2-1","c":"孙峰燕","g":0,"p":1}],"ms":[{"id":19453,"topic":"描述式赞赏三步法\t","learn_goal":"","remark":"你平时表扬人，是不是总说\t“你真棒\"\"做得\t\n好\"?这类简单赞美虽能让人一时开心，长期却难有实质激励，还可能显得敷衍。想拥有持续成长的下属、更自信的孩子，或是更默契的伙\n伴嘛?在这里我们将分享\t“描述式赞赏三步\t\n法\"，教你用具体行为、实际价值、真实感受表达认可，让沟通有力量，助力身边人成长!","level":"TF3-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"田娟","city":""},"club":{"name":"郑州轩辕分舵","city":"郑州"},"prologue":"\u003cp>【自我介绍】1分钟\u003c/p>\u003cp>各位伙伴，大家好！我是娟子，我的三个标签是：企业培训师、RIA学习力导师、野生主持人\u003c/p>\u003cp>【分组】\u003c/p>\u003cp>在今天的学习中，会有讨论环节，因此我们在场的小伙伴，左手边的分为1组，右手边的分为1组，便于后面的交流。\u003c/p>\u003cp>【学习目标】\u003c/p>\u003cp>大家在跟随我完成本次的 RIA 现场学习后，能够区分 “评论式赞赏” 和 “描述式赞赏” 的具体差异（澄清），在遇到需要赞美的场景时，能够运用描述式赞赏三步法开展赞赏反馈（行为），使被赞赏者通过表情、语言反馈等方式呈现出被肯定的积极状态（界定）。\u003c/p>\u003cp>【图书介绍】2分（到这里用时共3分）\u003c/p>\u003cp>事件场景：国庆节要带着孩子回老家，4岁半的儿子提着他小小的行李箱，自己收拾好了回老家要穿的衣服，然后兴高采烈的对我说妈妈，我的衣服收拾好啦。我当时脱口儿出，哇，你太棒啦。儿子把行李箱放一边继续玩玩具了。从老家回郑州的时候，我又叫他，帮我一起收拾回来的东西，他却不干了，我当时就挺郁闷的，在想哪里出了问题呢。\u003c/p>\u003cp>提问：各位伙伴，你们有没有过这样的经历，当孩子、家人、伙伴做出来一些好的行为时，我们很多时候就直接脱口而出太棒啦、你好优秀、你真厉害……\u003c/p>\u003cp>影响：但这样的夸赞究竟能起到什么样的作用？对方能感受到你的表扬或者赞美嘛？可能只是一个当时的小糖果而已，无法成为激励他一直保持正向行为的力量；年纪大点的孩子或成人还有可能会觉得你不真诚，感受不到赞美是走心的，觉得你好假好敷衍。\u003c/p>\u003cp>解决：那么怎么赞美别人才能让对方感受到真诚有效呢？今天带大家学习的《如何说 孩子才会听 怎么听 孩子才肯说》这本书中的拆页，就能很好的解决这个问题，虽然他是一本亲子沟通的书籍，但它包含的诸多沟通技巧同样适用于成年人。比如今天的这个关于如何表达赞美的拆页，拆页片段已经发给大家了，大家先用1-2分钟左右的时间阅读一下，读完可以抬头示意我。\u003c/p>","ratings_count":1,"texts":[{"id":23826,"quote":"\u003cp>【R原文片段：】2分钟（到这里用时共5分）\u003c/p>\u003cp>《如何说 孩子才会听 怎么听 孩子才肯说》P187页\u003c/p>\u003cp>我必须承认，开始的时候，我对这种赞赏方式表示怀疑。即使已经见过一次效，我还是对它有些想法，为什么不用“太好了！……你真棒！太了不起了！”这种最自然的赞赏方式，而非要用另外的方法来描述我们内心的惊喜呢？\u003c/p>\u003cp>但是不管怎么说，我还是努力去尝试，起先我很严格的去做，结果不久之后，我注意到孩子真的开始赞赏他们自己。\u003c/p>\u003cp>例如：\u003c/p>\u003cp>我:（没有说：“吉利，你真了不起！”）你算出来打折的玉米罐头是一美元三个，比不打折的一捆玉米罐头实际上要贵很多。我真高兴。\u003c/p>\u003cp>吉利：（咧嘴一笑），我很聪明啊！\u003c/p>\u003cp>我：（没有说“安迪，你真棒！”）你把韦克尼太太这么复杂的电话留言都记下来了，写的也很清楚。我明白为什么明天的会议顺延了，我需要找谁，该告诉他们什么。\u003c/p>\u003cp>安迪：是啊，我是个很靠得住的孩子。\u003c/p>\u003cp>毫无疑问，孩子们越来越了解和认可他们的能力了，这给了我继续努力的动力。而且这的确是需要努力。真正看到孩子好的行为，去体验并且详细描述出来，总是比只说一句“你真棒！”要困难得多。\u003c/p>","explains":"\u003cp>【I】拆书家讲解引导：6分钟（到这里用时共11分）\u003c/p>\u003cp>【过度语】\u003c/p>\u003cp>好的，我看伙伴们都看完了拆页部分，接下来我们一起来学习。\u003c/p>\u003cp>【what】\u003c/p>\u003cp>（辨析概念）\u003c/p>\u003cp>各位伙伴，在这个拆页中我们读到了两个赞赏的方式：一种是“太好了！……你真棒！太了不起了！”这样以主观评价为核心，直接对人或行为给出概括性、结论性的判断，不涉及具体细节的赞赏方式，我们定义它为“评论性赞赏”。而另一种是以客观事实为依据，用语言聚焦对方具体行为及积极影响，能让对方清晰知道自己“做对了什么、有何价值”的赞赏方式，我们定义它为“描述式赞赏”\u003c/p>\u003cp>（案例与概念相互参照）\u003c/p>\u003cp>为了大家更好的区分两个概念，接下来我们做个练习，大家来判断一下以下案例中，哪些是“评论性赞赏”和“描述式赞赏”\u003c/p>\u003cp>案例1：团队汇报后，领导对做报告的同事反馈：“你这次报告做得真好！”（评论性赞赏）\u003c/p>\u003cp>案例2：邻居帮忙代收快递并送到家门口，你对邻居说：“太感谢啦！你特意帮我代收了快递，还亲自送到家门口，我下班回来不用再跑驿站，省了好多事，被你这么贴心照顾着，真的特别温暖！”（描述式赞赏）\u003c/p>\u003cp>案例3：朋友组织小聚，结束后你对组织者说“你组织活动真厉害！”（评论性赞赏）\u003c/p>\u003cp>案例4：早上起床看到伴侣给你准备早餐，你对他说：“一早起来也太惊喜了吧！你特意给我做了煎蛋和喜欢喝的燕麦粥，我不用急着出门买早餐，既能吃到健康的，还能多睡 10 分钟，上班也不赶了，被你记着喜好、贴心照顾的感觉也太好了！”（描述式赞赏）\u003c/p>\u003cp>【why】\u003c/p>\u003cp>相信通过这几个例子让大家更清楚了这两种赞赏方式，虽它们都是表达认可，但长期效果天差地别：描述性赞赏有细节和感受，评论性赞赏只是主观判断。生活中很多人爱用评论性赞赏，图简单却只给评价、没理由，生硬易有歧义，是“无效赞赏”，不仅难鼓励人、提自信，还可能疏远感情；而描述性赞赏是“有效赞赏”，会具体说行为或感受，显真诚、给人快乐信心，刻意练着用，能帮对方认能力、提自信，还能拉近距离、建好人缘。\u003c/p>\u003cp>【how】\u003c/p>\u003cp>具体应该怎么做呢，只需要3步就能掌握这个技能：\u003c/p>\u003cp>1.说具体行为：别只夸“真棒”，而是要说对方做了啥（如“你算清了罐头折扣差价”“你记全了复杂留言”）\u003c/p>\u003cp>2.谈实际价值：说明这行为解决了什么问题、有什么好处（如“能判断买哪种划算”“我清楚会议安排了”）。​\u003c/p>\u003cp>3.讲真实感受：说给自己的好的方面（如 “我很放心”“我特别高兴”）。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>描述式赞赏适合需要深度认可、拉近距离、固化行为的场景，比如家人做好关键事项、同事攻克工作难题、朋友贴心帮大忙，或是孩子独立完成挑战；不适合赶节奏的紧急反馈，以及对方正需要安抚情绪的场景。\u003c/p>\u003cp>正面案例：\u003c/p>\u003cp>学了这个方法后，昨天晚上我回到家，看到儿子玩过玩具后给收拾到了玩具箱里，之前都是扔一地然后吵他后一起收拾或者奶奶收拾。于是我就及时对他进行了赞美：宝贝，你今天玩完玩具后，主动把玩具箱打开，把所有玩具都归位放好，还把玩具箱盖子轻轻合上了（说具体行为）；这样下次你想玩玩具时，能直接从箱子里找到，不用到处翻找，也让客厅保持干净（讲实际价值）；妈妈看到你能做到自己的事情自己收尾，特别骄傲，觉得你越来越能干啦（表真实感受）！\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>很多人觉得赞美不用复杂，随口夸两句就行，可这样的赞美太表面，不仅让对方摸不清自己‘好在哪’，也没法让他愿意重复好的行为\u003c/p>","interaction":"\u003cp>\u003cstrong>【过渡语】\u003c/strong>\u003c/p>\u003cp>亲爱的伙伴，为了更好的掌握今天学习的技能，接下来让我们一起做个练习。\u003c/p>\u003cp>\u003cstrong>【显像提问】\u003c/strong>\u003c/p>\u003cp>请大家想象一下未来一个月或者一周内，你可能会遇到什么需要赞美他人的事情呢？比如孩子主动把脏衣服放进洗衣篮、同事帮你梳理了杂乱的项目数据、邻居主动搭手帮你把大件快递搬到家门口等等，请把你预计会发生需要赞赏的场景按照给大家练习单上的格式给编成小剧场。\u003c/p>\u003cp>编写要求：剧场中需包含明确的故事背景（含具体时间、地点）、两个核心人物角色、清晰的 “起因 - 经过 - 结果” 情节线，且人物对话中需自然融入描述式赞赏三步法（说具体行为 + 谈实际价值 + 讲真实感受）。\u003c/p>\u003cp>接下来请大家开始编写自己的剧本。时间五分钟，五分钟后，我们请小伙伴来分享自己的剧本。\u003c/p>\u003cp>（过渡语）：接下来，邀请一位小伙伴来分享下:\u003c/p>\u003cp>莹莹分享：\u003cbr>故事背景：我是一名研三的学生，目前正在写毕业论文，需要学习数据分析\u003cbr>时间：下个月\u003c/p>\u003cp>地点：学校\u003c/p>\u003cp>人物：我和同学小李\u003c/p>\u003cp>起因：我正在自习室研究如何做数据分析，唉声叹气时，同学小李路过，注意到了我们的状态不太对\u003c/p>\u003cp>经过：\u003c/p>\u003cp>小李：莹莹，看你愁眉苦脸的，是遇到什么问题了吗？\u003cbr>莹莹：是的，数据分析不知道怎么做，研究了好几天了，还没有研究明白\u003c/p>\u003cp>小李：不要担心，让我看看是研究的哪方面的数据呀？随后小李说，这个我刚好会，并且我还有相关的资料可以分享给你，然后我在教你一些方法\u003c/p>\u003cp>莹莹：小李，你真的好贴心，不仅给我分享资料，还给我教会方法，可以让我研究数据时不在迷茫，提高学习效率，我真的很幸福，有你这么好的同学真好\u003c/p>\u003cp>结果：我不仅解决了数据上的困扰，特别的开心，小李听到我对他的感谢后更是露出了幸福的微笑，我们关系更近了。\u003c/p>\u003cp>\u003cstrong>【拆书家点评】1分钟（到这里用时共19分）\u003c/strong>\u003c/p>\u003cp>感谢莹莹的反馈分享，伙伴们，相信通过这个演练，大家一定对如何真诚的赞赏别人有了更深入的了解\u003c/p>\u003cp>\u003cstrong>【结束语】\u003c/strong>\u003c/p>\u003cp>各位伙伴，今天咱们学透了描述性赞赏，核心就是把 “夸”落到细节上。接下来试着用在生活里吧，一句有细节的认可，比十句“真棒”更有力量。课程就到这，期待大家的实践！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1763623261000,"updated_at":1766372558000,"ria":true},{"id":17914,"topic":"赞赏孩子的三个技巧","learn_goal":"","remark":"用赏识的目光捕捉，用真诚的语言表达。学会赞赏孩子的三个技巧，让他人在我们语言的力量下越来越有力量，关系越来越融洽！","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"霍英霞","city":""},"club":{"name":"邢台第二筹备分舵","city":"邢台"},"prologue":"\u003cp>各位新朋友、老朋友，大家好，我是拆书家霍英霞。我身上有三个标签：一名从教25年的小学语文教师，一个大学生女儿的妈妈，一个爱学习的终身学习者。\u003c/p>\u003cp>为了方便我们接下来的学习，我们先进行一个分组，以现在的座位为准， 每四人位一组。\u003c/p>\u003cp>今天的分享的拆页来自书籍《如何说孩子才会听 怎么听孩子才肯说》 作者是阿黛尔•法伯、伊莱恩•玛兹丽施。这本书在1980年首次发行后，先后被译为30多种文字，风靡全球，长踞家教图书榜首。书中不仅有亲子沟通的策略，还有详实丰富丰富的案例，其中的理念和方法不仅可以运用到育儿之中，更引发了我们对关系建立的进一步思考。\u003c/p>\u003cp>接下来请大家用1分钟的时间阅读拆页内容，阅读结束后，请抬头示意。\u003c/p>","ratings_count":1,"texts":[{"id":22157,"quote":"\u003cp>从我们日复一日对孩子细微处的描述，孩子们也在不断地增加他们内心的力量。孩子发现他可以把杂乱的屋子整理干净，他能做个礼物为他人带来帮助和安慰，他能抓住观众的注意力，他能写出感人的诗篇，他能做到守时，他有控制自己的能力，他主动、灵活。所有这些都会存储在他的内心，没有人能夺去。今天有人对他的评价可能是个“好孩子”，明天可能有人对他的评价是“坏孩子”，但是他用康复卡鼓励妈妈的那些时光以及他不知疲倦坚持学习的那些日子，在他心里是不会被抹去的。\u003c/p>\u003cp>所有这些经历，都可以在今后受到挫折和困惑的时候，给他安慰和鼓励，也都会成为他日后成功的基石。\u003c/p>\u003cp>赞赏孩子的三个技巧\u003c/p>\u003cp>1.描述你所看见的。\u003c/p>\u003cp>2.描述你的感受。\u003c/p>\u003cp>3.把孩子值得赞赏的行为总结为一个词。\u003c/p>","explains":"\u003cp>What：当孩子完成一件事情，或达成我们期盼的时候，我们都会用“真棒”“你做的真好”“哇，你太厉害了”这样的语言表示我们的赞赏\u003c/p>\u003cp>Why：我们用赞赏让孩子更有力量，让他拥有美好的回忆去应对未来不确定的日子。我们还可以用赞赏让孩子对自己的行为有正确的认知。但是不恰当的赞赏方式，不仅不会产生预期的教育效果，甚至可能让孩子自我怀疑，骄傲自满，虚荣心强，急功近利等。\u003c/p>\u003cp>How：那么，怎样去赞赏孩子呢，这里有三个技巧\u003c/p>\u003cp>第一个技巧：描述所见。就是不加评判，将能够看到，尤其是细节，不加修饰词地描述出来。\u003c/p>\u003cp>“我看到书都摆在桌子上，玩具也都收在架子上了，地面上没有一片字纸和垃圾。”\u003c/p>\u003cp>第二个技巧：表达感受。能够用表示情绪的词语表达自己的感受。\u003c/p>\u003cp>“我看到这样的房间觉得很舒服”\u003c/p>\u003cp>第三个技巧：总结行为。\u003c/p>\u003cp>把孩子值得赞赏的行为总结为一个词。“你把玩具都分类摆放了，既整齐、拿取又方便，这就叫做‘有条理’”。\u003c/p>\u003cp>讲一个我自己的例子：孩子大三了，正面临考研的选择上。这次回来又给我讲起准备跨考心理学，我对她说：“我看到你经过再三考虑，从化学到药学又到生物学，最后坚定地选择跨考心理学。我有些担心这条路难走，但更多的是对你的敬佩。你能选择自己喜欢的专业去跨考，这就叫做‘勇气可嘉’！”她说，嗯，谢谢妈妈。\u003c/p>\u003cp>Where:这种用描述替代评价的方法，不仅适用于赞扬孩子，还可以用于日常赞扬他人，让对方开心、自信、有力量，形成良好的人际关系。\u003c/p>","interaction":"\u003cp>赞赏可以给人力量，也能建立良好关系。回想一下我们最近一个月，有没有看到孩子或家人在哪些地方做得比较好，值得我们去赞赏呢？我们当时是怎么说的呢？对方的反应如何？我们在组内和小伙伴们进行分享吧，总共5分钟。可以讲自己成功的例子，也可以讲自己失败的例子。\u003c/p>\u003cp>赞赏让关系更紧密，在未来一个月内我们应该如何运用所学呢？请大家用1分钟的时间在纸上写出你的目标和行动规划。目标要有清晰具体、可衡量，计划要可执行、并且安排时间期限。参考格式为：在什么场景，什么时间段，我和谁对话，我是如何运用 3个技巧来说的 1、2、3,这样做我对结果的期待是什么?\u003c/p>\u003cp>大家都已经写好了，那么我想请一位小伙伴来分享一下。\u003c/p>\u003cp>用赏识的目光捕捉，用真诚的语言表达。在这次拆书中，我们了解了赞善孩子的三个技巧：描述所见，表达感受，总结行为。希望每位小伙伴都能运用好这三个技巧，让他人在我们语言的力量下越来越有力量，关系越来越融洽！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1722500796000,"updated_at":1751003976000,"ria":true},{"id":17544,"topic":"解决负面情绪沟通六法","learn_goal":"","remark":"孩子有负面情绪时，我们如何沟通？本场拆书分享的“解决负面情绪沟通六法”帮助我们解决问题","level":"TF1-2","duration":24,"status":30,"type":0,"chaishujia":{"username":"刘彦奇","city":"长沙市"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"\u003cp>大家好！\u003c/p>\u003cp>我是刘彦奇，很高兴今天给大家进行TF1-2的拆书分享。\u003c/p>\u003cp>三个标签介绍一下自己：\u003c/p>\u003cp>『二个孩子爸爸』：一儿一女。\u003c/p>\u003cp>『公 务 员』：现在湘西龙山县乡村振兴驻村帮扶。\u003c/p>\u003cp>『准拆书家』：希望一年内能不断精进自己的拆书技能。\u003c/p>","ratings_count":3,"texts":[{"id":21731,"quote":"\u003cp>摘自《如何说孩子才会听，怎么听孩子才肯说》P27页。\u003c/p>\u003cp>***\u003c/p>\u003cp>1．帮助孩子面对他们的感受，孩子需要他们的感受被接纳和尊重。\u003c/p>\u003cp>2．安静专心地倾听。\u003c/p>\u003cp>3．用简单的词语回应他们的感受。\u003c/p>\u003cp>“哦·····嗯······原来是这样······”\u003c/p>\u003cp>4．说出他们的感受。\u003c/p>\u003cp>“这件事让你很灰心！”\u003c/p>\u003cp>5．用幻想的方式实现他们的愿望。\u003c/p>\u003cp>“真希望我能立刻把香蕉变熟了给你吃！”\u003c/p>\u003cp>6．所有的感受都应该被接纳，但某些行为必须受到限制。“我看得出你很生弟弟的气。用嘴巴告诉他你将怎么做，而不是用拳头。”\u003c/p>\u003cp>***\u003c/p>","explains":"\u003cp>『I 』讲解引导\u003c/p>\u003cp>what：这个片断主要讲述当我们的孩子有负面情绪时，我们如何与孩子沟通，引导孩子化解负面情绪，克制一些不合理行为。\u003c/p>\u003cp>why：我们和孩子是两个独立的个体，有着不同的感知系统，都有各自真实的感受，没有对错之分。如果父母能深入到孩子的内心，理解孩子的感受，肯定孩子的感受，帮助他们了解自己最真实的想法，对孩子来说是很大的帮助。孩子一旦清楚了自己的内心的想法，他们会愿意与父母沟通交流，就能在父母的引导下，集中精力来应对出现的问题，化解负面情绪。反之，如果我们不这么做，当孩子的感受被搁置或者直接否定时，负面情绪就会让孩子从对事物的抱怨转移到对父母的抱怨，孩子就会与父母之间将越来越走向对抗，孩子的负面情绪会进一步被激化。而你越是希望孩子停止抱怨，你就越会被无理取闹的孩子激怒。\u003c/p>\u003cp>how：根据拆页，我总结了一个“负面情绪六步化解法”\u003c/p>\u003cp>1.面对感受。通过语言引导孩子说出自己的困难，以便我们正视他的感受。\u003c/p>\u003cp>2.专心倾听。尊重的前提首先是倾听对方，我们只需要认真倾听就可以有好的效果。\u003c/p>\u003cp>3.简单回应。在倾听过程中给予回应，虽然只是几个字，但孩子知道你在确实在认真听他说话。\u003c/p>\u003cp>4.说出感受。理解孩子后猜想孩子当时的感受，并表达出来，帮助孩子一同面对感受。\u003c/p>\u003cp>5.幻想实现。用幻想的方式使孩子内心的需求得以实现，让孩子真正体会到父母对他的理解。\u003c/p>\u003cp>6.限制行为。对一些不合理的行为给予限制。\u003c/p>\u003cp>example：记得前几天，我家二孩，回家做作业时，因为不会，妈妈在外开会，我在外地，家里外婆不会辅导他作业，急得直跳，还用手扯自己头发了。我当时心痛儿子、也很着急，但我想到了这个“负面情绪六步化解法”，并一步一步引导他缓解负面情绪。\u003c/p>\u003cp>第一步：面对感受。打电话给他，引导他说出困难和感受，说：“你现在有什么困难？”\u003c/p>\u003cp>第二步：倾听儿子反馈的困难和感受。\u003c/p>\u003cp>第三步：简单回应。说：“哦，原来是这样的。”\u003c/p>\u003cp>第四步：说出感受。说：“我知道你很着急，害怕因为作业完不成，会被老师批评。”\u003c/p>\u003cp>第五步：幻想实现。说：“不过没关系，你不用害怕，现在时间是八点，爸爸指导你，相信你能够很快完成作业。”\u003c/p>\u003cp>第六步：限制行为。对他说：“但你不能做用手扯头发的动作，这种方式不能解决你的问题，还会伤害到你。”\u003c/p>\u003cp>打过电话后，我能感觉孩子的情绪得到了缓解，不再象开始，只是自顾自说，开始与我沟通。相信我熟练运用这个方式，我与孩子沟通的效果会越来越好。\u003c/p>\u003cp>where：当孩子通过一些不合理的方面发泄负面情绪时，我们适用这个方法。当然在遇到成年人因情绪激动，采取一些不理智的方式沟通交流时，也可以使用这个方法。\u003c/p>","interaction":"\u003cp>『A1』学习者拆为己用\u003c/p>\u003cp>拆书指令：\u003c/p>\u003cp>请大家回想下，你的小孩最近因为什么事情而闹过情绪？小孩不愿意起床，不愿意刷牙，不愿意上学。在超市看到想要的玩具赖着不走。在学校跟同学闹矛盾，被老师误会等等。\u003c/p>\u003cp>你是怎么回应的？\u003c/p>\u003cp>5分钟后我们请每组一个代表分享一下。\u003c/p>\u003cp>5分钟时间到，现在我每组邀请一位小伙伴用1分钟的时间分享一下他的经历。\u003c/p>\u003cp>现在有请蓉蓉分享：\u003c/p>\u003cp>蓉蓉：孩子小的时候经常不能很好地表达，会很容易处在自己的情绪之中。比如我们家小孩，前几天，她跑完步，自己去洗澡，过程中，我去看了一下，发现她洗完澡后，又穿上了的脏衣服。我就冲了进去说，宝宝您错了，您不应该穿脏衣服，要换上干净的衣服。这时候，我的孩子突然就情绪上来了，大哭起来，我当时都傻了，不知道怎么处理，他的情绪一下子就强烈了，用哭泣来表达，让我出去。这就是我遇到的一个情绪事件。\u003c/p>\u003cp>好，谢谢蓉蓉小伙伴的分享。\u003c/p>\u003cp>『A2』催化应用\u003c/p>\u003cp>接下来请大家考虑下在未来的两周内，当你再次遇到孩子出现负面情绪时，将如何运用今天学习的方法（面对感受，专心倾听，简单回应，说出感受，幻想实现、限制行为），融会贯通与孩子进行沟通呢？请说明应用的具体场景，具体做法、具体时间和要达到什么具体效果。\u003c/p>\u003cp>给大家用5分钟的时间思考并记录在便签纸上。现在开始。请完成的伙伴在聊天里回复1示意我一下。\u003c/p>\u003cp>5分钟时间到，下面我邀请一位同学用1分钟的时间分享一下他的计划。还没写好的小伙伴可以分享到留言区，或者发给我。\u003c/p>\u003cp> 下面还是请蓉蓉分享：\u003c/p>\u003cp> 蓉蓉：如果我下次碰到孩子有负面情绪时，我会尝试体会一下孩子的感受， 他哭的话我也会陪着她慢慢地哭。然后跟她说，妈妈知道您现在有一点不开心，要她告诉我为什么不开心，是碰到了什么问题，我们可以商量，对不合理的行为进行限制。\u003c/p>\u003cp> 好的，感谢蓉蓉的分享，如果下次场景更具体一些会好些。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1714285456000,"updated_at":1718717033000,"ria":true},{"id":17177,"topic":"运用五个步骤解决复杂问题和冲突","learn_goal":"","remark":"父母总感觉孩子不听话，孩子总觉得父母不理解自己，那如何跟孩子实现有效沟通呢","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"霍英霞","city":""},"club":{"name":"邢台第二筹备分舵","city":"邢台"},"prologue":"\u003cp>各位好！我是霍英霞，霍是霍元甲的霍英是英雄的英，霞是霞光的霞。我和大富豪霍英东的名字只差一个字，我是迎着朝霞出生的，所以名字当中有一个霞。\u003c/p>\u003cp>我的第一个标签：教师。并且我是一名从教25年的老教师啦，一直从事一线教学工作，送走了很多届毕业班。\u003c/p>\u003cp>我的第二个标签：妈妈。我的女儿已经上大学了，在养育她的路上有很多的经历，有机会我会一一和大家分享。\u003c/p>\u003cp>我的第三个标签：终身学习者。在遇到问题的时候我喜欢通过学习去解决问题，我先后学习了国家二级心理咨询师、家庭教育咨询师、青少年生涯规划师，参加了父母效能训练工作坊，这些学习让我在工作和生活中受益匪浅。\u003c/p>\u003cp>在学习中，我们形成了学习共同体，在小伙伴的身上汲取了很多的力量。也第一次听说了拆书帮，进入了拆书之旅，虽然路由坎坷，但是仍痛并快乐着！\u003c/p>\u003cp> 拆书法：“拆书法”是一种学习的方法。你是否经历过经常读书，但是又感觉自己没有什么所得？读了很多书，但是自我又没有成长？通过拆书ria的三个便签法，可以让你的学习更有成效。那什么是RIA呢？R是Reading，阅读原文，I是Interpretation：理解，用自己的语言重述这块内容，A是Appropriation：应用，其中分为A1和A2。A1指向过去，针对其中某个信息，问自己有无相关经历，听、见或思考过类似事情。A2指向未来，规划今后如何把这个点运用到工作和生活中，以及想要达到的目标或实施的行动。拆书法又分为个人学习和现场学习。一位专业的拆书家可以将一本30元的致用类图书拆为一场3万元的培训。\u003c/p>\u003cp>拆书帮：拆书帮的使命是致力于培养拆书家，将我们这样的一群人聚集在一起，释放拆书家的能量，相互陪伴，助人达己。拆书帮的愿景是帮助拆书家们升级学习力。拆书帮的价值观是陪伴赋能、拆为己用、反求诸己、持续精进、共同成长。通过不断的晋级，让自己拆书的技能越来越高，成为一个主动学习者。加油，我们一起学习，拆为己用。\u003c/p>\u003cp>过渡语：接下来我将现场演练（RIA）拆书过程。\u003c/p>\u003cp>今天给大家带来的原页是《如何说孩子才会听 怎么听孩子才会说》中106页片段，时间交给大家，观看文本片段。看完之后抬头或举手示意我即可。\u003c/p>","ratings_count":1,"texts":[{"id":21353,"quote":"\u003cp>当问题一再出现时,情况就会变得比先前复杂。那么复杂的问题就需要复杂的技巧。家长辅导员、劳务谈判代表、婚姻咨询师已经总结出一套非常好的方法,来解决复杂的问题和冲突。这是我在小组里介绍给大家的:\u003c/p>\u003cp>解决问题的五个步骤\u003c/p>\u003cp>第一步:讨论孩子的感受和需求\u003c/p>\u003cp>第二步:说出你的感受和需求\u003c/p>\u003cp>第三步:一起讨论,找到大家都同意的解决方法\u003c/p>\u003cp>第四步:把所有的想法都写下来(不带任何评论)。\u003c/p>\u003cp>第五步:挑出哪些建议你们接受,哪些不接受,哪些要付诸行动\u003c/p>","explains":"\u003cp>What:\u003c/p>\u003cp>孩子放学和小伙伴打篮球、在外面玩不回家，你都准备开饭了，她还没回家，而这件事你已经给他说了很多遍了；孩子总是写作业总是拖延，导致你10点半了还不能睡觉，你特别困扰；孩子假期想去海边度假，可你早就想去大理玩，该怎么办呢……当你面临这些困扰的时候，你可以尝试运用五个步骤去解决这些复杂问题和冲突，寻找到双方都满意的方案。\u003c/p>\u003cp>Why:\u003c/p>\u003cp>冲突意味着需求不同，冲突的反义词是融合或和谐。我们希望解决问题，更渴望和谐的关系。通过五个步骤，关注到需求双方，评估出最合适现状的解决方法。这样，用简单的方法形成和谐的关系，满足双方的需求。\u003c/p>\u003cp> how：\u003c/p>\u003cp>具体的做法可参照以下步骤：\u003c/p>\u003cp>1.倾听感受。请孩子聊一聊他的想法和感受，了解孩子的需求。比如，你特别想和小朋友一起玩，让你离开，真的挺不容易。\u003c/p>\u003cp>2.表达需求。向孩子表达自己的真实想法和感受，尤其是孩子的做法中哪些地方影响到了自己。“但是，我也很想在六点半开始吃晚饭。”\u003c/p>\u003cp>3.讨论方法。讨论交流孩子和家长都可以接受的解决方法，这一点非常重要，如果遇到自己无法接受的方法，一定要真实表达，表明这个方法自己为什么接受不了。可以说：“让我们一起想一想，有什么方法？”\u003c/p>\u003cp>4.列出方法。把讨论到的方法逐条写下来，可以把孩子提出的方法和家长的方法分列写出。“我写下来了，还有吗？”\u003c/p>\u003cp>5. 确立方案。和孩子一起逐条评估方法，确定双方都能接受的最终方案并实施。“我们一起看看哪些要去掉？哪些可以保留”\u003c/p>\u003cp>where：\u003c/p>\u003cp>这种方法不但可以用在孩子遇到问题时，其他很多地方也适用。比如亲密关系、夫妻之间需要协商事情；工作中上下级就某些问题有意见分歧；商业用途中和客户如何达成一致等；在学校中，也可用在处理学生、家长之间的纠纷时。\u003c/p>","interaction":"\u003cp> A1故事：孩子上初中的时候总是写作业特别磨蹭，十一二点写不完都是常事。我陪着她到十点多的时候都困得不得了，有时就打盹睡着了。她就让我早点休息，可是我怕不盯着她她就更磨蹭。有一次，十点半看着她对着一道数学题发愣，过了15分钟，还是那种状态不在线。我找出答案让她抄，说赶紧写完睡觉。她还是不动，我就急了。最后揍了她几巴掌，她也哭了，说：“妈妈，我也想学习好啊！”\u003c/p>\u003cp>反思：现在想想，当他作业出现问题，我也休息不了，这种问题时常出现的时候，我们应该在有时间没情绪的时候，用五步法去寻找到一个解决方案。既帮她找到学习、完成作业的方法，也让我能好好休息。\u003c/p>\u003cp>【A2具体应用】3分钟\u003c/p>\u003cp>孩子上大学了，在外的时间越来越多了，联系越来越少了，我挺担心她在外的安全的。因此，我计划在寒假她回来的时候用五步法和她聊一聊。\u003c/p>\u003cp>目标：孩子放假回家5天内，和孩子一起确定在外时候怎么能让彼此放心 。\u003c/p>\u003cp>步骤：\u003c/p>\u003cp>第一步，先约好某一天要一起讨论这个事。\u003c/p>\u003cp>第二步，用五步法来寻找解决方案\u003c/p>\u003cp>1.倾听感受。我：丫头，你去长沙玩的时候，你特别高兴还是兴奋呀，与我说说呗，或者我还需要为你做些什么？\u003c/p>\u003cp>2.表达需求。那天你到了之后没有给我报平安，出门在外担心，真是需要得到你的信息。\u003c/p>\u003cp> 3.讨论方法。那我们都来说说，怎么才能让你不烦我，我又安心呢？\u003c/p>\u003cp>4.列出方法。咱们把这些条都写下来，找到你我都能接受的方法。\u003c/p>\u003cp>5. 确立方案。我们一起找到了解决这个问题的方法，我们就按这样试试看吧。\u003c/p>\u003cp>第三步：实践并评估情况。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1705302173000,"updated_at":1706189083000,"ria":true},{"id":16621,"topic":"“描述式赞赏”三步法","learn_goal":"","remark":"不恰当的表扬或者赞赏，短期来看，\n孩子会得到满足，孩子会开心。\n但是这样会把孩子培养成固定型思维。\n当他做的好，做的对的时候，\n他相信是自己聪明。\n当遇到挫折的时候，就会焦虑，\n会否认，会认为运气不好。\n而为了再次证明自己聪明，会挑选简单，\n没有难度的任务去完成。长此以往，\n孩子在面对障碍时轻易放弃，\n无法接受一点批评。\n对他的未来造成深远的伤害！","level":"TF3-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"樊昊魁","city":"常州市"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>\u003cstrong>自我介绍\u003c/strong>\u003c/p>\u003cp>不破不能立，不拆不成器！拆书帮把知识拆成你的能力！欢迎大家参加拆书帮线下拆书练级活动。我是今天的领拆人樊昊魁。三个标签介绍自己：1.企业内训师。2.爱好参加线下沙龙活动。3.2级拆书家。\u003c/p>\u003cp>\u003cstrong>分组\u003c/strong>\u003c/p>\u003cp>一会儿有分组讨论的环节，为了便于活动进行，咱们现在分个组。从我的右手边起，每两人一组。\u003c/p>\u003cp>\u003cstrong>学习目标\u003c/strong>\u003c/p>\u003cp>咱们对齐一下今天的学习目标：：在跟随我完成本次的拆书现场学习后，学习者能够区分“评论性赞赏”和“描述性赞赏”，在需要夸奖他人的时候可以运用“描述性赞赏”的三步法，让对方真正收到你的真诚赞赏，以帮助他人了解和认可自己的能力。\u003c/p>\u003cp>\u003cstrong>【场景】\u003c/strong>\u003c/p>\u003cp>在讲这本书之前，我想先分享一个我和我女儿果果的故事。今年6月30号是学校公布考试成绩的时候。作为家长，表面说是不在意孩子的成绩，其实内心里也有一点忐忑。我下班一进门就迫不及待的问孩子：“果果，今天~学校发成绩单了么？”果果灿烂的笑着回答：“发了发了！”接着就小跑着去拿成绩单。呵，看来成绩应该还不错。我心里想。接手一张A4大小的打印纸，扑面还有点油墨的香气。嚯！6个优秀！我心里呀，乐开了花，说道：“果果，真是太厉害了！你真是一个小天才！”\u003c/p>\u003cp>\u003cstrong>【提问】\u003c/strong>\u003c/p>\u003cp>各位伙伴，你们有没有过类似的经历？孩子做的好的时候，做的对的时候，直接就用“太厉害了”，“你真聪明！”“你很棒！”“非常好”等等话语来表扬孩子？\u003cstrong>（互动）\u003c/strong>学习者：不好！\u003c/p>\u003cp>\u003cstrong>【影响】\u003c/strong>\u003c/p>\u003cp>那么这样真的好吗？短期来看，孩子会得到满足，孩子会开心。但是这样会把孩子培养成固定型思维。当他做的好，做的对的时候，他相信是自己聪明。当遇到挫折的时候，就会焦虑，会否认，会认为运气不好。而为了再次证明自己聪明，会挑选简单，没有难度的任务去完成。长此以往，孩子在面对障碍时轻易放弃，无法接受一点批评。对他的未来造成深远的伤害！\u003c/p>\u003cp>\u003cstrong>【解决】\u003c/strong>\u003c/p>\u003cp>那么应该如何解决这个问题呢？我今天带来的这本书《如何说孩子才会听怎么听孩子才肯说》提供了一种“描述性赞赏”这样的方法，来让我们学会如何正确的鼓励孩子。\u003c/p>\u003cp>下面请大家阅读手中的拆页，时间2分钟，现在开始\u003c/p>","ratings_count":1,"texts":[{"id":20731,"quote":"\u003cp>书籍：《如何说 孩子才会听 怎么听 孩子才肯说》\u003c/p>\u003cp>作者：阿黛尔.法伯\u003c/p>\u003cp>页码：P187\u003c/p>\u003cp>标题：“描述式赞赏”\u003c/p>\u003cp>——————————————————————————————————————————————————————\u003c/p>\u003cp>做完这些练习后,你可能更明白孩子对“评价性”的赞赏有什么反应:\u003c/p>\u003cp>“你是个好孩子。”\u003c/p>\u003cp>“你是个很棒的演员。\u003c/p>\u003cp>“你终于变成优秀学生了。\u003c/p>\u003cp>“你真体贴人。”\u003c/p>\u003cp>你也同样清楚了孩子对“描述性”的赞赏有什么感受:\u003c/p>\u003cp>“我看见你自己穿上了T恤衫,标签朝后;你拉上了裤子的拉锁:两只袜子还是同一双的,穿好了鞋。你做了这么多事,多不容易啊!“\u003c/p>\u003cp>“你是个雍容华贵的女王!站在那里,显得高大挺拔,你讲话的时候,声音响彻整个剧场。”\u003c/p>\u003cp>“看来你最近在功课上下了不少功夫。我注意到你的作文有老师的评语,你的报告也提前交了,你还找到了自学单词的方法。”\u003c/p>\u003cp>“我喜欢这些黄气球和红心。让我很受安慰。看到这些,我觉得病好多了。”\u003c/p>","explains":"\u003cp>好的，我看到大部分小伙伴已经读完了。没读完的也关系，下面听我讲解就好。\u003c/p>\u003cp>首先第一个问题，这个拆页讲的是什么？\u003c/p>\u003cp>\u003cstrong>【what】\u003c/strong>\u003c/p>\u003cp>拆页讲的是~？（互动）学习者：赞美！\u003c/p>\u003cp>讲的是评价式赞赏和描述式赞赏。\u003c/p>\u003cp>\u003cstrong>【概念对比强化讲解】\u003c/strong>\u003c/p>\u003cp>那么应该如何理解者两个词呢?举个例子啊， 像“挺好”，“真美”，“太妙了”，“多美”，“太漂亮了”，“多好”等等词语，或者说我们原文里面有什么？“很棒&quot;，&quot;优秀&quot;，&quot;真体贴人&quot;等，这些呢都是评价词语，于此关联的就是评价式赞赏。\u003c/p>\u003cp>同样的还有什么？我们这个原文里面有什么？“我看见了你穿上了T恤衫”，“我喜欢这些黄气球和红心”等等,这些都是什么？（互动）学习者：描述。描述，对吧，描述你看的的事实并加以赞赏，就是描述式赞赏。\u003c/p>\u003cp>\u003cstrong>【案例辨析】\u003c/strong>\u003c/p>\u003cp>那么如何区分评价式赞赏和描述式赞赏呢？我们来举几个案例，各位伙伴帮我选择一下哪些是描述式赞赏，哪些是评价式赞赏？\u003c/p>\u003cp>1. 果果，我看到你刚才吃完饭以后，自己把自己的碗筷都洗了，我感到很高兴。\u003cstrong>描述\u003c/strong>\u003c/p>\u003cp>2. 果果，你的作业写的太好了！\u003cstrong>评价\u003c/strong>\u003c/p>\u003cp>3. 果果，你可真聪明！\u003cstrong>评价\u003c/strong>\u003c/p>\u003cp>4. 果果，你从7月1日到12日，一共写了753道数学计算题目，我感到很开心，因为这就叫努力!\u003cstrong>描述\u003c/strong>\u003c/p>\u003cp>5. 好棒！这就是我希望的！\u003cstrong>评价\u003c/strong>\u003c/p>\u003cp>6. 你是一个多么好的孩子啊！\u003cstrong>评价\u003c/strong>\u003c/p>\u003cp>7. 果果，今天去苏州旅游的时候，虽然天气很热，但是你一直跟在哥哥身后，没有抱怨。我感到很欣慰。因为这就是坚毅的性格。\u003cstrong>描述\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【how】\u003c/strong>\u003c/p>\u003cp>那么具体应该如何去做呢？这里我们一起来学习一下\u003cstrong>“描述式赞赏”\u003c/strong>\u003c/p>\u003cp>1.描述事实\u003c/p>\u003cp>描述你看见的具体的事实。比如：“你把自己的碗筷都洗了”“一共写了753道数学计算题目”。为什么一定要描述事实？因为事实是已经发生的，无法争辩的。会让你的表达充满自信，也让对方相信你。\u003c/p>\u003cp>2.说出感受\u003c/p>\u003cp>说出你对上面描述的事实带给你的感受。正确的表达自己，让对方也能理解你、感受你。\u003c/p>\u003cp>3.词语总结\u003c/p>\u003cp>用一个词语来总结。比如：努力，坚强，有决心等词语。对于孩子来说，他们可能学习过这些词语，但是这些词语究竟是什么样子他们还不理解。通过父母的总结，让孩子真正的理解这些词语的含义。同时，孩子会对照这些词语来不断鼓励自己。长此以往，孩子就会形成成长性思维。\u003c/p>\u003cp>\u003cstrong>【案例】\u003c/strong>\u003c/p>\u003cp>让我们回到开场的案例里面，我应该如何应用\u003cstrong>“描述式赞赏”\u003c/strong>？\u003c/p>\u003cp>1.描述事实\u003c/p>\u003cp>果果，我看到你得了6个优。同时我也看到了二年级下半学期每天都把白天上课的内容都复习了一遍。\u003c/p>\u003cp>2.说出感受\u003c/p>\u003cp>我感到很安心。\u003c/p>\u003cp>3.词语总结\u003c/p>\u003cp>这就叫做自律。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>各位可能会觉得这么做太麻烦了，用之前的做法多简单省事。事实上，不这么做会更麻烦。因为在类似的情况下没有用最妥善的的做法而带来的时间和精力的浪费，要严重的多……总之，虽然比较麻烦点，但是值得。\u003c/p>\u003cp>\u003cstrong>【Where】\u003c/strong>\u003c/p>\u003cp>这个方法主要是用于针对孩子做对事情的时候，来赞赏孩子的行为，培养孩子的自主性。不适用于成人之间的沟通。\u003c/p>","interaction":"\u003cp>相信通过上面的分享，大家已经初步掌握了“\u003cstrong>描述式赞赏\u003c/strong>”了。\u003c/p>\u003cp>各位伙伴可以想想一下，咱们可能遇到那些可以运用这个技巧的场景？假如未来一周或者一个月，如果要应用咱们今天所学的这个方法，将会是怎样的一个场景呢？\u003c/p>\u003cp>现在我们可以设计一个场景来应用学习。这个场景要以对话的形式呈现，要有时间、地点、人物、起因、经过和结果等元素。\u003c/p>\u003cp>大家可以先思考，然后把关键词句写在我给大家发的拆页后的表格里，大家独立完成，时间3分钟，现在开始。\u003c/p>\u003cp>OK，各位，时间到啊！那位伙伴来分享一下，张老师（张兮吾）来分享一下\u003c/p>\u003cp>张兮吾：我来分享一个\u003c/p>\u003cp>张兮吾：时间呢，可能是未来一到两周之内。地点应该是家里。人物应该就是我跟我孩子。\u003c/p>\u003cp>张兮吾：起因呢，就是我开始慢慢让他收拾东西嘛。他玩玩具，他会把所有的东西都摊开。摊开的到处都是，对吧。\u003c/p>\u003cp>张兮吾：我前一段时间，已经通过分解步骤的方式，让他掌握了就是收拾东西的一个技能。\u003c/p>\u003cp>樊昊魁：分步骤吗？\u003c/p>\u003cp>张兮吾：哎，就是分步骤嘛。就是你先把它堆在一块儿，然后把它放在篮子里，然后把它贴在墙边。\u003c/p>\u003cp>张兮吾：他这个怎么收拾东西已经会了。所以后面我就期待着他，那天，如果说有一天，我没有要求的情况下，他主动把玩具收好了。\u003c/p>\u003cp>张兮吾：那么这个时候，我就马上会冲到他面前，我跟他说：诶，爸爸刚才看到你主动在玩完玩具之后，在没有任何人的提醒之下，就把玩具收拾好了。爸爸感觉很欣慰，很开心。\u003c/p>\u003cp>樊昊魁：描述事实和说出感受。\u003c/p>\u003cp>张兮吾：你的这个行为让爸爸看到了自律和爱干净。\u003c/p>\u003cp>来，让我们掌声感谢张老师的精彩演绎。\u003c/p>\u003cp>\u003cstrong>【结语】\u003c/strong>\u003c/p>\u003cp>OK，今天咱们的学习就到这里。\u003c/p>\u003cp>现在咱们一起回顾一下今天所学内容\u003cstrong>“描述式赞赏”\u003c/strong>，分别三步是那三步？\u003c/p>\u003cp>第一步？（互动） 学习者： 描述事实\u003c/p>\u003cp>好！第二步？（互动）学习者：说出感受\u003c/p>\u003cp>第三步？（互动） 学习者： 词语总结\u003c/p>\u003cp>以上是我今日分享，最后祝愿各位伙伴，咱们孩子都拥有成长型思维。感谢大家的参与！谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1694421498000,"updated_at":1695006916000,"ria":true},{"id":16062,"topic":"谨防说太多的“不”","learn_goal":"","remark":"过级活动","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"包不娴","city":""},"club":{"name":"东莞乐享分舵","city":"东莞"},"prologue":"\u003cp>【自我介绍】：\u003c/p>\u003cp>各位亲爱的小伙伴,大家晚上好！我是包不娴，我今晚上分享分为四个部分，一是自我介绍，二是拆书帮介绍，三是拆书，四是总结。我是在嘉里顿大学呆了很久的家庭主妇。我这个名字是与我女儿包不乖有关，当时她还没上小学，听到我在给家人都各取了一个姓包的名字，她就突然福至心灵，说；妈妈，你要叫“包不闲”。闲是悠闲的闲。这几年我感觉虽也有忙忙碌碌，但有些是瞎忙，而且人贵有自知之明，我不是娴雅温良的女子，还是给闲加个女字旁好了，发音还是包不娴。\u003c/p>\u003cp>我现在给了自己一个标签，有时躺平有时挣扎，因为我觉得自己是需要臣服在当下的，这就是躺平，对能改变的事情我要努力去提升，这是挣扎。\u003c/p>\u003cp>【拆书帮介绍】\u003c/p>\u003cp>说到拆书帮我们就要先说拆书法。拆书法是一种针对成人学习，以提升学习能力，解决实际问题为目标导向的一种读书方法。这个拆字是有讲究，是通过ＲＩＡ三个步骤来实现的，R指的是reading，阅读原文，I是指 interpretation，表示我们对原文进行准确的阐述释意，A，Appropriation，是内化.是指将书中内容对照自身的经历进行反思，进行深度的内化，并且结合我们自身的实际需求，用于指导我们将来的行动。拆书法主要应于致用类书籍，但如果能力持续精进，就可以到达外物皆可拆的境界。\u003c/p>\u003cp>这样的一群志同道合的读书学习爱好者聚集在一起，就成了拆书帮。拆书帮是全国性的公益组织，在多个城市都有设立的分舵，还有独特的师徒制，大伙共同应用这种新的学习理念来读书，通过多场线上线下的拆书活动，可以让我们轻松交流，互相启发和促进，达到共同学习目的。\u003c/p>\u003cp>【过渡语】\u003c/p>\u003cp>那现在就由我来带领大家拆解一下今天的片段，主题是谨防说太多的&quot;不&quot;，来自被誉为“父母与孩子沟通的圣经”的这本----《如何说，孩子才会听，怎么听，孩子才肯说》。这本书出版至今已经40余年，至今长盛不衰。让我们花2分钟时间看一下原文片段，看完后在屏幕上面打个1示意我一下。\u003c/p>","ratings_count":1,"texts":[{"id":20144,"quote":"\u003cp>【R阅读原文拆页】2分钟\u003c/p>\u003cp>《如何说孩子才会听，怎么听孩子才会做》 P164-P166\u003c/p>\u003cp>谨防说太多的&quot;不&quot;\u003c/p>\u003cp>很多时候父母用生硬的&quot;不&quot;挫伤了孩子的热情，孩子会感觉这是对自己的攻击，他们会尽其所能来反抗。他们尖叫、发怒、骂人、不开心。他们质问父母：&quot;为什么不能？……你讨厌……我恨你！&quot;\u003c/p>\u003cp>即使最耐心的父母这时候都会生气。我们该怎么做？投降？还是凡事都说&quot;可以&quot;？很明显，凡事顺从是当然不行的，会让孩子变得专横霸道。还好，我们有方法帮助家长既坚定自己的立场，又不招致对抗。\u003c/p>\u003cp>代替说&quot;不&quot;的方法\u003c/p>\u003cp>A . 提示\u003c/p>\u003cp>孩子：我能去苏珊家玩吗\u003c/p>\u003cp>代替说&quot;不，你不能去。&quot;\u003c/p>\u003cp>给她摆事实。\u003c/p>\u003cp>家长：我们五分钟后就要吃饭了。\u003c/p>\u003cp>孩子得到这个提示，会对自己说：&quot;我猜我不能去。&quot;\u003c/p>\u003cp> B ．接纳感受\u003c/p>\u003cp>孩子：（在动物园）我现在不想回家。还能再玩会儿吗？\u003c/p>\u003cp>代替说：&quot;不，我们现在就得走。&quot;\u003c/p>\u003cp>接纳她的感受。\u003c/p>\u003cp>家长：我看出来你不愿意走，想玩很长很长时间。（带她离开的时候）玩得正高兴的时候，真不想离开。\u003c/p>\u003cp>有的时候，一个人的感受被接纳后，他的抗拒心理会减弱。\u003c/p>\u003cp>C ．描述问题\u003c/p>\u003cp>孩子：妈妈，现在能开车带我去图书馆吗？\u003c/p>\u003cp>代替说：&quot;不能，你得等会儿。&quot;\u003c/p>\u003cp>描述问题：\u003c/p>\u003cp>家长：我想带你出去。问题是电工半小时后就来了\u003c/p>\u003cp>D ．有可能的话，用&quot;是&quot;代替&quot;不&quot;\u003c/p>\u003cp>孩子：我们能去操场玩吗？\u003c/p>\u003cp>代替说：&quot;不行，你还没吃午饭呢？&quot;\u003c/p>\u003cp>用&quot;肯定&quot;代替：\u003c/p>\u003cp>家长：当然可以，吃完饭就去。\u003c/p>\u003cp>E . 给自己时间想想\u003c/p>\u003cp>孩子：我能在盖瑞家过夜吗？\u003c/p>\u003cp>代替说：&quot;不行，你上周刚去过。&quot;\u003c/p>\u003cp>给自己时间想想：\u003c/p>\u003cp>家长：让我想想。\u003c/p>\u003cp>这句话有两个效果：让孩子的坚持稍稍放缓（至少他知道自己的要求被认真考虑了），也给家长留出思考时间。\u003c/p>\u003cp>相比之下，说&quot;不&quot;显得简短，上面的叙述略显繁琐。但是，它比说&quot;不&quot;要更有效。\u003c/p>","explains":"\u003cp>I【重述知识点】5分钟\u003c/p>\u003cp>{What}\u003c/p>\u003cp>本拆页为如何巧妙拒绝孩子提供了一些应对思路和方法，避免了直接说“不！”。\u003c/p>\u003cp>日常生活中，有太多的机会会遇到孩子们向家长提出要求，有些要求一听就不合理，为了赶时间图省事，为了维护我们在孩子面前的权威，我们很有可能开口就是：“不行，你不能这样。”\u003c/p>\u003cp>{Why}\u003c/p>\u003cp>然而，这些过于爽快的&quot;不&quot;很可能会在孩子心中挫伤了他们的热情，令他们感觉到这是对他们的否定和攻击，会引发他们的反抗(有些青春期孩子被拒绝可能会反应很大），从而导致一轮争执与不开心，破坏了和谐的亲子关系。但我们也没有办法凡事都投降，凡事都说可以。\u003c/p>\u003cp>{How}\u003c/p>\u003cp>下面有一些方法可以帮助我们自己，既坚定自己拒绝的立场，又不招致孩子们的对抗。\u003c/p>\u003cp>就让我们拿常见的孩子要看电视，玩电脑等事情来对照书里的方法一一说明。\u003c/p>\u003cp>1.提示。孩子提要求之后，我们摆出一个与这个要求不能兼容的事实。\u003c/p>\u003cp>孩子：我现在不想睡觉，我还想看电视。\u003c/p>\u003cp>家长：明天周五，早上还得早起呢。\u003c/p>\u003cp>2.接纳感受。家长孩子双方都应该明白，不被同意的只是行为本身，但是孩子的感受家长是可以接纳并共情的。有时候一个人的感受被接纳后，他的抗拒心理就会减弱。\u003c/p>\u003cp>孩子：电视太好看了，我现在还想看。\u003c/p>\u003cp>家长：我看出来了，你觉得电视很好看，你想看很久，所以这时候是不愿意关掉的。\u003c/p>\u003cp>3.描述问题。先表达出对要求中合理的地方可以赞成，再说清楚与此矛盾的地方。\u003c/p>\u003cp>孩子：我看的是很有意义的视频，并没有在玩游戏。\u003c/p>\u003cp>家长：有意义的视频我不反感。问题是就这个月医生才说你的眼睛有一只近视的，要爱惜它，要滴眼药水，控制用眼时间。\u003c/p>\u003cp>4.有可能的话，用&quot;是&quot;替代“不”。用肯定的方法来婉拒当前的不合理请求。\u003c/p>\u003cp>孩子：我还要再玩一会平板。\u003c/p>\u003cp>家长：周未可以。你的Happy hour会在周末如约而至。\u003c/p>\u003cp>5.给自己时间想想。就是不立刻拒绝，也许孩子的要求有不合理部分，但是考虑到他有些特殊情况我们要想想。这么做有两个作用，一个是让孩子知道自己的要求被认真对待了；二也是给我们留出了思考时间来判断怎么对待他的请求，是否可以让步。\u003c/p>\u003cp>孩子：今天生病了不舒服，让我就多看一小会电视。\u003c/p>\u003cp>家长：让我想想。（视情况看是否同意或者父母找出其他的安抚之道)\u003c/p>\u003cp>{Where}\u003c/p>\u003cp> 在亲密关系，职场上或朋友之间，我们也可以衡量情况，适时使用。在紧急或危险的时候就不适用。\u003c/p>","interaction":"\u003cp>【A1联系具体经验】3.5分钟\u003c/p>\u003cp>今年春节，我和亲戚们带孩子坐一辆面包车回老家。一对夫妻和他们三岁的孩子笑笑坐在第二排，我带孩子坐在第三排。路上笑笑突然提要求说想坐第三排。她爸爸立刻就说：&quot;不行！这开着车呢，哪能换位置？&quot;笑笑就开始闹情绪，她妈妈说：“宝贝，这可不行，刚才上车你又不吭声，现在这全是山路没法停，我们还赶时间呢。”孩子听不进去，很快就大哭起来，夫妻两人都烦躁了，生气地批评她就是不听话，就是一个爱哭鬼。我当时对笑笑说；“让我猜猜你的想法:你以前还没试坐过面包车，没有坐过最后一排，所以想试一试，对吗？&quot;孩子马上点头了。我在后面轻轻搭住她肩膀，立刻同理她：&quot;是呀，面包车好新鲜，最后一排感觉挺好玩的，没有坐到，笑笑心里好遗憾啊！&quot;神奇的事情发生了，孩子当场就止住哭泣！我又想了想，再说：&quot;嗯，这里到西山不知道还开多久，如中途停车我们就能换座；就算不停，回程的时候我们就给笑笑把后座给预订上！&quot;笑笑对这个安排非常满意，很快的，车里又充满了孩子的欢笑。\u003c/p>\u003cp>现在回想起来，我是无意中有用了这个替代说“不”的技能点中的第2和4点，我第一时间同理了孩子并且尝试给出了一个延迟满足的方案。孩子父母虽然也有用到技能点1提示来“摆事实”-----山路不能停车及赶时间等，但因为他们先说了&quot;不行&quot;，引发了孩子的不满，孩子因为年纪小不理解不让换座的原因，家长也没办法同理孩子感受，只希望孩子马上听话，导致他们的说辞就不被孩子所接受。\u003c/p>\u003cp>拒绝的方法是需要我们活学活用的，并不是要一次性使上全部的方法，需要我们看当时的情况，灵活挑选，结合孩子反应，单独或者联合使用。\u003c/p>\u003cp>【A2具体应用】3分钟\u003c/p>\u003cp>我自己在日常生活中经常出于图省事，也常给孩子直接说“不”，还期待她能快速遵守。但我女儿不是传统意义上的乖乖女，日复一日，会影响我们的亲子关系。有时我给她开了绿灯，又会为我没原则妥协而懊恼。我准备做下面的计划，用替代说“不”的方法来婉拒孩子。\u003c/p>\u003cp>1.预判：对孩子说不的情形，我预判多数都会集中在她要求玩电子产品和吃零食的时刻。这些时候我要先从心理上特别留意。如果我没有提前想好应对，到时一有状况我就容易进退失据。晚上有时孩子会耍赖要吃零食，我需要用到综合技巧1，2和4，比如说“你很想吃这个蛋糕，它看起来味道不错让你心动。晚上10点多了你肠胃都好想休息不干活了；妈妈明白，想克服自己的”很想要吃”的感觉是不容易的，我们需要在一个合理的时间段来吃：明天一早就来吃它！”我相信这样说，比“这都几点了？就是不能吃!你太馋了”会让她更容易接受。\u003c/p>\u003cp>2.替代说“不”需要有时时刻刻的觉知，我各写一个少说“不”的便签纸在贴客厅和厨房，以便提醒自己。\u003c/p>\u003cp>3.下一周开始定个小目标。我想对女儿直接说“不”，但是又使用了技能点控制住，这样情形如果达到三次，我就奖励自己逛淘宝一下午。\u003c/p>\u003cp>4.同时注意到使用技能点之后孩子的反馈，以精进自己的技巧。\u003c/p>\u003cp>【结束语】0.5分钟\u003c/p>\u003cp>最后总结一下今天的拆书.直接说“不’，是容易且简短有力的，上面各种替代应对略显繁琐，但对于成长中的孩子，有技巧的拒绝，不伤亲子关系，并能引发他们自己的思考和选择是更重要的。\u003c/p>\u003cp>我今天的分享就到此结束了，希望这个片段会对各位小伙伴有一点小帮助或启发哦！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1686898132000,"updated_at":1687262074000,"ria":true},{"id":16002,"topic":"用心倾听，畅享亲子沟通","learn_goal":"","remark":"如何开启孩子的心灵世界？\n\n如何与孩子达成美妙的交流沟通？\n\n如何让孩子在您的引导下身心健康发展？\n\n拆书家宋海兰将讲解实用有效的方法，帮助你和孩子建立起一个能够快乐交流的平台，使孩子变得愿意与父母配合！","level":"TF2-3","duration":25,"status":30,"type":0,"chaishujia":{"username":"海兰","city":"北京市"},"club":{"name":"北京城市之光分舵","city":"北京市"},"prologue":"\u003cp>\u003cstrong>开场\u003c/strong>：\u003c/p>\u003cp>大家好！按照惯例先做个自我介绍，我叫宋海兰，三个标签介绍自己：课程研发者（目前从事的工作），自媒体人（运营公众号），终身学习者（所有的幸运都是不断学习带来的）\u003c/p>\u003cp>给大家说明一下今天我不是教给大家如何育儿，而是给大家分享一种沟通技巧，这个技巧是从一本亲子类的书籍学到的，实践后效果很好，所以给大家分享。\u003c/p>\u003cp>\u003cstrong>图书介绍\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【F】\u003c/strong>\u003c/p>\u003cp>今天我的拆页来自书籍《如何说孩子才会听 怎么听孩子才肯说》，主要讲述了一种让孩子听话的神奇语言，这种爱的语言使孩子很容易接受您的要求和忠告。 作者是美国的阿黛尔·法伯和伊莱恩·玛兹丽施，她们是国际著名亲子沟通专家。\u003c/p>\u003cp>\u003cstrong>【A】\u003c/strong>\u003c/p>\u003cp>本书不像同类某些书籍只讲理论，本书内容是她们在创办的学校和研究所，长期与父母们用自身的实践总结提炼，并且这些方法非常行之有效。因此被译为30多种文字风靡全球20年畅销不衰。\u003c/p>\u003cp>\u003cstrong>【B1】：\u003c/strong>两位杰出的教育专家提供的互相尊重而又切实可行的沟通方法，使得父母与各年龄段孩子的关系更加轻松而有质量，本书因此受到来自世界各地父母和专家热情洋溢的赞美。的的确确能缓解所有年龄段孩子与父母的紧张关系，带来父母与孩子的合作。如果在线上的爸爸妈妈们目前正遇到了一些和孩子之间的沟通合作问题，推荐你们看看这本书。\u003c/p>\u003cp>【\u003cstrong>B2\u003c/strong>】 听到这里大家可能会感到奇怪，我没有孩子为什么会来跟大家分享一本亲子类的书籍呢？这也正是这本书神奇的地方。我通过看这本书，从中找到了今天的拆页，通过这个拆页帮助我解决了成人之间的沟通问题，学会了如何有效倾\u003c/p>\u003cp>听。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>在跟随我完成本次倾听技巧学习后，学习者能够在家人/朋友/同事等在遇到困难时，能利用全神贯注、简短应答和反馈感受者三步进行有效倾听，从而帮助对方找到解决的方法。\u003c/p>","ratings_count":2,"texts":[{"id":20076,"quote":"\u003cp>\u003cstrong>R原文片段：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>倾听三步曲\u003c/strong>\u003c/p>\u003cp>庆幸的是这位父亲刚刚参加了“如何帮助孩子面对他们的感受”的讲座，下面是发生在他家里的真实情形：\u003c/p>\u003cp>儿子：我真想打迈克尔一巴掌！\u003c/p>\u003cp>父亲:孩子，你生气了？\u003c/p>\u003cp>儿子：我真想狠狠地打他那张肥脸！\u003c/p>\u003cp>父亲：你这么生他的气啊？\u003c/p>\u003cp>儿子：你知道那个坏家伙干了什么吗？在车站他无缘无故抢走我的笔记本，扔到了垃圾箱里！\u003c/p>\u003cp>父亲: 嗯！\u003c/p>\u003cp>儿子：我猜他怀疑是我在美术教室把他捏的鸟弄碎的。\u003c/p>\u003cp>父亲: 你这样想啊。\u003c/p>\u003cp>儿子：是啊。他哭的时候，一直盯着我。\u003c/p>\u003cp>父亲：哦！\u003c/p>\u003cp>儿子：但不是我弄碎的。真的不是我。\u003c/p>\u003cp>父亲：你知道不是你。\u003c/p>\u003cp>儿子：我不是故意的，那个蠢德比把我推到在课桌上的时候，我根本没办法。\u003c/p>\u003cp>父亲：德比推了你。\u003c/p>\u003cp>儿子：是啊。好多东西都掉地上了，但只有那个鸟碎了。我没有故意摔碎它，他捏的鸟艇好的。\u003c/p>\u003cp>父亲：是，你真的没有故意弄碎它。\u003c/p>\u003cp>儿子：没有，但他不相信我。\u003c/p>\u003cp>父亲：你觉得你告诉他真相，他也不会相信你吗？\u003c/p>\u003cp>儿子：我。。。我应该告诉他，不管他信不信。我觉得他也应该向我道歉，不该把我的本子扔到垃圾箱里。\u003c/p>\u003cp>这位父亲很惊讶地发现，他并没有提任何问题，孩子竟然把事情的原委都告诉了他。他也没有给孩子任何建议，孩子自己就找到了解决方法。他甚至不敢相信，他只是倾听孩子说话、回应他的感受，就对孩子有这么大的帮助。\u003c/p>","explains":"\u003cp>\u003cstrong>拆书家讲解引导：\u003c/strong>\u003c/p>\u003cp>看完的小伙伴可以举手示意我。没看完也没有关系，可以来跟着我的节奏共同来学习\u003c/p>\u003cp>\u003cstrong>What：\u003c/strong>拆页片段主要讲述了全身心倾听三部曲：全神贯注、简短应答和反馈感受，从而帮助对方找到解决的方法。\u003c/p>\u003cp>\u003cstrong>Why：\u003c/strong>\u003c/p>\u003cp>生活中沟通无处不在，我们会有以下的困惑\u003c/p>\u003cp>当朋友向你表达自己和家人吵架的时候，你直接批评不应该吵架搞得对方很不高兴；或者配偶给你反馈闺蜜不搭理自己时，你则让其反思自己不足从而导致夫妻吵架\u003c/p>\u003cp>又或者同事给你讲工作中遇到困难时，你直接让对方想想办法从而导致同事关系不融洽\u003c/p>\u003cp>\u003cstrong>How\u003c/strong>\u003c/p>\u003cp>如何做到全身心倾听呢？只需要三步\u003c/p>\u003cp>\u003cstrong>第一步：全神贯注\u003c/strong>\u003c/p>\u003cp>遇到问题我们需要做两点：\u003c/p>\u003cp>1、态度：用认真的态度去对待，从内心深处重视起来。并避免自己的内心受到其他外界环境的干扰。所谓一心不能二用\u003c/p>\u003cp>2、行动：用行动来证明对这件事情的重视。比如用眼睛看着对方的眼睛。\u003c/p>\u003cp>总之，不要一边做自己的事情一边倾听。一起坐下来，没有外界因素的干扰，用心聆听对方的诉说。\u003c/p>\u003cp>\u003cstrong>第二步：简短应答：\u003c/strong>\u003c/p>\u003cp>当回应对方时为了避免打断对方的思路，让他们把想说的话表达完整。我们可以使用，例如：嗯、、这样、、、原来十这样、、不容易打断他们的思路，让他们把话说得更完整，真正把自己的感受表达清楚。\u003c/p>\u003cp>\u003cstrong>第三步：反馈感受：\u003c/strong>\u003c/p>\u003cp>说出他们的感受。例如“这件事让你很难过！”如果不是很肯定，就用疑问的语气，让对方来确认我们是否理解正确。通过这种方式，让对方感受到我们是理解他的。给予了他心灵的力量，他自然就能找到解决问题的办法。\u003c/p>\u003cp>\u003cstrong>where\u003c/strong>\u003c/p>\u003cp>无论当我们遇到困难，或者身边的亲人、朋友和同事遇到困难时，都可以使用这个方法有效倾听\u003c/p>\u003cp>\u003cstrong>通过案例分享，希望大家对方法有了进一步的认识。\u003c/strong>\u003c/p>\u003cp>接下来说说我最近的一次经历。看看大家能不能更进一步的去使用这个方法。\u003c/p>\u003cp>事情发生在今年的夏天，我同事小郭哭着给我说同事小张故意用水倒在自己手机上，她说自己很想打小张一顿，\u003c/p>\u003cp>我用了今天所学的倾听三步曲：全身贯注，简短应答和反馈感受和小郭受沟沟通；我找了一间会议室，放下手机，真诚地看着小郭说\u003c/p>\u003cp>我：你这么生他的气\u003c/p>\u003cp>小郭：你知道她都干了什么吗？把一杯水直接倒在我手机上\u003c/p>\u003cp>我：嗯！\u003c/p>\u003cp>小郭;我猜她怀疑是我故意打翻了她桌子上的水杯从而弄湿了她的手机\u003c/p>\u003cp>我：你这样想啊\u003c/p>\u003cp>小郭：是啊，她看了一眼自己在水中的手机，之后把水倒在我手机上\u003c/p>\u003cp>我：哦\u003c/p>\u003cp>小郭：但不是我故意打翻她水杯的，是被其他同事不小心撞了一下从而碰倒了她水杯\u003c/p>\u003cp>我：别人撞的你\u003c/p>\u003cp>小郭：是啊\u003c/p>\u003cp>我：你没有故意洒水在小张手机上\u003c/p>\u003cp>小郭：没有，但是小张她不相信\u003c/p>\u003cp>我：你觉得你告诉她真相，她也不会相信你吗？\u003c/p>\u003cp>小郭：我。。。我应该告诉她，不管他信不信。我觉得她也应该向我道歉，不该用水故意倒在我手机上\u003c/p>\u003cp>结果太神奇了我只是倾听小郭的话、回应他的感受我没有给任何建议，小郭竟然告诉我了事情原委并且找到了解决方案\u003c/p>","interaction":"\u003cp>\u003cstrong>A学习者拆为己用：学习者拆为己用：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计\u003c/strong>\u003c/p>\u003cp>我的经历是不是让大家对方法有了更深的理解？所谓实践出真知。接下来我给大家提供一个场景，我们可以通过练习去学习如何全身心倾听：\u003c/p>\u003cp>下班前老张和小王因为一件小事吵起来，刚好被领导看见，被领导叫道办公室一顿批评，老张拖着一身疲惫回到家，妻子小李准好丰盛得晚餐等他共用晚餐，吃饭时妻子小李发现一向健谈得老张竟然没有言语。这时，妻子小李该如何用倾听三步法来进行解决问题\u003c/p>\u003cp>\u003cstrong>分组：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>大家进行小组讨论：然后选一个代表利用今天所学的倾听三步曲说出小组的解决方案\u003c/strong>提醒大家：三步是：全神贯注，简短应答和反馈感受。\u003c/p>\u003cp>给大家5分钟的时间。\u003c/p>\u003cp>5分钟后，邀请小伙伴来进行分享\u003c/p>\u003cp>接下来下来我们邀请一个代表分享小组的解决方案，提示一下不超过5分钟。\u003c/p>\u003cp>感谢伙伴的分享的解决方案\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>安卓组丽丽分享解决方案如下：\u003c/p>\u003cp>听了老张的按照今天所学的倾听三步曲\u003c/p>\u003cp>\u003cstrong>全身贯注：\u003c/strong>看着对方，表示自己态度上在用心倾听对方说话，行动上妻子放下手机关掉电视，有独立空间，倒杯水，\u003c/p>\u003cp>简短应答：老张在表达情绪的时候，妻子给老张回应：比如说你现在是很生气？他（小王）这样做你觉得不太舒服？给予情绪的回应，在老张讲事实和故事的时候给老张一些“嗯”，“啊”给与在听他表达的回应，帮助老张更好的说下去。如果老张没怎么说清楚或者没有捋清楚的地方妻子小李帮他重复一下他所要表达的意思。把事情倾听完整。\u003c/p>\u003cp>\u003cstrong>反馈感受：\u003c/strong>老张表述完事情后，他会想一些解决方案，他想要一个结果。你想这样做？老张你觉得这样做小王会理解你对吗？\u003c/p>\u003cp>\u003cstrong>1分钟\u003c/strong>\u003c/p>\u003cp>\u003cstrong>结束语：\u003c/strong>\u003c/p>\u003cp>今天我们一起学习了倾听三部曲。让我们再次来回顾一下，三个步骤，全神贯注；简短应答和反馈感受。只有倾听，才能正确的了解别人的感受和需要，才更能达到有效的沟通。好的，我的分享到此结束。谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1686373116000,"updated_at":1687734612000,"ria":true},{"id":15927,"topic":"如何帮助孩子客服依赖心理","learn_goal":"","remark":"依赖性很强的孩子会缺乏自信和独立性。\n如果不及时纠正会发展成“依赖性人格陪碍”，严重的话时常会感到抑郁。焦虑，影响身心健康。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"朱齐琳","city":"镇江市"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>大家好，我是朱齐琳，朱元璋的朱，整整齐齐的齐，王字旁双木林，名字里的齐字是父母希望我能文武双全，现在的我虽不是文武双全，但却身兼数职。\u003c/p>\u003cp>我有三个标签：\u003c/p>\u003cp>1、创业者，线上经验7年护肤品淘宝店，5年前自考化妆品配方师助理证书，是个会看护肤品成分的护肤达人。帮助超过500位小伙伴养成科学护肤的好习惯，线下经营一家小型泰餐厅店主，主要负责店铺运营、客户维护以及后厨问题收集反馈。\u003c/p>\u003cp>2、两个孩子的妈妈。\u003c/p>\u003cp>3、兼职文案写手，懂得文案底层逻辑，能快速提炼产品超级卖点，擅长护肤品朋友圈短文案、未来我计划从兼职文案转到线上全职文案写手，实现左手码字，右手财务自由。\u003c/p>\u003cp>在这之前有必要先给大家介绍一下拆书、拆书法和拆书家。\u003c/p>\u003cp>拆书是运用RIA的便签学习法。\u003c/p>\u003cp>RIA便签分别是\u003c/p>\u003cp>R:学习者阅读拆书家提供的拆页片段\u003c/p>\u003cp>I:拆书家用自己的话重述拆页内容并引导学习者更好理解拆页内容。\u003c/p>\u003cp>A: 用所学的知识关联到生活工作中，应用规划未来的行动。\u003c/p>\u003cp>A分为A1,A2,A3\u003c/p>\u003cp>A1:激活学习者经验；\u003c/p>\u003cp>A2:催化学习者应用；\u003c/p>\u003cp>A3:促动学习者现场演练。\u003c/p>\u003cp>拆书法分为个人学习法和组织学习法\u003c/p>\u003cp>就个人而言非常适合成年人提升个人能力和解决问题。\u003c/p>\u003cp>组织学习者也就是拆书家，他们还是学习促进者，能把一本书里的知识点加工拆成一堂课现场讲解，整个过程如同一场培训，能很好的促进和引导学习者把知识消化为己用。\u003c/p>\u003cp>“拆书帮”是把一群会拆书的学习爱好者聚集在一起，在全国各地都有拆书帮分舵，是非莹利性青年自组织。\u003c/p>","ratings_count":2,"texts":[{"id":20016,"quote":"\u003cp>片段来源《如何说孩子才会听，怎么听孩子才肯说》\u003c/p>\u003cp>微信电子书版：P982-983\u003c/p>\u003cp>原文：\u003c/p>\u003cp>要克服依赖心理，可从以下几个方面着手帮助孩子。\u003c/p>\u003cp>1．要纠正孩子平时养成的依赖习惯，提高孩子的动手能力\u003c/p>\u003cp>教导他多向独立性强的同学学习，不要什么事情都指望别人，遇到问题要做出属于自己的选择和判断，加强自主性和创造性。\u003c/p>\u003cp>2．要帮助孩子在生活中树立行动的勇气，恢复自信心\u003c/p>\u003cp>自己能做的事一定要自己做，自己没做过的事要锻炼做。\u003c/p>\u003cp>3．丰富孩子的生活内容，培养其独立生活能力\u003c/p>\u003cp>让他们在学校中主动要求担任一些班长级工作，以增强主人翁的意识。使他们有机会去面对问题，能够独立地拿主意、想办法，增强自己独立的信心。在家里，让孩子该干的事要自己去干，如穿衣、洗碗、打扫卫生等，不要什么都推给爸爸妈妈，做个“小地主”。\u003c/p>","explains":"\u003cp>\u003cstrong>what：\u003c/strong>\u003c/p>\u003cp>这个片段告诉家长该如何克服孩子的依赖心理，给出了3个有效培养孩子独立性的方法。\u003c/p>\u003cp>我发现身边有很多妈妈对孩子照顾得无微不至，连孩子每天要写什么作业、第二天要带什么书、班级群里打卡都会帮孩子安排好，甚至连穿什么衣服也根据自己的喜好来帮孩子决定。\u003c/p>\u003cp>你会发现孩子对你越来越依赖，无论大小事都想着妈妈会帮忙做好，遇到问题第一时间也是抛给妈妈。\u003c/p>\u003cp>\u003cstrong>why:\u003c/strong>\u003c/p>\u003cp>但家长的面面俱到只会让孩子的依赖性更强，你知道吗？依赖性很强的孩子会缺乏自信和独立性。\u003c/p>\u003cp>在学校中，依赖性很强的孩子，学习上希望老师能对他们提出要求，给出解决问题的思路。\u003c/p>\u003cp>长期下来孩子就缺乏独立思考的能力，在家中孩子会认为妈妈说什么都是对，出了社会孩子觉得无论发生什么事，都是自己的错。\u003c/p>\u003cp>如果不及时纠正会发展成“依赖性人格障碍”，离开父母和学校，独立生活和工作会觉得压力很大，严重的话时常会感到抑郁、焦虑，影响身心健康。\u003c/p>\u003cp>家长们，爱孩子最好的方式就是让孩子早早学会独立。\u003c/p>\u003cp>\u003cstrong>how：\u003c/strong>\u003c/p>\u003cp>我们可以从以下3方面来克服孩子的依赖心理，在生活中慢慢养成独立解决问题的习惯。\u003c/p>\u003cp>第一 ：减少依赖:\u003c/p>\u003cp>要纠正孩子平时养成的依赖习惯，提高孩子的动手能力。\u003c/p>\u003cp>多跟独立性强的同学学习方法，学会自己找方法来解决问题，遇事先让孩子自己做决定，比如选择喜欢款式的衣服。\u003c/p>\u003cp>第二：建立自信:\u003c/p>\u003cp>要帮助孩子在生活中树立行动的勇气，恢复自信心。\u003c/p>\u003cp>会做的事情要让孩子自己做，从来没做过的事情在保证安全的前提下，让孩子试着动手完成，比如孩子自己动手做蛋糕、切水果、取快递。\u003c/p>\u003cp>第三：解决问题:\u003c/p>\u003cp>丰富孩子的生活内容，培养其独立生活能力。\u003c/p>\u003cp>鼓励孩子在学校积极主动帮老师干活，遇到问题让孩子先做决定，但千万不要代替孩子来做这件事，找机会让孩子面对难题，家里的家务可以安排孩子来做，父母不要包揽。\u003c/p>\u003cp>\u003cstrong>where：\u003c/strong>\u003c/p>\u003cp>这三个方法适合家长与孩子之间，同样适合教育者和学习者之间，遇到依赖性特别强的学生，可以通过这三个方法来引导锻炼学生的独立性以及独立思考的能力。也可以让独立性强的学生和依赖性强的同学多交流分享经验。\u003c/p>","interaction":"\u003cp>A1联系具体经验：\u003c/p>\u003cp>和大家分享一个我自己的真实经验。按照这三个方法来锻炼孩子的独立性。\u003c/p>\u003cp>我从女儿出生3个月（2014年11月)就开始创业，那时候我也知道平时能帮孩子解决问题的时间不多，更别说能帮他们做事，所以我更多的重心是培养孩子自己解决问题的能力，一来父母也轻松，二也能培养孩子的独立能力。\u003c/p>\u003cp>妞妞（我女儿小名），现在是三年级学生，一年级入校的时候就加了班级群以及还有一个学习群是我帮她报的叫叫阅读课。\u003c/p>\u003cp>建群的前一周妞妞的作业和打卡视频都是由我来拍然后发到这两个群里去，由于我工作开始忙碌起来，我决定让妞妞自己去打卡发群，包括群内的作业通知也自己记录和查看。\u003c/p>\u003cp>叫叫阅读的打卡会麻烦一些，我把流程告诉她，让她按照这个流程做就行。\u003c/p>\u003cp>我把线上和线下课打卡步骤流程告诉女儿，目的就是为了让她对我“减少依赖”。\u003c/p>\u003cp>剩下的就是放手让她自己执行，我从来没有去检查她的作业情况，妞妞也很有信心能完成好这些事，我不定期打开群消息，都会看到妞妞认真打卡的痕迹，以及不漏掉每一条老师发来的信息。\u003c/p>\u003cp>我不去过问她打卡情况，其实就是在帮助她“建立自信”，偶尔抽查发现孩子确实能完成很好。\u003c/p>\u003cp>在生活中，只要买和孩子有关的东西（文具、衣服、蛋糕、生活用品等）我都会让他自己做决定是否要购买。\u003c/p>\u003cp>前天去商场看到一条我认为很漂亮的裙子，当时第一反应就是打视频给妞妞看，问她是否喜欢这个款式，妞妞不喜欢我就换另一个款式给他选。\u003c/p>\u003cp>妞妞告诉我她不想买这条裙子，我问为什么？她说因为每天穿校服，很少能穿上裙子，所以没必要浪费钱购买了。\u003c/p>\u003cp>其实这样的场景经常发生，可以锻炼孩子“解决问题”的能力，孩子思考是否真正需要，已经有自己独立思考的能力，不需要我帮她来做决定。同时我也很尊重她的决定。\u003c/p>\u003cp>接下来我也放手让妞妞接受更多挑战，做一些之前没做过的事情，让她在这个过程中学会总结经验。\u003c/p>\u003cp>家长们，要相信“相信”的力量，孩子就是盲盒，你不期待就是最好的期待。\u003c/p>\u003cp>A2具体应用：\u003c/p>\u003cp>马上快放暑假，2023年8月2日-2023年8月20让妞妞到我的店里帮忙打包外卖和核对订单。趁着假期我用书中的三个方法制定计划加强锻炼我女儿的独立性。\u003c/p>\u003cp>1．减少依赖\u003c/p>\u003cp>让女儿帮忙店内打包外卖，提升动手能力\u003c/p>\u003cp>2．建立自信\u003c/p>\u003cp>告诉女儿虽然这件事她没做过，但她一定没问题，帮她树立信心。\u003c/p>\u003cp>3．解决问题\u003c/p>\u003cp>每个外卖订单我只看不说，所有的特殊备注让女儿自己来处理，锻炼她独立处理问题的能力。\u003c/p>\u003cp>18天的外卖打包工作给她不一样的体验也锻炼了她独立处理问题的能力，我也会给女儿相应的报酬，让她知道只有付出才有收获，把自己赚来的钱由她自己合理分配。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1685688524000,"updated_at":1686535073000,"ria":true},{"id":15595,"topic":"帮助孩子面对他们的感受","learn_goal":"","remark":"帮助孩子面对他们的感受","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"拆书家十八","city":"贵阳市"},"club":{"name":"贵阳黔灵分舵","city":"贵阳"},"prologue":"\u003cp>目标：设定学习目标。要求：可观察/可测量的行为或动作\u003cbr>在跟随我完成本次RIA现场学习后，学习者能够情景重现一次他人在表达难过，伤心等负面情绪时自己做的不到位的一件事，并且学会用尊重感受的方法做到不评价，不给建议，逐步舒缓他人的负面情绪，双方顺利完成沟通或者就此事达成意见一致，甚至找到解决方案。\u003cbr>\u003cbr>\u003cbr>【开场】爱学习，爱分享的伙伴们大家好，欢迎大家参加本次RIA现场学习，我是一级拆书家杨朵，大家可以叫我十八，医美设计师是我的职业，成为孩子亦师亦友，引以为傲的母亲是我终生学习的原动力。\u003cbr>\u003cbr>【分组】希望本次RIA现场学习后，各位能够学会运用尊重感受的方法，舒缓他人的负面情绪，为了方便学习过程中充分交流讨论，我们来进行一下分组。今天有位小伙伴到场，我们就3人一组。谢谢！\u003cbr>\u003cbr>【用FAB法介绍图书。要求：清晰辨别出F、A、B】\u003cbr>下面我先来介绍一下我今天拆解的这本书《如何说孩子才会听 怎么听孩子才会说》。\u003cbr>【F】特征，核心是“书”，用于满足好奇心。\u003cbr>这是一本家教类的图书，本书就“尊重感受”“鼓励合作”“鼓励自立”“代替惩罚方法”“赞美方法”“角色中释放”6大问题提供了30个技巧，讲了如何与不同年龄段的孩子进行有效沟通，简单易行且有效。\u003cbr>\u003cbr>【A】优势，重点是“比较”，用于建立安全感。\u003cbr>与同类家教类图书相比，本书出版三十多年，被翻译成三十多种语言，销量累计位于美国家教类图书第一。与其他家教类图书相比，本书每一个方法都配有漫画，并且有以前的做法和新方法的场景模拟对比；与其他家教类图书相比，本书开篇作者直接给出了如何阅读本书的方法。\u003cbr>\u003cbr>【B】利益，强调的是“你（学习者）”用于引发兴趣。\u003cbr>B1：这本书给学习者带来的好处。\u003cbr>通过对本书的学习，可以帮助你解决家里每天因为吃饭，穿衣，学习等上演的亲子大战，可以缓解越来越陌生的亲子关系，学到代替惩罚的有效方法，怎样鼓励孩子自立，如何有效的赞美孩子，如何让孩子和你合作等沟通方法。\u003cbr>B2：拆页片段给学习者带来的好处\u003cbr>如果你的孩子或者朋友在向你述说一件事时突然说：算了，不说了，或者反而更加的闷闷不乐，甚至孩子大声哭闹，那么今天拆页的片段提供了尊重感受的方法（帮助孩子面对他们的感受的方法），就可以让你学会如何有效的帮助他们缓解负面情绪\u003c/p>","ratings_count":1,"texts":[{"id":19653,"quote":"\u003cp>【R】阅读原文\u003c/p>\u003cp>帮助孩子面对他们的感受（P27-P27）\u003c/p>\u003cp>孩子需要他们的感受被接纳和尊重\u003c/p>\u003cp>1.安静专心地倾听。\u003c/p>\u003cp>2.用简单的词语回应他们的感受。\u003c/p>\u003cp>“哦……嗯……原来是这样……”\u003c/p>\u003cp>3.说出他们的感受。\u003c/p>\u003cp>“这件事让你很灰心!”\u003c/p>\u003cp>4.用幻想的方式实现他们的愿望。\u003c/p>\u003cp>“真希望我能立刻把香蕉变熟了给你吃!”\u003c/p>\u003cp>所有的感受都应该被接纳,但某些行为必须受到限制。\u003c/p>\u003cp>“我看得出你很生弟弟的气。用嘴巴告诉他你将怎么做,而不是用拳头。”\u003c/p>","explains":"\u003cp>（看到大家都阅读完了，接下来我会进行片段内容的讲解。）\u003c/p>\u003cp>【what】:原文告诉我们帮助孩子面对感受的四个技巧，从而让孩子觉得自己被尊重，有利于进行有效的沟通。。\u003c/p>\u003cp>【why】:感受与行为有直接的联系，每个人都希望自己的情绪被他人理解和尊重，而人们大多数表现出的语言都是否定感受，给建议，心里分析，提问，讲大道理等\u003c/p>\u003cp>（不这么做的坏处）被他人不断的否定感受，不仅孩子会感到愤怒与困惑，大人同样会奔溃。在愤怒的状态时，听不进去任何建议，看法，更不会将注意力集中在如何解决问题上，而且情绪会影响判断和想法。\u003c/p>\u003cp>（这么做的好处）一旦他人觉得自己的感受被理解，负面情绪就会自行消退，达到顺利沟通，相互理解，彼此谅解，甚至共同合作。\u003c/p>\u003cp>【举个例子】（我说一个我自己的例子）反例\u003c/p>\u003cp>在今年4.22日时，我因为工作上的一件事情特别的生气，回家跟老公说起这件事情的时候，我老公就说:老板说什么就是什么了，听听就行了，就像我们的某某领导，她经常就是这样的。听到他这么说我就越发的生气，心想他一点都不理解我，真是没有共同话题，就生气的对他说：算了，不和你说了，没意思。\u003c/p>\u003cp>【HOW】:\u003c/p>\u003cp>那么如何让他人觉得你是在尊重他的感受，理解他，有以下几种方法\u003c/p>\u003cp>1、认真倾听：全神贯注的倾听他人的诉说，时不时的进行眼神的交流。\u003c/p>\u003cp>2、简答回应：用“嗯”“哦”“是这样”等简答的词语代替提建议和提问来回应他们的感受\u003c/p>\u003cp>3、幻想愿望：用幻想的方式代替逻辑上的解释\u003c/p>\u003cp>如：“真希望我是蛋糕师，现在就可以做蛋糕给你吃”\u003c/p>\u003cp>4、说出感受：用说出对方的感受方式代替否定感受\u003c/p>\u003cp>如：“这件事让你感到非常沮丧”\u003c/p>\u003cp>正例:\u003c/p>\u003cp>在学了这个方些技巧后，我就经常在和我儿子沟通的时候使用。记得特别清晰的一次，在小洋洋2岁4个月大时，一天我下班回到家，正和他玩小车车变火车，玩的正开心时，爷爷就逗他，拿走了他一个小车车。洋洋一下子特别的生气，边哭边打自己的头。奶奶在旁边着急的说:不能打头，他还准备继续这个打头的动作，\u003c/p>\u003cp>我（温和的对洋洋说）:宝贝,爷爷拿了你的车车你生气了？（说出孩子的感受）\u003c/p>\u003cp>他放下手，忍着眼泪说：是。\u003c/p>\u003cp>看他情绪没有那么激动了，我就接着说：爷爷其实是想和你一起玩，如果你不喜欢这样，你可以对爷爷说,爷爷你这样拿走玩具我会生气哦，而且生气也不可以打自己哦，知道了吗？洋洋说：知道了，妈妈。接着我们俩拥抱了一下，就开开心心的去玩了。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>这些方法可以单独使用，可以两两组合，多种搭配，可根据不同的场合多元化运用；\u003c/p>\u003cp>可以用于亲子沟通中，还可以在家人，朋友情绪低落时用来缓解他们的消极情绪，工作中下属因工作的压力情绪低落时，理解他的感受，逐步调整回工作状态。\u003c/p>","interaction":"\u003cp>拆书家提问设计】\u003c/p>\u003cp>【场景设计】\u003c/p>\u003cp>接下来呢，要请大家回想一下，你最近一周或一个月内，有没有这样的情形，他人向你诉说一件影响他情绪的事情，结果说到一半他就不说了，或者事后他仍然闷闷不乐，甚至情绪失控，比如：孩子对你说他的玩具坏了，学校里老师批评他了，朋友对你说她和爱人因为某件事吵架了等等，而你当时是如何回应的？\u003c/p>\u003cp>请大家仔细回想一下当时的场景，简单的写在便签上，并在小组内分享，每人大约一分钟的时间，每个人都要分享哦\u003c/p>\u003cp>（来回在小组内走动，倾听他们的分享）\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>1、分享者阿志：一个星期前，座位旁的同事向我抱怨老板不好，老板安排不合理等等，总之就是负面情绪的输出。我听了特别不舒服，还没等他说完，我就直接对他说：还好吧，本来他就是老板，谁让我们是打工的呢，你想开点等一堆大道理。同事生气的说：他还能把我开除了。就这样结束了本次对话。\u003c/p>\u003cp>2、分享者燕子：连续3天幼儿园的老师都在给我说：你儿子又打小朋友了，又不好好吃饭了等等，这些都是好久没有发生的事情了。昨天晚上和他心平气和的沟通，但是今天早上他又犯了以前的老错误，我直接把他揍了一顿，而且直接把他关在了门外边\u003c/p>\u003cp>【拆书家提问设计】\u003c/p>\u003cp>我听到了小伙伴们精彩的分享，现在请大家想一下，如果时光倒流，你再回到刚才分享的事件发生时间点，你会如何运用今天所学的尊重感受的方法来进行这次的谈话，请在便签上写下来，并在小组内分享，5分钟后我会邀请一位小伙伴来分享。\u003c/p>\u003cp>（提示：这些技巧有认真倾听，简单回应，说出感受，幻想愿望）\u003c/p>\u003cp>刚才听了阿志的分享特别的精彩，有请他用2分钟的时间分享一下。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>分享者阿志：如果同事向我抱怨老板，表达他的感受，我就会1、首先就是少说，不大打断他的话（认真倾听）；2、简单回应：恩，好像他是这样的；3、幻想愿望：买彩票中个500万，就直接抄老板的鱿鱼。4、说出感受：听到他这么说你感到很愤怒。\u003c/p>\u003cp>谢谢阿志的分享，从你的分享中我感受到了你的共情和尊重对方的感受\u003c/p>\u003cp>接纳他人的语言有助于提高我们的沟通效果，但是，我们不是天生就会说这种共情的语言，因此，需要我们通过一些新方法不断的强化练习来熟悉这种“新语言”，帮助孩子接纳他们感受的方法就是其中一种，希望大家回去以后多多使用，希望今天的学习对大家有所帮助，谢谢各位的聆听与陪伴。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1681617041000,"updated_at":1681618477000,"ria":true},{"id":15372,"topic":"如何让赞赏更走心","learn_goal":"","remark":"赞赏他人一个是我们日常生活里最常做的事，你会赞赏他人吗？你的孩子听到你的赞赏会有什么表现？有没有发现孩子跟你的互动越来越少？如果告诉你有一个简单的方法既能让赞赏变得更深得人心，想不想来了解一下呢？","level":"TF3-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"静Tina","city":"青岛市"},"club":{"name":"青岛五月风分舵","city":"青岛"},"prologue":"\u003cp>\u003cstrong>【开场】分钟\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【自我介绍】\u003c/strong>\u003c/p>\u003cp>大家好，我是张芳，一名屡战屡败屡败屡战的创业者，一名正在努力深造的全职妈妈，也是一名持续精进中的拆书家，很开心今天能跟大家一起来学习这篇主题为“如何让赞赏更走心”的拆页。我今天将要过的是TF3-2 ，用时大概是25分钟。\u003c/p>\u003cp>\u003cstrong>【分组】\u003c/strong>\u003c/p>\u003cp>按照今天到场人数我为大家分一下组，方便待会儿大家交流学习。我左手边两位老师为第一组，右手边两位老师为第二组。\u003c/p>\u003cp>\u003cstrong>【学习者场景法图书介绍】2分钟\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【场景】\u003c/strong>\u003c/p>\u003cp>在我们日常生活中时常会碰到这样的情况，孩子突然拿着取得很大进步的成绩单走到你面前，满含期待地等待你的回馈。你从孩子手中接过来成绩单，然后满意地拍拍他的肩膀说：“厉害！继续加油！”\u003c/p>\u003cp>或者孩子自己尝试独立地穿上了衣服穿鞋子，然后走到你面前得意地展示自己的“努力成果”，这时候正在追剧的你，转头瞄了一眼孩子，紧接着甩给他一句：“哇，你真棒！去玩吧！”然后继续追剧。\u003c/p>\u003cp>\u003cstrong>【提问】\u003c/strong>\u003c/p>\u003cp>你留意到孩子听到你的话后是什么反应了吗？他真的很开心满足吗？或者有没有发现孩子渐渐不再愿意跟你分享他的成绩与喜悦？那么遇到这些问题你通常会怎么解决？是不是从来没有考虑过从改变对他的赞赏方式作为突破口呢？\u003c/p>\u003cp>\u003cstrong>【影响】\u003c/strong>\u003c/p>\u003cp>虽然“厉害”“你真棒”之类的简单赞赏方式也会起到正面反馈的作用，但是用太频繁，孩子就会觉得你是在敷衍他，渐渐地孩子就会对被赞赏这件事失去兴趣。而且随着孩子年纪长大，他们甚至会觉得家长并不关心他们理解他们，从而变得不再愿意跟家长沟通。\u003c/p>\u003cp>\u003cstrong>【解决】\u003c/strong>\u003c/p>\u003cp>那么如何做到对孩子的赞赏不再单单浮于表面，能让孩子感到你的赞赏很走心呢？今天我给大家介绍一本被誉为育儿圣经的书---《如何说孩子才会听，怎么听孩子才肯说》，作者是阿黛尔法伯和伊莱恩马兹丽施，她们为读者提供了一些先建立尊重，在解决问题的交流沟通方式。而今天我们要一起拆解的片段也是选自这本书的一个沟通技巧，它给我们介绍了一种相比平时简单的赞赏更加走心的赞赏方式。\u003c/p>\u003cp>\u003cstrong>【学习目标】1分钟\u003c/strong>\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者在需要对别人进行赞赏的时候（界定），能够运用（行为）赞赏三步法先对他人的良好行为和自己的感受进行描述再归纳出优点（澄清）。\u003c/p>\u003cp>\u003cstrong>【A1量表自测】设计量表自测 1分钟\u003c/strong>\u003c/p>\u003cp>首先咱们一起做一个小测试，它会帮助大家了解自己平时都是怎么赞赏孩子的。请认真阅读以下五个小题目，大家根据自己的情况1到6分的标准来给自己打分，非常符合打6分，非常不符合打1分。给大家一分钟时间，现在开始。\u003c/p>\u003cp>\u003cstrong>【I解释量表自测意义】\u003c/strong>\u003c/p>\u003cp> 好，时间到了哈，这个测试只是一个参考，大家不要有心理压力，它是用来帮助带大家反观自己在赞赏孩子时的一些行为和内心世界。下面我想来问一下大家：\u003c/p>\u003cp>总分有高于25分的小伙伴请举下手。好，没有哈，\u003c/p>\u003cp>总分在10-25分的小伙伴请举下手。哇，好棒，有三名小伙伴，如果总分在这个区间内，说明你已经掌握了一些有效的表扬孩子的方法，那么相信通过今天的学习你一定会在表扬孩子方面有更多的认识和拔高。\u003c/p>\u003cp>那么剩下的应该就是低于10分的小伙伴了：好，如果你的分数低于10分，那么你一定是今天的分享中最大的收获者，可以在稍后的演练中多多参与，习得一种非常有效的赞赏孩子的好方法，来帮助自己的孩子建立强大的内心。\u003c/p>","ratings_count":1,"texts":[{"id":19421,"quote":"\u003cp>\u003cstrong>【R原文片段】（字） 1分钟\u003c/strong>\u003c/p>\u003cp>本拆页选自《如何说孩子才会听，怎么听孩子才肯说》的第185页。拆页主题是：如何让赞赏更走心。\u003c/p>\u003cp>下面请大家用1分钟时间阅读下手中的拆页，阅读完的小伙伴请抬头示意一下我。现在开始。\u003c/p>\u003cp>我必须承认，开始的时候，我对这种赞赏方式表示怀疑。即使已经见过一次效，我还是对它有些想法，为什么不用“太好了！……你真棒！太了不起了！”这种最自然的赞赏方式，而非要用另外的方法来描述我们内心的惊喜呢？\u003cbr>但是不管怎么说，我还是努力去尝试，起先我很严格的去做，结果不久之后，我注意到孩子真的开始赞赏他们自己。\u003cbr>我:（没有说：“吉利，你真了不起！”）你算出来打折的玉米罐头是一美元三个，比不打折的一捆玉米罐头实际上要贵很多。我真高兴。\u003cbr>吉利：（咧嘴一笑），我很聪明啊！\u003cbr>我：（没有说“安迪，你真棒！”）你把韦克尼太太这么复杂的电话留言都记下来了，写的也很清楚。我明白为什么明天的会议顺延了，我需要找谁，该告诉他们什么。\u003cbr>安迪：是啊，我是个很靠得住的孩子。\u003cbr>毫无疑问，孩子们越来越了解和认可他们的能力了，这给了我继续努力的动力。而且这的确是需要努力。真正看到孩子好的行为，去体验并且详细描述出来，总是比只说一句“你真棒！”要困难得多。\u003c/p>","explains":"\u003cp>\u003cstrong>【I拆书家讲解引导】5分钟\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【WHAT】\u003c/strong>\u003c/p>\u003cp>这篇拆页作者给我们介绍了两种赞赏方式。一种是用简单的评价性语言来对他人行为结果给于赞赏。另一种是针对好的行为细节进行描述并赞赏，也就是我们今天将要学习的赞赏三步法。\u003c/p>\u003cp>\u003cstrong>【和学习者简短互动】\u003c/strong>\u003c/p>\u003cp>现在请大家回过头再看一下拆页，我想请问大家两个问题：\u003c/p>\u003cp>1-拆页中括号里的赞赏方式属于评价是描述？\u003c/p>\u003cp> 学习者：评价\u003c/p>\u003cp>是的，这是一种简单评价结果和人的赞赏方式，没有描述细节，它只是通过评价来赞赏他人。\u003c/p>\u003cp>2-拆页中“你算出来打折的玉米罐头是一美元三个，比不打折的一捆玉米罐头实际上要贵很多。我真高兴。”这句赞赏属于描述还是评价呢？\u003cbr> 学习者：描述\u003c/p>\u003cp>非常正确，这是在描述，这句话里有对行为细节的描述，还描述了自己的感受。\u003c/p>\u003cp>\u003cstrong>【WHY】\u003c/strong>\u003c/p>\u003cp>用“你真棒”“真厉害”这样用简短的评价的语言对孩子行为的结果进行赞赏，时间久了会让孩子感觉我们的赞赏非常不走心，进而也就减少与家长在这方面的互动。\u003c/p>\u003cp>那么通过用描述细节的方法去赞赏则会让孩子在被赞赏的过程中学会辨识哪些是对的那些是错的。也避免了孩子养成非黑即白的极端思维模式。更容易让孩子感到被关注被理解，从而让孩子内心更有力量更加自信。\u003c/p>\u003cp>\u003cstrong>【HOW】\u003c/strong>\u003c/p>\u003cp>如何用描述来赞赏他人呢？我给大家总结了三步，也就是我们要学习的赞赏三步法：\u003c/p>\u003cp>1-描述事实：简单的描述自己看到的事实，或者之前孩子的行为。比如：我看到刚刚、、、、我注意到这几天、、、、\u003c/p>\u003cp>2-描述感受：表达自己对这个事实真实的内心感受，比如说：我觉得、、、、我感到、、、、\u003c/p>\u003cp>3-描述优点：总结下对方这样做的一个优点或者特点。比如：你这样就叫做：、、、、、当然如果对方可以自己总结出优点，那样更好，对自己的肯定是自信的第一步。\u003c/p>\u003cp>\u003cstrong>【WHERE】\u003c/strong>\u003c/p>\u003cp>这种赞赏的方法虽然出现在育儿书籍，但是同样可以用在成人间的赞赏，比如赞赏爱人，朋友，或者下属时也可以用到这种赞赏方式。\u003c/p>\u003cp>当然如果孩子或他人做了自己应该做的事的时候，我们可以把描述变成简单描述事实和自己的感受。比如孩子吃光了自己碗里的饭菜，你可以说：看到干净的碗，我真开心啊！\u003c/p>\u003cp>\u003cstrong>【举例】\u003c/strong>\u003c/p>\u003cp>上周末吃完饭，我把碗筷端到厨房去洗，出来后发现孩子正在拿着抹布擦桌子。我心里顿时感到非常的温暖，我蹲下来温柔地看着她说：“CC妈妈看到你在主动帮妈妈做家务（这是我在描述事实），妈妈心里好感动（这是我在描述我的感受），你真是个热爱劳动的好宝宝，谢谢你！”（这是我在描述孩子的优点）CC听我说完干得更起劲儿了，还跟我说：“妈妈，这是我应该做的。”从那以后每次吃完饭她都会拿着抹布去擦桌子，还主动去洗自己的袜子。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A学习者拆为己用】10分钟\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A3现场演练】场景设计、拆书家提问设计\u003c/strong>\u003c/p>\u003cp>好了，通过学习今天的拆页我们大概都掌握了怎样通过描述来赞赏他人，也就是赞赏三步法。接下来我们一起来做一个演练来巩固下，希望大家积极参与，从中获得更多的启发。\u003c/p>\u003cp>场景是这样的：小明同学要参加一个月后学校举行的团体踢毽子比赛，但是他现在还踢不好，他很担心因为自己的原因影响到班级总体成绩，于是每天早晨早起来练习踢毽子，一个月后的比赛他们班拿到了团体第一名，小明回到家第一时间跑到妈妈面前报喜，作为妈妈的你，会如何用今天学到的“赞赏三步法”来赞赏他行为呢？\u003c/p>\u003cp>各小组选出一名小伙伴做家长，一名小伙伴做小明，大家一起来演练一下，给大家5分钟时间，5分钟后我请一组小伙伴来给大家演练一下。没有参与演练的小伙伴可以在旁边观测下他们的演练是否有疏漏或者可以改进的地方，来帮助他们调整完善。好，现在开始。\u003c/p>\u003cp>\u003cstrong>【A3现场演练】学习者案例  1分钟\u003c/strong>\u003c/p>\u003cp>【学习者案例】：\u003c/p>\u003cp>好了，各位小伙伴看来都讨论的非常热烈，可惜我们的时间已经到了，稍后等我们分享完，各位小伙伴私下再来讨论。现在先请清栎这一组先来演练一下吧！\u003c/p>\u003cp>第一组:\u003c/p>\u003cp>清栎（妈妈），韩新波（小明）\u003c/p>\u003cp>韩新波：妈妈妈妈，我今天特别开心，今天我们踢毽子比赛我们班得到了团体第一名！\u003c/p>\u003cp>清栎：哇塞！这么厉害呀！你是怎么做到的呀！\u003c/p>\u003cp>韩新波：我每天都早起起来练习踢毽子，恐怕自己踢不好影响班级总成绩。\u003c/p>\u003cp>清栎：哦，我也注意到了，这几天你基本每天都早起踢毽子，那得到这么好的成绩那你有什么感受呢？\u003c/p>\u003cp>韩新波：我觉得特别自豪，为班级和团队贡献了自己的力量好开心！\u003c/p>\u003cp>清栎：是吧？很开心哈？妈妈也为你们取得团体第一名感到骄傲和自豪，你为了班级荣誉感，每天早起来坚持练习踢毽子，这就叫勤奋努力，而且有班级荣誉感，常吃以往，你一定会得到同学们的认可，你也会越来越有成就感的。\u003c/p>\u003cp>韩新波：嗯，我会继续努力的！\u003c/p>\u003cp>非常棒！大家为清栎组鼓一下掌！我发现一个非常好的点，就是清栎作为妈妈她用了引导式的语言来主动引导孩子去表达：比如“你是怎么做到的呢？”“你有什么感受呢？”然后再说出妈妈的感受，这是一个非常好的方法，这也让我学习到了，它是我们这次学习中的一个亮点，看来清栎已经赞赏三步法掌握得炉火纯青了。那么，我们请第二组的小伙伴来分享一下他们的演练吧！\u003c/p>\u003cp>第二组：\u003c/p>\u003cp>洁琼（妈妈），核桃（小明）\u003c/p>\u003cp>核桃：妈妈，我们学校举行的踢毽子比赛，我们班拿到了第一名呢！\u003c/p>\u003cp>洁琼：妈妈感到很骄傲，妈妈看到了你每天早起练习踢毽子，最后你们班拿到了第一名，你对这个结果有什么感受你呢？\u003c/p>\u003cp>核桃：我觉得特别开心，我坚持练了一个月的踢毽子才让自己有了很大的进步，从而才让我们班有了这样的好成绩，\u003c/p>\u003cp>洁琼：嗯，这也说明你是一个特别有责任心和集体容易感的孩子，妈妈相信以后你会把这种责任心和集体荣辱感的行为继续保持下去，以后你在做其他事情时也会有更好的结果的。\u003c/p>\u003cp>核桃：嗯，我会的妈妈！\u003c/p>\u003cp>洁琼：好，加油！\u003c/p>\u003cp>【互动】所以在场的小伙伴不管是不是家长， 有没有孩子，我想在未来在对自己的孩子教育方面都会学到很好的沟通技巧。\u003c/p>\u003cp>\u003cstrong>【A2】布置任务\u003c/strong>\u003c/p>\u003cp>我们今天的分享接近尾声了，最后为了让大家可以在生活中学以致用，我给大家布置一个小作业，大家在未来一周在遇到需要赞赏他人时，请尝试用描述来赞赏他人的方法，也就是我们今天学习的“赞赏三步法”来对他人的行为进行赞赏。并观察下对方听到你的赞赏后跟之前你赞赏他们的时候的反应有什么不同。\u003c/p>\u003cp>尝试用纸和笔，或者用手机来记录一下。完成作业后的小伙伴麻烦把你们赞赏别人时的具体时间，地点，人物，具体赞赏内容以及当时对方的反应通过微信方式发给我。大家一起讨论学习，争取能从中学到更多的东西。\u003c/p>\u003cp>\u003cstrong>【作业收集】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【结束语】\u003c/strong>\u003c/p>\u003cp>通过今天的学习，相信大家已经掌握了“赞赏三步法”的内容，也明确了赞赏三步法的优点，在今后的生活中希望这种走心的赞赏方式可以帮助你赢得更好的人际关系和亲子关系。\u003c/p>\u003cp> 谢谢大家的参与，我的分享到此结束。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1679230970000,"updated_at":1679649353000,"ria":true},{"id":15329,"topic":"五招让孩子愿意合作","learn_goal":"","remark":"线上过级","level":"TF1-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"俞三日","city":""},"club":{"name":"昆明春城分舵","city":"昆明"},"prologue":"\u003cp>\u003cstrong>【分组准备】\u003c/strong>\u003c/p>\u003cp>请今天可以参与互动的小伙伴在公屏打1。\u003c/p>\u003cp>今天互动的小伙伴到时候不用分组，直接在大厅分享。\u003c/p>\u003cp>\u003cstrong>【图书介绍】\u003c/strong>1分钟 \u003c/p>\u003cp>大家好，还是先来介绍一下自己，我叫俞晶，又称俞三日，现居德国。我的三个标签是：\u003c/p>\u003cp>1. 三岁混血娃宝妈：在中德跨文化家庭里，努力学习求同存异。\u003c/p>\u003cp>2. 拆书家：通过拆书训练，找到中国人圈子，并提升学习原能力\u003c/p>\u003cp>3. 倾听修炼者：通过阅读实践训练自己更有亲和力，希望能用三个太阳的温度给人带去温暖\u003c/p>\u003cp>今天我想跟大家分享的书是一本关于爱的技巧和训练，名叫《如何说，孩子才会听；怎么听，孩子才肯说》。这本书浅显易懂，里面有简单实用的行动步骤和生动有趣的插画例子。通过阅读和操练，我们可以学会更好的跟孩子沟通互动，与他们建立的良好关系，并促进他们身心健康的成长。\u003c/p>\u003cp>\u003cstrong>【过渡语\u003c/strong>】今天我选的拆页是其中关于“如何鼓励孩子与我们合作的技巧”。\u003c/p>\u003cp>下面请大家花1~2分钟的时间看一下原文片段，看完后在评论区回复111。现在就可以开始阅读了。\u003c/p>","ratings_count":1,"texts":[{"id":19372,"quote":"\u003cp>\u003cstrong>【R】阅读原书拆页 2 分钟 \u003c/strong>\u003c/p>\u003cp>[片段来源]：拆解片段来自《如何说，孩子才会听；怎么听，孩子才肯说》\u003cstrong>P56-57\u003c/strong>\u003c/p>\u003cp>那么，有什么更好的方法可以替代吗？有没有一种办法，可以让孩子和我们配合，而又不伤害他们的自尊，也不会让他们有逆反心理？有什么办法可以让家长少付出代价，又好操作呢？\u003c/p>\u003cp>下面，我们一起来分享非常有帮助的五个技巧。不是每一个技巧都适用于每个孩子，也不是每个技巧都适合你自己，这些技巧也不是每次都见效。但是，这五个技巧能帮助我们和孩子建立起互相尊重的平台，而互相尊重正是合作的开始。\u003c/p>\u003cp>鼓励孩子与我们合作的五个技巧\u003c/p>\u003cp>1，描述：描述你所看见的，或者描述问题。\u003c/p>\u003cp>2，提示、\u003c/p>\u003cp>3，用简单的词语表达。\u003c/p>\u003cp>4，说出你的感受。\u003c/p>\u003cp>5，写便条\u003c/p>","explains":"\u003cp>\u003cstrong>【过渡语】\u003c/strong>\u003c/p>\u003cp>好，看大家差不多看完了，不知道大家阅读完之后有什么想法呢？下面就由我代领大家拆解一下这个片段。\u003c/p>\u003cp>\u003cstrong>【I】拆书家讲解引导 \u003c/strong>\u003c/p>\u003cp>\u003cstrong>【what】\u003c/strong>\u003c/p>\u003cp>原文片段为我们提供了以互相尊重为核心，鼓励孩子与我们合作的：“尊重-合作”五技巧。\u003c/p>\u003cp>\u003cstrong>【Why】 \u003c/strong>\u003c/p>\u003cp>在教养孩子过程中，父母通常会与孩子产生很多冲突。有时父母自己也很难保持耐心和尊重，容易从自己的角度去训斥、勒令、威胁、讽刺孩子，希望孩子按照自己的思路行事”。\u003c/p>\u003cp>而最后的结果，常常是矛盾升级、两败俱伤。孩子要么不情愿的配合，要么反抗示威养不成这些习惯。两种都对孩子有伤害，严重的甚至会影响亲子关系和孩子的未来。\u003c/p>\u003cp>如果我们能够掌握“尊重-合作”五技巧，让孩子在跟我们的沟通中觉得被尊重，通常就更容易让孩子能与我们合作。 \u003c/p>\u003cp>\u003cstrong>【Where】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>适用范围：\u003c/strong>\u003c/p>\u003cp>接下来要学习的尊重-合作技巧，不但适合亲子关系，在其他冲突比较多的关系中也适用，比如家人、好友、邻居、同事、下属等等。\u003c/p>\u003cp>\u003cstrong>使用注意点：\u003c/strong>\u003c/p>\u003cp>1） 以关系为基础。\u003c/p>\u003cp>如果跟对方关系不够好，那可能会发生这种情况：你的中立的话语甚至可能会被对方负面诠释，造成他的抵触。比如有时候丈夫可能只是说了句“今天饭有点硬。”妻子如果比较敏感，很可能会觉得丈夫在挑刺、对自己的辛苦准备不珍惜，可能就会甩过去一句：“你爱吃不吃。”那最后很可能就会吵起来了。\u003c/p>\u003cp>但正是因为关系不好，才更需要持续的练习和使用这些技巧来改善关系，坚持久了以后就会有正向的改变出现。\u003c/p>\u003cp>2） 以合理为前提。\u003c/p>\u003cp>在要求对方之前，先要考虑要求本身是否合理，包括1）是否适合对方的年龄发展水平，比如让一岁的孩子在饭店里保持安静，这是超龄要求；2）是不是更多的是自己想要强加给孩子的要求，比如让孩子什么都得让着弟弟妹妹。\u003c/p>\u003cp>\u003cstrong>【How】\u003c/strong>\u003c/p>\u003cp>接下来我们一起来看”尊重-合作“五技巧，分别是：\u003c/p>\u003cp>1. \u003cstrong>描述事实。\u003c/strong>\u003c/p>\u003cp>客观描述你所看到的场景或者问题，就能集中精力在问题和解决问题上，而不是谁对谁错上。怎么能客观呢？就要用物品作主语。比如，小朋友常见的收拾问题，可以说“玩具都散在地上。” 如果加个“你把”，变成“你把玩具都散在地上”，就会有责怪的意味，对方可能会产生抵触情绪 ，一旦有抵触，就不会有主动配合的意愿出现。\u003c/p>\u003cp>2. \u003cstrong>提示做法。\u003c/strong>\u003c/p>\u003cp>用平和的语气和用词告诉孩子应该或者不应该做什么。孩子了解了可能的自然后果，也更愿意去配合要求。比如“玩具应该收拾好，不然下次要再玩会找不到、笔盖不盖好墨水干了以后就不能用了。\u003c/p>\u003cp>3. \u003cstrong>简化表达。\u003c/strong>\u003c/p>\u003cp>用简单的词语或者短语有力的表达，在提示基础上又给了孩子主观能动性，让孩子自己主动去思考可能的问题和解决方案。比如想让孩子收拾乱放的小熊的时候，只说“小熊！” 孩子就会想，喔，小熊怎么了，喔，小熊在地上，要收拾到收纳箱里。而相比较而言，讲大道理、啰嗦就会像蚊子一样招人烦，我自己就是，经常因为讲一堆重点不明确而被丈夫批评。\u003c/p>\u003cp>4. \u003cstrong>说出感受。\u003c/strong>\u003c/p>\u003cp>这里指的是我们真诚的表达出我们自己的感受。这能让孩子知道我们也是有界限的，能帮助他们跟我们共情。如果孩子懂得尊重我们，也会考虑到我们的感受而做出改变。比如孩子房间乱，玩具搁脚，我说“我踩到你的玩具，我的脚很疼。”或者“我不喜欢在杂乱的环境里生活，这会让我很焦虑。” \u003c/p>\u003cp>5. \u003cstrong>书写便条\u003c/strong>。\u003c/p>\u003cp>写便条说明需求和感受、并贴在相应的地方。这个方法能让孩子觉得被重视、大人则可以避免直接冲突，对于平时比较急躁（起到冷静暂停的作用）或者不善表达（起到有时间构思的作用）的父母很适合。\u003c/p>\u003cp>比如，可以用拟人的方式在小熊玩具身上贴“小主人，跟你玩好了我想回家，我现在很难过，请送我回家好吗？”这样的字样作为提示。如果孩子还不认字，也可以画一个哭脸来代替。另外，送纸条的方式也不仅仅局限在贴，也可以让一些孩子特别喜欢的人物来送，接受度会更高。比如圣诞老人、复活节兔子等等。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】激活经验 \u003c/strong>\u003c/p>\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>接下来请大家用30秒来回想一下，然后我们请每位小伙伴每人花1-2分钟时间来分享自己的要求不被孩子或者亲人、邻居、同事配合的一个经历，当然也可以是特别配合的一个经历。\u003c/p>\u003cp>回想一下，当时的场景下你的心情怎么样，你是如何提出要求的呢？对方又是怎么回应的呢？你当时用了哪些不对的方式呢？或者特别好的方式呢？对比“尊重-合作五技巧”，又有哪些是已经运用到的，哪些是可以考虑尝试运用的呢？想象一下运用的效果。\u003c/p>\u003cp>好，30秒时间到。谁愿意先来分享一下你的经历呢？\u003c/p>\u003cp>\u003cstrong>学习者案例记录：现场记录——案例\u003c/strong>\u003c/p>\u003cp>\u003cstrong>案例1：\u003c/strong>学习者有一个13岁的儿子，从小用比较强制的语气和方式让孩子准点睡觉，对小时候的孩子还比较管用，但现在孩子大了，用命令的方式孩子不太配合了。\u003c/p>\u003cp>\u003cstrong>案例2：\u003c/strong>学习者是民宿老板，酒店业对卫生要求高。但是每次保洁工作做得不好，他都是用命令的口吻去告诉保洁什么该做什么不该做。这样的效果不是很好，问题总是再次出现。学习者通过思考，认为可能是没有做到尊重保洁，如果有尊重的基础，再使用描述事实和提示做法的技巧，说不定对方下次就会认真的做好工作。\u003c/p>\u003cp>\u003cstrong>【A2】催化应用 5分钟\u003c/strong> （规划未来应用）\u003c/p>\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>1. 未来的一周或一个月内，你是不是还可能遇到这样的场景呢？比如：孩子不听话不配合、学生调皮捣蛋、跟年轻不成熟的晚辈一起工作充满阻碍、或者伴侣、父母有些不配合你的地方...\u003c/p>\u003cp>2. 这个时候，你会如何运用“尊重-合作五技巧”来促使对方与你合作呢？\u003c/p>\u003cp>3. 可以参考下面的方式，在脑海中想一想你具体的行动目标和行动步骤，如果身边有纸和笔的话也可以在纸上写下来：\u003c/p>\u003cp>Ø 目标：在接下来的______（时间段，比如明天3月12日一整天），我会在______（地点，比如家里），面对______（对象，比如家人），在_______场景中（比如孩子把墙壁涂花了的场景中）操练一次尊重-合作的技巧。\u003c/p>\u003cp>Ø 行动：\u003c/p>\u003cp>1，在这个场景中，我们该使用书写便条还是直接沟通的方式呢？\u003c/p>\u003cp>2.1如果是书写便条，我们该怎么准备、如何去写、以什么方式给到对方？\u003c/p>\u003cp>2.2如果是直接沟通，我们可以使用描述事实、提示做法、还是表达自己的感受呢？\u003c/p>\u003cp>3，可能有的困难是什么？怎么可以克服这样的困难？\u003c/p>\u003cp>Ø 可以设置奖励来鼓励自己行动！如果完成操练，可以______。 \u003c/p>\u003cp>\u003cstrong>学习者案例记录：现场记录——Andy的案例\u003c/strong>\u003c/p>\u003cp> 学习者计划明天晚上在家里客厅里跟自己的儿子使用尊重-合作技巧进行直接沟通，要解决的问题是让孩子关掉电视，早点休息。\u003c/p>\u003cp>具体行动步骤：\u003c/p>\u003cp>l 提示孩子：“十一点了，该睡觉了。”\u003c/p>\u003cp>l 表达感受：“你晚睡我会担心你的身体，也怕你这么晚在客厅容易着凉。”\u003c/p>\u003cp>l 可能的困难：平时凶惯了，第一次这么温柔不知道效果怎么样，但希望能持续操练。\u003c/p>\u003cp>\u003cstrong>【结束语】\u003c/strong>\u003c/p>\u003cp>好的，谢谢大家的参与，下面大家跟我一起再次回顾一下这五招有哪些内容：描述事实、提示做法、简化表达、说出感受、书写便条。核心是尊重，以尊重为目标，可以灵活的运用一个或多个技巧。希望大家可以把它们运用到你的家庭、生活、工作当中去。\u003c/p>\u003cp>好的，非常感谢大家，以上就是我今天的分享，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1678698629000,"updated_at":1679014114000,"ria":true},{"id":15125,"topic":"亲子沟通","learn_goal":"","remark":"不要等到犯了很多错误再来看本书，也不要等到很多错误酿成恶果再来看本书，更不要等到恶果已经生长到无法根除再来看本书。 马上阅读它吧，学会“说”“听”，及时沟通，消除隔阂，清扫孩子内心的尘埃，帮孩子营造一片晴朗的天空，让孩子健康快乐成长！ 一本和孩子有效沟通的超级指导书，作者清晰简洁创造了一套操作方法，使做家长变得更高效和更快乐。","level":"TF1-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"京彩纷呈","city":"石家庄市"},"club":{"name":"石家庄冀城分舵","city":"石家庄"},"prologue":"\u003cp>\u003cstrong>拆书技能点1：\u003c/strong>拆书活动前，已发送《拆书预备表》给观察家，且内容填写准确、完整。\u003c/p>\u003cp>\u003cstrong>拆书技能点9：\u003c/strong>总时长没有少于20分钟，没有超过25分钟。\u003c/p>\u003cp>\u003cstrong>拆书技能点10：\u003c/strong>“逐字稿包括开场、R、I、A1、A2、A3......的预备表+现场完整案例”格式整理实录。（此项可在活动结束后校验）\u003c/p>\u003cp>\u003cstrong>自我介绍：\u003c/strong>\u003c/p>\u003cp>各位小伙伴们大家上午好，感谢大家能来参加我的TF1-2的过级活动，我是今天的拆书家京京，我今天分享的主题是：鼓励孩子与我们合作。\u003c/p>\u003cp>首先我用三个标签来跟大家做下自我介绍。\u003c/p>\u003cp>第一个标签是：用亮点原则搞定两个男孩的全职妈妈。通过每天给孩子写优点的方式提升孩子的自我价值感，让孩子向善向好发展。\u003c/p>\u003cp>第二个标签是：语音写作践行者。就是通过用语音输出的方式记录自己的所思所想，目前每天语音写作至少1万字已224天。\u003c/p>\u003cp>第三个标签是：5点早起践行者。目前已早起74天。\u003c/p>\u003cp>\u003cstrong>拆书技能点4：\u003c/strong>用会议软件对学习者进行分组，并加入各小组讨论。\u003c/p>\u003cp>\u003cstrong>分组\u003c/strong>\u003c/p>\u003cp>在接下来的拆书环节中，我们会有小组分享环节，到时候我会用腾讯会议为大家分组。（人数多的情况：每6人一组，人数少的情况3人一组或不分组，直接讨论分享）\u003c/p>\u003cp>\u003cstrong>拆书技能点2：\u003c/strong>选择图书是实用类或理论类图书。\u003c/p>\u003cp>\u003cstrong>图书介绍：\u003c/strong>\u003c/p>\u003cp>今天和大家分享的拆页选自《如何说，孩子才会听；怎么听，孩子才肯说》\u003c/p>\u003cp>这本书的\u003ca href=\"https://baike.baidu.com/item/%E4%BD%9C%E8%80%85/144157?fromModule=lemma_inlink\">作者是阿黛尔·法伯、伊莱恩·玛兹丽施。两位女性作者不仅是国际著名的亲子沟通专家，而且都是三个孩子的母亲，她们已被收录于美国名人录。\u003c/p>\u003cp>本书给出了一系列非常实用的亲子教育技巧，书中给出了大量的家庭沟通实例和练习。值得惊喜的是书中还配有卡通漫画来展现每个技巧，即使在我们心急的情况下，仅仅通过看漫画也能将书中的技巧很快复习一遍，因此它的确是一本实操性非常强的家教读物。\u003c/p>\u003cp>今天拆页中提供的5个技巧，可以在既不伤害孩子的自尊，也不让他们有逆反的心理前提下与我们合作，帮助我们和孩子建立起互相尊重的平台。\u003c/p>\u003cp>那么下面进入到我们今天分享的主体内容部分。\u003c/p>\u003cp>我们花1分钟的时间来看一下原文片段，看完后请您在评论区打个1，示意我一下，谢谢。\u003c/p>","ratings_count":1,"texts":[{"id":19137,"quote":"\u003cp>\u003cstrong>拆书技能点3：\u003c/strong>拆页内容未超过2页图书内页。\u003c/p>\u003cp>\u003cstrong>拆书技能点5：\u003c/strong>【R】所选拆页包含具体行动或做法。\u003c/p>\u003cp>\u003cstrong>拆书技能点11：\u003c/strong>在讲解时，通过共享屏幕播放PPT，清晰呈现R原文、I便签核心内容和A2指令。\u003c/p>\u003cp>\u003cstrong>主题（页码）：鼓励孩子与我们合作，第二章P57\u003c/strong>\u003c/p>\u003cp>有没有一种方法，可以让孩子和我们配合，而不至于伤害他们的自尊，也不会让他们有逆反的心理？有什么办法可以让家长少付代价，又好操作呢？\u003c/p>\u003cp>下面．我们一起来分享非常有帮助的五个技巧。不是每一个技巧都适用于每个孩子，也不是每个技巧都适合你自己，这些技巧也不是每次都见效。但是，这五个技巧帮助我们和孩子建立起互相尊重的平台，而互相尊重正是合作的开始。\u003c/p>\u003cp>鼓励孩子与我们合作的五个技巧\u003c/p>\u003cp>1．描述：描述你所看见的，或者描述问题。\u003c/p>\u003cp>2．提示。\u003c/p>\u003cp>3．用简单的词语表达。\u003c/p>\u003cp>4．说出你的感受。\u003c/p>\u003cp>5．写便条。\u003c/p>","explains":"\u003cp>\u003cstrong>拆书技能点6：\u003c/strong>拆书家讲解引导中包括了：1）行动建议步骤；2）与行动各步骤对应的案例。\u003c/p>\u003cp>\u003cstrong>拆书技能点11：\u003c/strong>在讲解时，通过共享屏幕播放PPT，清晰呈现R原文、I便签核心内容和A2指令。\u003c/p>\u003cp>好的，我看到大家都已经看完了。下面我跟大家分享一下我对拆页的理解。\u003c/p>\u003cp>what:\u003c/p>\u003cp>这个片段主要为我们提供了五个鼓励孩子与我们合作的技巧。\u003c/p>\u003cp>why:\u003c/p>\u003cp>我们来回想一下，生活中，当我们希望孩子配合时通常是怎么做的呢？\u003c/p>\u003cp>“我数三下，你再不把玩具放回原处，我就把玩具给你扔了” ——威胁\u003c/p>\u003cp>“再让我看到你在墙上乱画，我就揍你了” ——警告\u003c/p>\u003cp>“马上把屋子打扫干净！”——命令\u003c/p>\u003cp>“告诉你多少遍了上完厕所要关灯”——责备\u003c/p>\u003cp>“你看你，又是要出门了，忘了拿包，如果包不长在你身上，你就记不住拿”——讽刺挖苦\u003c/p>\u003cp>“你怎么这么没礼貌，总是打断我说话，真是讨厌”——谩骂\u003c/p>\u003cp>“你答应的好好的，我们买了小鸡，你负责每天喂它。但这星期已经提醒过你三次了。我受不了了，我和爸爸轮流来帮你弄，都成了我们的事儿了。”——长篇大论的说教\u003c/p>\u003cp>试想一下，当我们以这种方式对待孩子的时候，孩子对这些话会有什么反应？孩子会是怎么样的心情？\u003c/p>\u003cp>害怕、内疚、逆反、自我否定、不安全感等等负面感受。\u003c/p>\u003cp>使用片段中的给出的五个技巧，能鼓励孩子自愿、开心地 跟家长合作去做事，从而也会有助于我们建立和谐的亲子关系。\u003c/p>\u003cp>来看一下具体的做法。\u003c/p>\u003cp>how:\u003c/p>\u003cp>\u003cstrong>技巧1：描述。\u003c/strong>不带情绪的描述我们看到的事件或问题。\u003c/p>\u003cp>比如：孩子乱扔垃圾——“我看到阳台地上扔着一个香蕉皮没人管他”\u003c/p>\u003cp>孩子没关灯——“宝贝，我看到厕所的灯还开着呢。”\u003c/p>\u003cp>\u003cstrong>技巧2：提示。\u003c/strong>简单清晰的说出正确的行为或做法。\u003c/p>\u003cp>比如：孩子在墙上乱画——“墙不是用来画的，纸是用来画的”\u003c/p>\u003cp>想让孩子帮忙做家务——“我现在需要有人能帮我收拾一下餐桌”\u003c/p>\u003cp>\u003cstrong>技巧3：简单的词语表达。\u003c/strong>\u003c/p>\u003cp>有时候多说不如少说，孩子不喜欢说教和长篇大论，对他们来说，越短越容易记住，也越有效。\u003c/p>\u003cp>比如：孩子忘记拿包只需要说：“宝贝，你的包”\u003c/p>\u003cp>\u003cstrong>技巧4：表达感受\u003c/strong>\u003c/p>\u003cp>我们只描述自己的感受就好。可以用“我....”“我觉得....”这样的语句。\u003c/p>\u003cp>比如：“如果我的话还没说完，就被人打断，我会觉得不高兴。”\u003c/p>\u003cp>经验告诉我们：孩子的感受得到尊重后，他们也会尊重大人的感受。但这也需要一个过程。当你说出你的感受：“那会让我很烦”，孩子可能会说：“那又怎么样，谁会在意呢？”这时候，你可以让孩子知道：“我在意。我在意自己的感受。我也在意你的感受。我希望家里人都在意彼此的感受。”\u003c/p>\u003cp>\u003cstrong>技巧5：写便条\u003c/strong>\u003c/p>\u003cp>有的时候，文字比口头说更有效。\u003c/p>\u003cp>比如：冰箱门上贴着“宝贝，拿完东西，记得关冰箱门”\u003c/p>\u003cp> 电视上贴着“在开电视之前，想一想，我的作业做完了吗”\u003c/p>\u003cp>\u003cstrong>注意\u003c/strong>：这5个技巧，可以组合使用，也可以根据实际情况从5个技巧中，选择一个你认为最有效的单独使用。在实际应用时，可以根据对方的反馈灵活调整。\u003c/p>\u003cp>当然这5个技巧，不是每一个技巧都适用于每一个孩子，这些技巧也不是每次都见效。但，这5个技巧可以帮助我们和孩子建立起互相尊重的平台，而互相尊重正是合作的开始。\u003c/p>\u003cp>where:\u003c/p>\u003cp>书中主要讲的是父母与孩子之间的合作，但其实这5个技巧也可以用于老师与学生之间，朋友之间、夫妻之间、同事之间等等。\u003c/p>\u003cp>但这五个技巧不适用于危险或紧急情况中。\u003c/p>\u003cp>案例:\u003c/p>\u003cp>为了方便大家更好的理解，我来分享一个我自己的案例。\u003c/p>\u003cp>前一段时间，我家老大上完厕所后总是忘记冲厕所，前天我发现他又忘记了冲厕所，我当时就有点儿带着情绪对孩子说“rr，你怎么回事，怎么总是忘记冲厕所，为这个事儿我都跟你说了多少遍了，你怎么总是记不住？”孩子一脸尴尬，说“你看到了没冲，你就顺手给冲了怎么了”，我没好气儿的回了一句：“那是你的事儿，我凭什么帮你冲？”孩子见状蔫蔫的去冲了厕所。\u003c/p>\u003cp>反思：我跟孩子的整个对话一开始就是带有情绪的，虽然孩子最后去冲了厕所，但面对我带有批评和责备的话语，孩子内心中的声音可能会是“我不好，我总是记不住”等负面感受，同时我的话也伤害了孩子的自尊，让孩子有了逆反的心理，也破坏了我们的亲子关系。\u003c/p>\u003cp>那学习了这个片段后，运用这5个技巧我该怎么说呢？\u003c/p>\u003cp>首先自己要深呼吸平复自己的心情，让自己不带有情绪的和孩子对话。\u003c/p>\u003cp>\u003cstrong>技巧1：描述：\u003c/strong>\u003c/p>\u003cp> 宝贝，刚刚是你上了厕所吗？我看到还没有冲马桶。\u003c/p>\u003cp>\u003cstrong>技巧2：提示。\u003c/strong>\u003c/p>\u003cp>上完厕所及时冲马桶才能保证干净卫生哦。\u003c/p>\u003cp>\u003cstrong>技巧3：用简单的词语表达。\u003c/strong>\u003c/p>\u003cp>冲马桶\u003c/p>\u003cp>\u003cstrong>技巧4：表达感受\u003c/strong>\u003c/p>\u003cp>马桶没有及时冲掉，我会觉得很不卫生。\u003c/p>\u003cp>\u003cstrong>技巧5、写便条\u003c/strong>\u003c/p>\u003cp>在卫生间马桶旁边写上“亲爱的宝贝，上完厕所要记得冲马桶哦，爱你的妈妈”\u003c/p>","interaction":"\u003cp>\u003cstrong>拆书技能点7：\u003c/strong>【A1】指令清晰。学习者在小组内分享了自己的经验，并有一位代表分享了本组的一个经验。\u003c/p>\u003cp>\u003cstrong>拆书技能点11：\u003c/strong>在讲解时，通过共享屏幕播放PPT，清晰呈现R原文、I便签核心内容和A2指令。\u003c/p>\u003cp>\u003cstrong>A1激活经验：\u003c/strong>\u003c/p>\u003cp>下面进入小组分享环节，因为今天的人数不多，我们就不分组了，直接在主界面进行分享就可以。\u003c/p>\u003cp>\u003cstrong>拆书家提问设计（逐字稿）：\u003c/strong>\u003c/p>\u003cp>好的方法与我们过往的经验产生关联才能更好的为我们所用。\u003c/p>\u003cp>那学习了这5个技巧后，请大家用1分钟的时间来回想一下，在过去的一周内与孩子、家人相处的过程中，有没有遇到：对方的行为与我们的期待不一致时，因使用了错误的方法（责备、命令、说教、威胁等等）而导致合作失败的具体案例呢？\u003c/p>\u003cp>比如：\u003c/p>\u003cp>因孩子一直玩手机的问题，威胁孩子“再玩手机就把手机没收了”导致孩子逆反。\u003c/p>\u003cp>出门送孩子上学的时间到了，因孩子还在磨磨蹭蹭而责备孩子，让双方情绪都不好。 \u003c/p>\u003cp>因老公进家门后总是把鞋子乱丢，没有放入鞋架上唠叨了几句，导致对方也情绪不好回怼了你.......\u003c/p>\u003cp>现在给到大家5分钟的分享时间，谁想到了就可以开麦发言，每人发言不超过2分钟。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>韩：\u003c/p>\u003cp>1、我家孩子大了，他抽烟了，我那天去到他屋里，当时没抽，但我看到有个盒子，盒子里面有烟灰，桌上还有烟。我当时就说“你怎么又抽烟了？说好了不抽的”，而后我就把他的烟掰断了扔到了垃圾桶里，把打火机也给扔了。\u003c/p>\u003cp>2、按要求孩子在家里是要洗碗的，那天都吃饭很久了，他还没洗，我就说“赶紧的，赶紧的，抓紧把碗给洗了去！你怎么拖拖延延的。”\u003c/p>\u003cp>刘：\u003c/p>\u003cp>寒假开始时，我就跟孩子已经约定好每晚把第二天的学习计划列好，这样第二天就可以按照计划去执行。有一天到晚上9点了，因为约定的是9点之前要把这项工作完成，9点以后就可以自由活动了。但到9点了，我还没有看到他第二天的学习计划。我第一句话说的是“我好像还没有看到你明天的学习计划，你是不是忘了写？”。第二句话我说“咱们是不是约定好了，每天晚上9点前把第二天的计划给列出来，是不是？”孩子回答“是”，我说“那你马上去写好吗？”孩子说“嗯，行”。第4句话我说“咱们既然约定好了的事情，就一定去做到，就跟咱们平时一样，承诺的事情就必须要做到，形成良好的习惯。”第5句话说的是“你去把计划列好贴到课桌的墙上”，交代完之后，孩子也没有反抗的情绪上的波动，孩子就老老实实的去做了。\u003c/p>\u003cp>\u003cstrong>拆书技能点8：\u003c/strong>【A2】指令清晰。提醒每个学习者都写下了一个包含具体做法，其中包含具体的行动方案，有明确时限和可衡量或可观测预期结果的便签。\u003c/p>\u003cp>\u003cstrong>拆书技能点11：\u003c/strong>在讲解时，通过共享屏幕播放PPT，清晰呈现R原文、I便签核心内容和A2指令。\u003c/p>\u003cp>\u003cstrong>拆书家提问设计（逐字稿）：\u003c/strong>\u003c/p>\u003cp> 谢谢两位小伙伴的分享！\u003c/p>\u003cp>在拆书帮，拆书呢就是为了拆为己用，为了帮助我们提升解决问题的能力。\u003c/p>\u003cp>接下来请小伙伴们想一想：在未来的一个周内，当再次遇到类似的场景时，你将如何运用5个技巧鼓励对方与我们合作呢？\u003c/p>\u003cp>现在给大家1分钟的时间，请大家在便签纸上写出未来一周内可能会出现的具体场景，按照我们讲到的5个技巧，规划一次具体的实际应用，这5个技巧可以都用，也可以挑选你喜欢的一个使用。\u003c/p>\u003cp>请开始....\u003c/p>\u003cp>这里也给大家提醒一下：写便签时不能仅仅是表决心，要有明确的时限、具体的做法、要有可衡量或可观测的预期结果。\u003c/p>\u003cp>\u003cstrong>与我们合作的五个技巧：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1、描述：\u003c/strong>不带情绪的描述我们看到的事件或问题。\u003c/p>\u003cp>\u003cstrong>2、提示。\u003c/strong>简单清晰的说出正确的行为或做法。\u003c/p>\u003cp>\u003cstrong>3、用简单的词语表达。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>4、表达感受\u003c/strong>\u003c/p>\u003cp>只描述自己的感受。可以用“我....”“我觉得....”这样的语句。\u003c/p>\u003cp>\u003cstrong>5、写便条\u003c/strong>\u003c/p>\u003cp>写完的小伙伴请在公屏上敲1示意我，我们可能会找一个小伙伴分享他的计划，会议结束后，我会把大家的A2便签收集起来。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>韩：\u003c/p>\u003cp>我做设计文件的审核，我用刚刚学习的其中的三个技巧来说一下。\u003c/p>\u003cp>1、“我看到你的设计文件中有一些项目的地址有错误”\u003c/p>\u003cp>2、提示他正确的做法。“你和同事要进行自审和一审，找到文件当中的错误，避免低级错误出现。”\u003c/p>\u003cp>3、表达感受。“出现这样的低级错误，我觉得会损害公司的形象，以后要注意一下，文件要写正确。”\u003c/p>\u003cp>\u003cstrong>结束语\u003c/strong>\u003c/p>\u003cp>今天的分享到此就结束了。\u003c/p>\u003cp>希望我们都能借助这5个合作的技巧，与孩子搭建起互相尊重的平台！\u003c/p>\u003cp>非常感谢大家的参与！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1675168764000,"updated_at":1676365827000,"ria":true},{"id":15077,"topic":"有效赞赏孩子的三步法","learn_goal":"","remark":"有没有一个时候让你感觉赞美孩子都让你语竭词穷，绞尽脑汁后说出来来的也仅仅是几句“你真棒！”“你真厉害！”，然后换来孩子意犹未尽地悻悻离开，剩下尴尬的自己？今天的拆页会给你带来不一样的赞赏孩子的方法，学习后你一定有一种相识恨晚的感觉。\n","level":"TF2-2","duration":30,"status":30,"type":0,"chaishujia":{"username":"静Tina","city":"青岛市"},"club":{"name":"青岛五月风分舵","city":"青岛"},"prologue":"\u003cp>\u003cstrong>【自我介绍】\u003c/strong>\u003c/p>\u003cp>大家好，我是张芳，三个标签介绍下我自己：过季的外贸人，当季的全职妈妈，未来的三级拆书家。今天我要过的是TF2-2， 用时30分钟，主题是：\u003cstrong>有效赞赏孩子的三步法\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者在需要对孩子或他人表示赞赏时，能够用描述性赞赏三步法来进行赞赏。\u003c/p>\u003cp>\u003cstrong>【图书介绍】2分钟\u003c/strong>\u003c/p>\u003cp>\u003cstrong>今天的拆页选自与《如何说，孩子才会听；怎样听，孩子才肯说》\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【F 特征】\u003c/strong>\u003c/p>\u003cp>本书作者是阿黛尔.法伯和伊莱恩.马兹丽施，她们俩都是国际著名亲子沟通专家，她们的著作不仅深受家长的欢迎，而且也得到专业权威人士的认可。本书结合案例通过七个章节的内容诠释了如何与孩子建立一种基于在平等互爱、互相尊重基础上的交流沟通方式。\u003c/p>\u003cp>\u003cstrong>【A 优势】\u003c/strong>\u003c/p>\u003cp>本书在美国家教类图书中销售量达300多万册稳居第一，被译为30多种文字风靡全球30年长销不衰。受到来自世界各地父母和专家热情洋溢的赞美。书中每个章节除了配有案例故事，疑难问题解答和练习题来深化知识外，作者还别出心裁地配上了卡通漫画，让书中的知识不在乎早乏味。这是同类书籍中非常鲜见的。\u003c/p>\u003cp>\u003cstrong>【B 利益】\u003c/strong>\u003c/p>\u003cp>【B1本书】\u003c/p>\u003cp>在生活中，你有没有在需要夸奖孩子的时候倍感语竭词穷？有没有发现孩子越来越不愿意跟你分享他们的成就和喜悦？那么这本书不但会帮家长们解决这些问题，而且还可以帮助父母收获良好的亲子关系和欢乐的家庭氛围，更能帮助孩子最终成长为独立自强充满爱心和具备责任心的人。读完这本书的其中一个小章节，就可以学到一些即插即用的亲子沟通技巧，在亲子沟通上有立竿见影的效果。\u003c/p>\u003cp>【B2拆页】\u003c/p>\u003cp>那么今天我给大家带来的拆页内容也是选自这本书中的其中一个亲子沟通的小技巧，它将教会给我们如何有效的表扬孩子，而且这个方法简便实用，百试不爽。\u003c/p>","ratings_count":1,"texts":[{"id":19081,"quote":"\u003cp>《如何说，孩子才会听；如何听，孩子才会说》 P192\u003c/p>\u003cp>\u003cstrong>赞赏孩子的方法\u003c/strong>\u003c/p>\u003cp>用描述代替评论\u003c/p>\u003cp>(“真好!”“太好了!”“真是绝了!”)\u003c/p>\u003cp>\u003cstrong>1.描述你所看见的\u003c/strong>\u003c/p>\u003cp>“地板很干净，床很平整，书都整齐地码放在书架上。”\u003c/p>\u003cp>\u003cstrong>2.描述你的感受\u003c/strong>\u003c/p>\u003cp>“走进这间屋子，感觉很舒服。”\u003c/p>\u003cp>\u003cstrong>3. 把孩子值得赞赏的行为总结为一个词\u003c/strong>\u003c/p>\u003cp>“你把笔都分了类，彩笔、钢笔分别放在不同的盒子里。这就叫作&#x27;有条理’。”\u003c/p>","explains":"\u003cp>【WHAT】今天的这段拆页给大家讲述了用三步可以实现的一种有效表扬孩子的方法，即描述性赞赏。\u003c/p>\u003cp>【WHY】通常我们喜欢用简单的评价性语言来对孩子或者他人进行赞赏，这样不但会让人误会我们是在敷衍，而且时间久了，孩子也会对被表扬这件事渐渐失去兴趣。而描述性赞赏是针对具体行为或过程进行表扬，而不是简单的肯定结果，这样可以让孩子内心更有力量，帮助孩子树立良好行为，也比较容易让孩子感受到大人对自己的关注和尊重。\u003c/p>\u003cp>\u003cstrong>【HOW】\u003c/strong>如何让我们对孩子的赞赏不那么干瘪又能给孩子带来积极的影响呢？下面我们就来一起学习描述性赞赏的三步法：\u003c/p>\u003cp>\u003cstrong>1-描述事实：\u003c/strong>把自己看到的事实用简单的一句话表述出来，比如：我看到、、、、、、\u003c/p>\u003cp>\u003cstrong>2-描述感受：\u003c/strong>针对你刚刚看到的事实，总结下你的真实感受，比如：我感觉到、、、、、\u003c/p>\u003cp>\u003cstrong>3-总结优点：\u003c/strong>比如，你这样做就叫做：有责任心，勇敢，乐于助人，坚强，乐观向上，等等。\u003c/p>\u003cp>（举例）一个月前孩子被选为国旗下好宝宝，老师让她周一升旗的时候表演拍皮球，孩子很开心地在我面前练习，还时不时地要求我欣赏她的“成绩”。她拍得很起劲儿虽然拍不了几个，而作为妈妈，我就要准备好花式的表扬语言来鼓励她。我知道这个时候“加油，你真棒！”说一次两次还行，说多了就会让孩子没有了兴趣。于是我根据她每次拍球时的特点来用描述性赞赏三步法表扬她：妈妈看到你这次站得很正、、、、、这次小手姿势也很正确，你又进步了宝贝，妈妈真为你开心、、、、再坚持练几次就一定有更好的效果。你这样不怕失败，一次次地总结经验让自己变得更好，叫做坚持不懈，坚持不懈的人最终都会成功的。孩子认真地听我说完，拍球拍的更认真了。\u003c/p>\u003cp>\u003cstrong>【WHERE】\u003c/strong>这种赞赏的方法虽然是出现在育儿书籍里，但是其实它可以被用在其他更多场合，比如对朋友、家人的赞赏，甚至对工作伙伴以及客户的赞赏。\u003c/p>\u003cp>\u003cstrong>注意：\u003c/strong>我们的赞赏不要联系到对方以前的过失或者缺点。比如你不能说：“以前你都考不及格，这次居然及格了！”这很容易让赞赏变成了嘲弄。\u003c/p>\u003cp>另外，赞赏要把握好度，如果过于热烈，而且喋喋不休的赞赏，就让人不免尴尬。\u003c/p>\u003cp>\u003cstrong>预防异议\u003c/strong>\u003c/p>\u003cp>有些小伙伴可能会说：我们也知道这种方法很棒，但是有时候我们真的很忙，没有精力和时间去用这个方法去表扬孩子，只想赶紧的用简单的“你真棒”来简单敷衍一下孩子，我们也很无奈。\u003c/p>\u003cp>是的，的确这是会经常出现的现实状况：一边是自己要处理的棘手事情，另一边是孩子心理的抚慰。但是这并不影响我们使用描述性赞赏三步法来进行赞赏。当我们在处理棘手的事情时，可以先用简单的表扬打发掉孩子，但同时能否在自己心里主动mark下这件事，然后等自己忙完手头的事第一时间找到孩子，跟他解释下刚才你在忙，没有机会跟他沟通太多，然后用描述性赞赏再对他刚才的行为补充表扬。我们还可以跟孩子约定，以后爸爸妈妈在忙着的时候可能没有办法跟你长时间的交流，不代表爸爸妈妈不在乎你的表现，希望给爸爸妈妈一点儿时间好么？这样一来一方面满足了孩子被表扬的心情，也完美了亲子关系，未来让孩子与家长之间更加默契。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A2分步催化1】拆书家提问设计\u003c/strong>\u003c/p>\u003cp>在场的各位在生活中一定扮演着不同的角色，有爸爸妈妈，叔叔阿姨，哥哥姐姐，还有老师，那么请你设想一下，未来一周内你身边的孩子可能会因为他做了什么他认为很有成就感的事而走到你面前寻求你的赞赏呢？\u003c/p>\u003cp>（分组）接下来我给大家分组，小伙伴们先在小组内分享，每个人尽量都来分享一下，在这里我还要再提醒下大家，这里只分享情景就好了，不需要分享如何做。五分钟后我会请一两位小伙伴来跟大家分享一下。\u003c/p>\u003cp>\u003cstrong>【A2分步催化1】学习者案例\u003c/strong>\u003c/p>\u003cp>好，哪位小伙伴想来分享一下？ \u003c/p>\u003cp>薛燕老师：我儿子上一年级，他最近特别喜欢做饭，最近学校也刚刚搞了一个劳动小达人的活动，需要他边做饭边讲解，然后把做家务的这件事情录制一个小视频，然后分享给大家，我想他做完这件事情以后肯定是要来到我身边寻求表扬的。\u003c/p>\u003cp>\u003cstrong>【A2分步催化2】拆书家提问设计\u003c/strong>\u003c/p>\u003cp>刚才伙伴们都设想出了一些孩子期待得到表扬得的场景，那么我们来继续思考一下，在刚刚你分享的场景下，你会怎样用今天学到的描述性赞赏的三步法来对孩子进行赞赏呢？\u003c/p>\u003cp>分享之前我们再来回顾下今天学习的描述性三步法：\u003c/p>\u003cp>\u003cstrong>1-描述事实：\u003c/strong>比如：我看到、、、、、、\u003c/p>\u003cp>\u003cstrong>2-描述感受：\u003c/strong>比如：我感觉到、、、、、\u003c/p>\u003cp>\u003cstrong>3-总结优点：\u003c/strong>比如，你这样做就叫做：有责任心，勇敢，乐于助人，坚强，乐观向上\u003c/p>\u003cp>（分组）下面请大家在小组内先分享，每个人不超过两分钟分享时间，5分钟结束小组分享后，我会找一两位小伙伴来分享他的计划。请注意，我们的计划除了要有具体时间，还要有具体的做法，其中包括具体行动方案，而且可以让大家观测到你预期目标。\u003c/p>\u003cp>\u003cstrong>【A2分步催化2】学习者案例\u003c/strong>\u003c/p>\u003cp>哪位小伙伴想来分享一下？\u003c/p>\u003cp>薛燕老师：未来一周，如果我的孩子就做家务这件事来寻求表扬的话，我会这样说：我看到你对做饭的流程特别熟悉，还加入了自己细致的讲解，我感受到了你的从容和淡定，你在做饭的时候特别有爱，有爱心的孩子最帅气！\u003c/p>\u003cp>\u003cstrong>【结语】1分钟\u003c/strong>\u003c/p>\u003cp>非常感谢大家的分享，也很开心看到大家掌握了今天拆页的重点：描述性赞赏的三步法。希望大家学以致用，把今天的拆页在未来拆为己用。\u003c/p>\u003cp>我的分享到此结束，谢谢大家的参与。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1673854493000,"updated_at":1673941499000,"ria":true},{"id":13955,"topic":"《解决问题的步骤》P106","learn_goal":"","remark":"当问题一再出现时，情况就会变得比以前复杂。那么复杂的问题就需要复杂的技巧。家长辅导员，劳务谈判代表，婚姻咨询师总结了一套非常好的方法，来解决复杂的问题和冲突，这是我在小组里介绍给大家的。\n解决问题的五个步骤。\n第一步：讨论孩子的感受和需求。\n第二步：说出你的感受和需求。\n第三步：一起讨论，找到大家都同意的解决方法。\n第四步：把所有的想法都写下来（不带任何评论）\n第五步：找出哪些建议你们能接受，哪些要付诸行动。 ","level":"TF1-1","duration":14,"status":30,"type":0,"chaishujia":{"username":"雷丹虹","city":"福州市"},"club":{"name":"福州筹备分舵","city":"福州"},"prologue":"\u003cp>\u003cstrong>【自我介绍】：\u003c/strong>各位伙伴们，大家早上好，我是今天的分享者雷丹虹。雨田“雷”，一片丹心的“丹”，彩虹的“虹”。借用诗句来做一个简单的自我介绍：春风化雨润心田，一片丹心天地间，虹飞百里千丝尽，云卧双肩七彩黏。是的，我是一名教育工作者，加入拆书帮是我学习成长路上又前进的一小步，今天是我第一次参加拆书帮晋级的日子，特别期待与各位小伙伴一起交流学习，共同进步！\u003c/p>\u003cp>\u003cstrong>【拆书帮介绍】：\u003c/strong>可能有小伙伴想要问：拆书帮是什么？那我先给大家解释一下什么是【拆书】，拆书的“拆”并不是拆散的意思，而是“转化”和“内化”，强调把书本里的知识转化为学习者的能力。所以“拆书”是一种以提升能力，解决问题为目标的成人学习方法论，强调以学习者为中心而不是以知识为中心，更强调要把知识关联学习者的经验，再规划具体的运用。分为个人学习的拆书法和组织学习的拆书法。个人学习的应用是RIA便签法，通过三张阅读便签，让人读一本书就能达到参加同主题培训的效果；组织学习的应用是一位拆书家拿一本书加工成一场现场学习，引导和促进一群人把知识拆为己用。\u003c/p>\u003cp>所以【拆书帮】是基于拆书法的学习爱好者社群，目前在全国很多地方都有拆书帮分舵（也叫拆书帮俱乐部）。拆书帮分舵是非营性青年自组织，其使命是帮助更多的学习爱好者成长为拆书家。\u003c/p>\u003cp>相信通过我的介绍，大家对于“拆书”和“拆书帮”已经有了一定的了解。那么我们今天就运用RIA便签法来拆解一个片段。 \u003c/p>","ratings_count":1,"texts":[{"id":17962,"quote":"\u003cp>片段来自子女教育类书籍《怎么说，孩子才会听，怎么听，孩子才肯说》。现在我把片段内容发给大家（发复印好的内容），请大家花2分钟时间来阅读手上的片段，阅读完的小伙伴可以抬头示意我一下。\u003c/p>\u003cp>\u003cstrong>【R 阅读原文】：\u003c/strong>\u003c/p>\u003cp> 坚持了三个星期以后，鲍比的老毛病又犯了。这位妈妈实在没有招了，当她把自己的烦恼在小组里讲的时候，大家提出了很多问题：“这种情况下，该怎么办？......假如所有方法都试过了，问题还是一遍一遍的出现，怎么办？......除了惩罚，再找不出别的办法的时候，该怎么办？‘’\u003c/p>\u003cp> 当问题一再出现时，情况就会变得比以前复杂。那么复杂的问题就需要复杂的技巧。家长辅导员，劳务谈判代表，婚姻咨询师总结了一套非常好的方法，来解决复杂的问题和冲突，这是我在小组里介绍给大家的。\u003cbr>\u003cstrong>解决问题的五个步骤。\u003c/strong>\u003cbr>\u003cstrong>第一步：讨论孩子的感受和需求。\u003c/strong>\u003cbr>\u003cstrong>第二步：说出你的感受和需求。\u003c/strong>\u003cbr>\u003cstrong>第三步：一起讨论，找到大家都同意的解决方法。\u003c/strong>\u003cbr>\u003cstrong>第四步：把所有的想法都写下来（不带任何评论）\u003c/strong>\u003cbr>\u003cstrong>第五步：找出哪些建议你们能接受，哪些要付诸行动。\u003c/strong> \u003cbr>\u003c/p>","explains":"\u003cp> 好，我看到大家已经看完拆页了，接下来我就分享一下我的理解和体会。\u003c/p>\u003cp>\u003cstrong>【WHY】：\u003c/strong>\u003c/p>\u003cp>在家庭教育中，当孩子出现屡教不改的问题或是行为时，家长们往往容易走进教育的误区，要么束手无策，要么把精力放在彼此的对抗上，好像除了高高在上的惩罚，再也找不到更好的办法，精神饱受折磨还达不到解决问题的目的。\u003cbr> 如果在孩子出现反复问题时，我们能够掌握好方法，把握好时机，把能量和精力放在解决问题上，寻求一种能够让彼此的需求都得到满足的方法，这样不仅能够积极的引导孩子，还能锻炼孩子自己解决问题的能力，达到合作共赢。\u003c/p>\u003cp>\u003cstrong>【WHAT】：\u003c/strong>\u003c/p>\u003cp>这个片段向我们介绍了当孩子出现反复问题时，如何积极解决问题和冲突的方法。\u003cbr>\u003cstrong>【HOW】：\u003c/strong>具体有五个步骤：\u003cbr>第一步【谈对方感受和需求】：设身处地体会孩子当时的感受并试着理解孩子的需求，把它说出来。 \u003cbr>譬如晚上看到孩子到点了还不写作业的时候，你可以这么说：“你和伙伴们玩游戏正开心的时候，妈妈让你停下去写作业，能看出来你有点不开心。”\u003cbr>第二步【说自己感受和需求】：真诚的袒露心声，向对方表达自己的感受和需求。 \u003cbr>可以这么说：“但是另一方面，如果你不注意时间，妈妈担心你今晚作业会做到很晚，影响你休息和第二天上学。”\u003cbr>第三步【寻求解决办法】：鼓励孩子一起参与讨论，找到问题的解决办法。 \u003cbr>可以这么说：“那我们一起想想，有什么办法能让我们都乐于接受，你也能更合理的安排时间？你先来说说看？”\u003cbr>第四步【写下所有想法】：不带任何评价的把想到的都记录下来。 \u003cbr>注意：过程中，不评论，不反驳，给一个安全的环境，鼓励双方都参与进来，尽可能多的写下解决办法。\u003cbr>第五步【沟通达成共识】：放下高高在上的身份，用平等平和的语气和孩子一起挑选出双方都能接受的解决办法。 \u003cbr>注意：结合自己的真实想发和需求来表达观点，哪些能接受，哪些不能接受，不接受也要充分沟通理由。 \u003cbr>\u003cstrong>【WHERE】:\u003c/strong>\u003c/p>\u003cp>其实这个方法不仅适用于家长和老师处理孩子屡教不改的问题；在家庭生活中，解决夫妻间出现的问题和矛盾时也同样受用。再就是在职场中处理同事间的矛盾和冲突时，也不失为一种好方法。\u003c/p>\u003cp>需要注意的是：对话双方应该心平气和，关系平等。不要把对话的精力放在输赢的争辩上，而应该是通过对话，积极的寻求共赢的方案。 \u003c/p>","interaction":"\u003cp> 看完拆页的内容，我立刻联想到了发生在我跟孩子身上的一个经历：\u003c/p>\u003cp>\u003cstrong>【A1相关经历】：\u003c/strong>\u003c/p>\u003cp> 记得上周末的傍晚时分，四岁半的弟弟正从小区玩耍回来，看到桌上的西瓜，伸手就要抓起来吃，我看到他满身是汗，脏兮兮的手就要伸手去抓东西吃，我当是又急又气，立刻就训斥孩子：“妈妈跟你说了多少次了，回家第一件事就是先洗手，你看看你，满身都是脏兮兮的就想吃东西，一点都不讲卫生！现在马上去洗手洗脸，没洗干净就不要吃了。” 本来开心心心回家的孩子被我突如其来的一顿训斥吓到了，立刻委屈的大哭起来。\u003cbr>\u003cstrong>【A1反思】： \u003c/strong>\u003c/p>\u003cp>现在想来，当时的我又急又气，在孩子出现不良行为的当下，①我没有说出“孩子的感受和需求”，虽然知道孩子玩耍回来又饿又渴，但是看到他不洗手的行为，情绪脑还是占据了主导地位。②因为急于阻止孩子的不良行为，也没有及时“说出自己感受和需求”，没有让孩子理解妈妈担心他因为不讲卫生，吃坏肚子的担忧。③没有积极地“寻求解决办法”，更没有给到孩子平等沟通，解决问题的机会，而是用训斥的语气在指责，忽略了理性解决问题的办法。其实在问题发生的时候，最难的是转变我们对待事情的态度，不能把孩子当成是一个“问题”来纠正，如果当时肯花时间坐下来，心平气和的和孩子分享彼此的感受，我想一定能和孩子一起讨论出解决的办法。\u003c/p>\u003cp>\u003cstrong>【A2目标】：\u003c/strong>\u003c/p>\u003cp> 孩子需要成长，家长又何尝不是呢？遇到反复出现的问题时，多一些耐心，真诚的和孩子沟通解决问题，在我看来是家庭教育中非常重要的。所以我决定在本周六的家庭会议中，通过跟孩子一起回溯事件和平等对话，帮助孩子养成吃东西前主动洗手的习惯。\u003c/p>\u003cp>\u003cstrong>【A2行动】：\u003c/strong>\u003c/p>\u003cp>我打算分为五个步骤：\u003c/p>\u003cp>第一步【谈对方感受和需求】：“宝贝，上周天傍晚你从小区开开心心的回家，到了饭点，看到可口的西瓜，一定很想吃。妈妈没有先提醒你去洗手，而是直接训斥你不洗手就不要吃东西，我想你一定又委屈又难过。” \u003cbr>第二步【说自己感受和需求】：“但是，你要知道，在外面玩耍回来，身上手上都有很多的小细菌，我们肉眼是看不到的，如果不洗手就去拿东西吃，小细菌跑进肚子里，很容易吃坏肚子，妈妈很担心你会生病。”\u003cbr>第三步【寻求解决办法】：“妈妈希望你养成讲卫生的好习惯，每天都健健康康的，我们一起想一想，怎样才能让小细菌不跑到宝贝的肚子里面呀？\u003c/p>\u003cp>第四步【写下所有想法】：过程中，多一些耐心，倾听并记录孩子的想法，及时的给与回应和积极引导。\u003c/p>\u003cp>第五步【沟通达成共识】：“宝贝太棒啦，想了这么多的好办法！抵抗小细菌，我们一起试试吧！\u003c/p>\u003cp>我想，以后碰到类似的情况，除了当时可以多一些耐心地跟孩子真诚的交流，我们还需要注意在沟通后及时给与孩子积极反馈。譬如：下次孩子回家第一件事情就记得先洗手，一定要及时肯定他的行为：“妈妈看到宝贝一回家就去洗手，香香的，洗的真干净，宝贝真是个讲卫生的好孩子，妈妈要奖励你双倍家庭积分哟”。\u003c/p>\u003cp>\u003cstrong>【奖励】:\u003c/strong> 如果我能在家庭会议中跟孩子达成约定共识和实践意愿，就奖励我自己双倍的家庭积分。\u003c/p>\u003cp>随着孩子一天天长大，也许我们会遇到更多的育儿问题。我相信为人父母没有不爱孩子的。让我们学会感受孩子，理解孩子，引导孩子，智慧的爱孩子！相信孩子拥有心灵上的富足和解决问题的智慧，是一生当中宝贵的财富！\u003c/p>\u003cp>以上就是我的个人分享，感谢各位伙伴们的陪伴和聆听。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1660378152000,"updated_at":1662885493000,"ria":true},{"id":11654,"topic":"帮助孩子面对他们的感受","learn_goal":"","remark":"怎么说孩子才会听，怎么听孩子才会说","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"拆书家十八","city":"贵阳市"},"club":{"name":"贵阳黔灵分舵","city":"贵阳"},"prologue":"\u003cp>目标：设定学习目标。要求：可观察/可测量的行为或动作\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者能够情景重现一次他人在表达难过，伤心等负面情绪时自己做的不到位的一件事，并且学会用尊重感受的方法做到不评价，不给建议，逐步舒缓他人的负面情绪，双方顺利完成沟通或者就此事达成意见一致，甚至找到解决方案。\u003c/p>\u003cp>【开场】爱学习，爱分享的伙伴们大家好，欢迎大家参加本次RIA现场学习，我是一级拆书家杨朵，大家可以叫我十八，医美设计师是我的职业，成为孩子亦师亦友，引以为傲的母亲是我终生学习的原动力。\u003c/p>\u003cp>【分组】希望本次RIA现场学习后，各位能够学会运用尊重感受的方法，舒缓他人的负面情绪，为了方便学习过程中充分交流讨论，我们来进行一下分组。今天有位小伙伴到场，我们就3人一组。谢谢！\u003c/p>\u003cp>【用FAB法介绍图书。要求：清晰辨别出F、A、B】\u003c/p>\u003cp>下面我先来介绍一下我今天拆解的这本书《如何说孩子才会听 怎么听孩子才会说》。\u003c/p>\u003cp>【F】特征，核心是“书”，用于满足好奇心。\u003c/p>\u003cp>这是一本家教类的图书，本书就“尊重感受”“鼓励合作”“鼓励自立”“代替惩罚方法”“赞美方法”“角色中释放”6大问题提供了30个技巧，讲了如何与不同年龄段的孩子进行有效沟通，简单易行且有效。\u003c/p>\u003cp>【A】优势，重点是“比较”，用于建立安全感。\u003c/p>\u003cp>与同类家教类图书相比，本书出版三十多年，被翻译成三十多种语言，销量累计位于美国家教类图书第一。与其他家教类图书相比，本书每一个方法都配有漫画，并且有以前的做法和新方法的场景模拟对比；与其他家教类图书相比，本书开篇作者直接给出了如何阅读本书的方法。\u003c/p>\u003cp>【B】利益，强调的是“你（学习者）”用于引发兴趣。\u003c/p>\u003cp>B1：这本书给学习者带来的好处。\u003c/p>\u003cp>通过对本书的学习，可以帮助你解决家里每天因为吃饭，穿衣，学习等上演的亲子大战，可以缓解越来越陌生的亲子关系，学到代替惩罚的有效方法，怎样鼓励孩子自立，如何有效的赞美孩子，如何让孩子和你合作等沟通方法。\u003c/p>\u003cp>B2：拆页片段给学习者带来的好处\u003c/p>\u003cp>如果你的孩子或者朋友在向你述说一件事时突然说：算了，不说了，或者反而更加的闷闷不乐，甚至孩子大声哭闹，那么今天拆页的片段提供了尊重感受的方法（帮助孩子面对他们的感受的方法），就可以让你学会如何有效的帮助他们缓解负面情绪。\u003c/p>","ratings_count":1,"texts":[{"id":15594,"quote":"\u003cp>【R】阅读原文\u003c/p>\u003cp>帮助孩子面对他们的感受（P27-P27）\u003c/p>\u003cp>孩子需要他们的感受被接纳和尊重\u003c/p>\u003cp>1.安静专心地倾听。\u003c/p>\u003cp>2.用简单的词语回应他们的感受。\u003c/p>\u003cp>“哦……嗯……原来是这样……”\u003c/p>\u003cp>3.说出他们的感受。\u003c/p>\u003cp>“这件事让你很灰心!”\u003c/p>\u003cp>4.用幻想的方式实现他们的愿望。\u003c/p>\u003cp>“真希望我能立刻把香蕉变熟了给你吃!”\u003c/p>\u003cp>所有的感受都应该被接纳,但某些行为必须受到限制。\u003c/p>\u003cp>“我看得出你很生弟弟的气。用嘴巴告诉他你将怎么做,而不是用拳头。”\u003c/p>","explains":"\u003cp>（看到大家都阅读完了，接下来我会进行片段内容的讲解。）\u003c/p>\u003cp>【what】:原文告诉我们帮助孩子面对感受的四个技巧，从而让孩子觉得自己被尊重，有利于进行有效的沟通。。\u003c/p>\u003cp>【why】:感受与行为有直接的联系，每个人都希望自己的情绪被他人理解和尊重，而人们大多数表现出的语言都是否定感受，给建议，心里分析，提问，讲大道理等\u003c/p>\u003cp>（不这么做的坏处）被他人不断的否定感受，不仅孩子会感到愤怒与困惑，大人同样会奔溃。在愤怒的状态时，听不进去任何建议，看法，更不会将注意力集中在如何解决问题上，而且情绪会影响判断和想法。\u003c/p>\u003cp>（这么做的好处）一旦他人觉得自己的感受被理解，负面情绪就会自行消退，达到顺利沟通，相互理解，彼此谅解，甚至共同合作。\u003c/p>\u003cp>【举个例子】（我说一个我自己的例子）反例\u003c/p>\u003cp>在今年4.22日时，我因为工作上的一件事情特别的生气，回家跟老公说起这件事情的时候，我老公就说:老板说什么就是什么了，听听就行了，就像我们的某某领导，她经常就是这样的。听到他这么说我就越发的生气，心想他一点都不理解我，真是没有共同话题，就生气的对他说：算了，不和你说了，没意思。\u003c/p>\u003cp>【HOW】: \u003c/p>\u003cp>那么如何让他人觉得你是在尊重他的感受，理解他，有以下几种方法\u003c/p>\u003cp>1、认真倾听：全神贯注的倾听他人的诉说，时不时的进行眼神的交流。\u003c/p>\u003cp>2、简答回应：用“嗯”“哦”“是这样”等简答的词语代替提建议和提问来回应他们的感受\u003c/p>\u003cp>3、幻想愿望：用幻想的方式代替逻辑上的解释\u003c/p>\u003cp>如：“真希望我是蛋糕师，现在就可以做蛋糕给你吃”\u003c/p>\u003cp>4、说出感受：用说出对方的感受方式代替否定感受\u003c/p>\u003cp>如：“这件事让你感到非常沮丧”\u003c/p>\u003cp>正例: \u003c/p>\u003cp>在学了这个方些技巧后，我就经常在和我儿子沟通的时候使用。记得特别清晰的一次，在小洋洋2岁4个月大时，一天我下班回到家，正和他玩小车车变火车，玩的正开心时，爷爷就逗他，拿走了他一个小车车。洋洋一下子特别的生气，边哭边打自己的头。奶奶在旁边着急的说:不能打头，他还准备继续这个打头的动作，\u003c/p>\u003cp>我（温和的对洋洋说）:宝贝,爷爷拿了你的车车你生气了？（说出孩子的感受）\u003c/p>\u003cp>他放下手，忍着眼泪说：是。\u003c/p>\u003cp>看他情绪没有那么激动了，我就接着说：爷爷其实是想和你一起玩，如果你不喜欢这样，你可以对爷爷说,爷爷你这样拿走玩具我会生气哦，而且生气也不可以打自己哦，知道了吗？洋洋说：知道了，妈妈。接着我们俩拥抱了一下，就开开心心的去玩了。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>这些方法可以单独使用，可以两两组合，多种搭配，可根据不同的场合多元化运用；\u003c/p>\u003cp>可以用于亲子沟通中，还可以在家人，朋友情绪低落时用来缓解他们的消极情绪，工作中下属因工作的压力情绪低落时，理解他的感受，逐步调整回工作状态。\u003c/p>","interaction":"\u003cp>【拆书家提问设计】\u003c/p>\u003cp>【场景设计】\u003c/p>\u003cp>接下来呢，要请大家回想一下，你最近一周或一个月内，有没有这样的情形，他人向你诉说一件影响他情绪的事情，结果说到一半他就不说了，或者事后他仍然闷闷不乐，甚至情绪失控，比如：孩子对你说他的玩具坏了，学校里老师批评他了，朋友对你说她和爱人因为某件事吵架了等等，而你当时是如何回应的？\u003c/p>\u003cp>请大家仔细回想一下当时的场景，简单的写在便签上，并在小组内分享，每人大约一分钟的时间，每个人都要分享哦\u003c/p>\u003cp>（来回在小组内走动，倾听他们的分享）\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>1、分享者阿志：一个星期前，座位旁的同事向我抱怨老板不好，老板安排不合理等等，总之就是负面情绪的输出。我听了特别不舒服，还没等他说完，我就直接对他说：还好吧，本来他就是老板，谁让我们是打工的呢，你想开点等一堆大道理。同事生气的说：他还能把我开除了。就这样结束了本次对话。\u003c/p>\u003cp>2、分享者燕子：连续3天幼儿园的老师都在给我说：你儿子又打小朋友了，又不好好吃饭了等等，这些都是好久没有发生的事情了。昨天晚上和他心平气和的沟通，但是今天早上他又犯了以前的老错误，我直接把他揍了一顿，而且直接把他关在了门外边\u003c/p>\u003cp>【拆书家提问设计】\u003c/p>\u003cp>我听到了小伙伴们精彩的分享，现在请大家想一下，如果时光倒流，你再回到刚才分享的事件发生时间点，你会如何运用今天所学的尊重感受的方法来进行这次的谈话，请在便签上写下来，并在小组内分享，5分钟后我会邀请一位小伙伴来分享。\u003c/p>\u003cp>（提示：这些技巧有认真倾听，简单回应，说出感受，幻想愿望）\u003c/p>\u003cp>刚才听了阿志的分享特别的精彩，有请他用2分钟的时间分享一下。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>分享者阿志：如果同事向我抱怨老板，表达他的感受，我就会1、首先就是少说，不大打断他的话（认真倾听）；2、简单回应：恩，好像他是这样的；3、幻想愿望：买彩票中个500万，就直接抄老板的鱿鱼。4、说出感受：听到他这么说你感到很愤怒。\u003c/p>\u003cp>谢谢阿志的分享，从你的分享中我感受到了你的共情和尊重对方的感受\u003c/p>\u003cp>接纳他人的语言有助于提高我们的沟通效果，但是，我们不是天生就会说这种共情的语言，因此，需要我们通过一些新方法不断的强化练习来熟悉这种“新语言”，帮助孩子接纳他们感受的方法就是其中一种，希望大家回去以后多多使用，希望今天的学习对大家有所帮助，谢谢各位的聆听与陪伴。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1622984834000,"updated_at":1622998734000,"ria":true},{"id":11302,"topic":"三步赞赏法，让赞赏更真诚走心，提高沟通效果","learn_goal":"","remark":"三步赞赏法，让赞赏更真诚走心，提高沟通效果","level":"TF2-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"李喜兰","city":"南昌市"},"club":{"name":"南昌滕王阁分舵","city":"南昌"},"prologue":"\u003cp>【\u003cstrong>开场\u003c/strong>】\u003c/p>\u003cp>大家下午好!欢迎来到拆书帮2-2的活动现场。我是李喜兰，用三个标签来介绍一下自己：幼儿园园长、两个男宝的妈妈、家庭教育指导师。 \u003c/p>\u003cp>\u003cstrong>【学习目标】在跟随我完成本次Ria现场学习后，学习者能够在赞赏的场景中运用赞赏三步法表达。\u003c/strong>\u003c/p>\u003cp>【\u003cstrong>图书介绍\u003c/strong>】2分钟\u003c/p>\u003cp>（F）特征：《如何说孩子才会听，怎么听孩子才肯说》作者是阿黛尔·法伯和伊莱恩·玛兹丽施。她们是国际著名亲子沟通专家，她们的著作不仅深受家长的欢迎，而且也得到专业权威人士的认可。两位作者都是三个孩子的母亲，她们已被收录于美国名人录。\u003c/p>\u003cp>（A）优势：此书列为《纽约时报》家庭教育类十大畅销书之一，销售300多万册，被译为30多种文字风靡全球，出版20多年畅销不衰。与同类育儿书相比，更具可操作性，尤其是书中还配有简单明了的漫画让人阅读感觉很好，每个章节后有练习很接地气，很贴心。\u003c/p>\u003cp>（B）利益：你有没有遇到过不管你怎么说，孩子就是不听？这本书教给你鼓励孩子与我们合作的技巧。书中从关注感受、鼓励、赞赏以及注重解决问题代替惩罚等六个方面来提升亲子沟通。这是一本融合爱与沟通技巧的神奇之书。接下来我给大家分享一个小片段。今天说的这个片段，可以使得你的赞赏富有诚意并且被孩子所接受，达到深入孩子内心，引导孩子正确行为的目的。\u003c/p>\u003cp> 现在我把这个片段发给大家，先给大家分个组方便交流分享，从右手边两两一组。阅读时间2分钟，阅读完毕的小伙伴请举手示意谢谢！\u003c/p>","ratings_count":1,"texts":[{"id":15227,"quote":"\u003cp>\u003cstrong>【R原文片段】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>《如何说孩子才会听 怎么听孩子才肯说》P192页 2分钟\u003c/strong>\u003c/p>\u003cp>\u003cstrong>赞赏孩子的方法\u003c/strong>\u003c/p>\u003cp>\u003cstrong>用描述代替评论\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（“真好！”“太好了！”“真是绝了！”）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1、描述你所看见的。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>“地板很干净，床很平整，书都整齐地码在书架上。”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2、描述你的感受。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>“走进这间屋子，感觉很舒服。”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>3、把孩子值得赞赏的行为总结为一个词。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>“你把笔都分了类，彩笔、钢笔分别放在不同的盒子里。这就叫做“有条理””\u003c/strong>\u003c/p>","explains":"\u003cp>好!大部分伙伴已经读完了，我来给大家介绍一下。\u003c/p>\u003cp>原文拆页介绍了赞赏孩子的三个步骤。赞赏孩子要从事实出发，说感受，不评论，并且最后用一个词语来概括，使得赞赏具有真实和有力量的感觉。\u003c/p>\u003cp>我常常听到大家常用赞赏孩子的不外乎这几句话：“你真棒！你真聪明！你做的很好！”等等，缺乏具体内容描述的赞赏，并不会得到孩子的认同，刚听完夸奖的时候会高兴，但在具体行动得不到反馈时，就会觉得你在应付他敷衍他，起不到激励的作用，引发不了孩子情感的共鸣和行为的改变。而通过这样的方法来赞赏孩子，可以和孩子建立情感共鸣，得到孩子的认可，强化孩子的优秀行为，激发孩子内心的美好情感。\u003c/p>\u003cp>\u003cstrong>（举例说明）\u003c/strong>\u003c/p>\u003cp>上周日在家里，12岁的大宝在自己房间画画，持续了一个多小时。当他画完后给我看并问我“妈妈！我画的好吗？”我瞄了一眼说：“嗯！画的很好！”孩子问：“怎么好了？”我说：“怎么好？多美啊！太漂亮了！”孩子一把拿走画不满地说：“你根本不喜欢！！”讲完这个案例，为什么我表达了赞赏，他们却不领情？就是因为总说很好啊，很美啊！这些话没有触动内心的感觉，学完今天这个方法，我可以这样来说。\u003c/p>\u003cp>1、说事实。把看见的现象说出来，告诉孩子事实是什么。\u003c/p>\u003cp>2、表感受。告诉孩子你的感受是什么，对方能感受到你的情绪的。\u003c/p>\u003cp>3、下定义。把值得赞赏的行为总结为一个词。\u003c/p>\u003cp>如果再回到上周，我会运用原文的三步法这样表达：\u003c/p>\u003cp>先说事实，今天你花了一个多小时在房间画火柴人。\u003c/p>\u003cp>再表感受，我看到你做这个事情很专注很用心，我感觉到很吃惊也很开心！\u003c/p>\u003cp>最后总结为一个词，你专注地做一件事情的样子很酷，你是一个专注的孩子，相信坚持下去你会越画越好。\u003c/p>\u003cp>这个专注和坚持下去比画的很好啊，要更恰当，也不是敷衍，不至于被孩子说你根本不喜欢。\u003c/p>\u003cp>\u003cstrong>（预防异议）\u003c/strong>\u003c/p>\u003cp>听完后是不是觉得太麻烦了，简单的一句话就够了，还要讲事实说感受，最后还得提炼概括。这就有两个疑问，赞赏一个孩子需要这么麻烦吗？他这么小能理解这么多吗？\u003c/p>\u003cp>第一，不是每件事都这么来赞赏，一般的小事情不需要这么复杂，需要这样赞赏的有两个标准：一个是孩子做的事是你希望未来他经常做到的，想让他的行为成为长期的事情；另一个是这个事情有一定难度，不是轻而易举小事。\u003c/p>\u003cp>第二，第三步来赞赏，孩子能理解这么多吗？\u003c/p>\u003cp>和孩子相处之后就会发现，孩子的观察能力特别强，你的一点点的情绪变化他能观察到，你的感受能获得孩子共鸣。而且孩子的记忆力特别好，你的总结可以让孩子记很长时间。所以说赞赏三步法，对孩子来说是能理解并且有效果的。\u003c/p>\u003cp>\u003cstrong>（适用边界）\u003c/strong>\u003c/p>\u003cp>赞赏三步法适用于和孩子，同事、家人、亲近的人之间激励对方的情况下使用，不适用于普通关系中一句话就可以解决的价值低没必要的小事。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A2】【催化应用】\u003c/strong>（4分钟）\u003c/p>\u003cp>\u003cstrong>（分步催化1）\u003c/strong>\u003c/p>\u003cp>设想一下，你的同事，家人或者孩子做了一件事让你特别想赞赏一下他，比如在周末的晚上当你加完班拖着疲惫而又饥饿的身体回家，当打开门看见12岁的儿子在厨房叮叮当当炒蛋炒饭，并给你端来一碗热气腾腾香喷喷的蛋炒饭时，你的幸福感扑面而来，你有没有想赞赏孩子的想法呢？请大家思考并想到自己的一个具体的赞赏场景。\u003c/p>\u003cp>时间3分钟，大家先思考2分钟，然后我们有请一位小伙伴来分享。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>占老师：我的小儿子三岁，做晚饭前我和他约定：“妈妈做饭时，你玩乐高，咱们互不打扰好吗？”当我做完饭时，看见他专注地玩乐高没有打扰我，我真的想赞赏一下他！\u003c/p>\u003cp>\u003cstrong>（分步催化2）：\u003c/strong>（5分钟）\u003c/p>\u003cp>请大家在刚刚想到的场景中，利用今天的赞赏三步法说出你的具体行动步骤，以便将来在生活中加以应用，请大家在小组内讨论并分享。时间3分钟，\u003c/p>\u003cp>3分钟后，哪位小伙伴愿意和我们一起分享？\u003c/p>\u003cp>时间到，请这位小伙伴分享一下自己的案例。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>占老师：学习了赞赏三步法，我会这样赞赏他。\u003c/p>\u003cp>第一步：妈妈看见你专注地玩乐高，一直到妈妈做完晚饭。\u003c/p>\u003cp>第二步：你遵守我们的约定没有打扰妈妈做饭，妈妈很高兴！\u003c/p>\u003cp>第三步：你是一个遵守约定的宝贝！\u003c/p>\u003cp>非常感谢小伙伴的分享！我今天的拆书到此结束，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1617858687000,"updated_at":1618479901000,"ria":true},{"id":10590,"topic":"怎样诚恳走心地夸奖别人","learn_goal":"","remark":"如何说孩子才会听怎么听孩子才会说","level":"TF2-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"整理控文娟","city":"北京市"},"club":{"name":"北京城市之光分舵","city":"北京市"},"prologue":"\u003ch3>\u003cstrong>一.自我介绍\u003c/strong>\u003c/h3>\u003cp>大家好，我是今天分享的拆书家整理控文娟。\u003c/p>\u003cp>我先用三个标签介绍一下自己：\u003c/p>\u003cp>第一个标签，新媒体运营，这是我的职业；\u003c/p>\u003cp>第二个标签，整理控，我有一个全网粉丝超过 11 万的自媒体公众号叫做整理控，是面向整理师和整理爱好者的\u003c/p>\u003cp>第三个标签，宝妈，我有一个 7 岁的儿子。\u003c/p>\u003cp>我今天挑战的级别是 2-1，今天和大家分享的图书是《\u003cstrong>如何说孩子才会听 怎么听孩子才肯说\u003c/strong>》。\u003c/p>\u003ch3>\u003cstrong>二.书籍介绍\u003c/strong>\u003c/h3>\u003cp>【新技能点：介绍图书】\u003c/p>\u003cp>【F 特征】\u003c/p>\u003cp>《如何说孩子才会听，怎么听孩子才肯说》的作者是美国的亲子沟通专家阿黛尔·法伯和伊莱恩·玛兹丽施，这是一本教家长如何跟孩子沟通的书，但其实也可以用在成人沟通之间，拆书帮的帮主赵周老师就曾经把这本书中的内容用在快消品店长跟 90 后销售员沟通的培训上。\u003c/p>\u003cp>【A 优势】\u003c/p>\u003cp>这本书相比同类的图书，最大的特点是直观和有可操作性，是一步步的在教父母和孩子沟通的办法，详细到句式和语气，甚至你在说这个句式时的心情，是一本非常实用的沟通类图书。\u003c/p>\u003cp>【B 利益】\u003c/p>\u003cp>不知道大家在日常生活中，有没有遇到这样的情况，你的女朋友或闺蜜跟你吐槽她工作中的烦恼，你给她提了很多个在你看来非常实用的建议，但她却不高兴；你跟男朋友或者老公说了 180 遍，要把脱下来的袜子放到脏衣篓里，他当时答应了，回头还是随处脱随处扔......这本《如何说，孩子才会听 怎么听 孩子才肯说》就能够教给你倾听和沟通的技巧。\u003c/p>\u003cp>【新技能点：设定学习目标】\u003c/p>\u003cp>我今天分享的拆页选自这本书的 192 页，主题是：如何诚恳走心地夸奖别人？\u003c/p>\u003cp>我先把拆页发给大家。\u003c/p>\u003cp>（在跟随我完成本次学习后，大家能够使用三步法夸奖别人，提高沟通效果。 ）\u003c/p>\u003ch3>\u003cstrong>三.分组 \u003c/strong>\u003c/h3>\u003cp>【技能点：分组】\u003c/p>\u003cp>下面请主持人帮我发一下拆页。大家都拿到拆页了吧。待会呢我们会有小组讨论，所以我们先进行一下分组，这边的几位是一组，另外的几位是一组。\u003c/p>\u003ch3>\u003cstrong>四、R 环节：阅读拆页 \u003c/strong>\u003c/h3>\u003cp>下面请大家花 1 分钟时间看一下拆页。如果阅读完毕，可以抬头示意我。\u003c/p>\u003cp>《如何听，孩子才会说，怎样说，孩子才肯听》172 页\u003c/p>","ratings_count":3,"texts":[{"id":14449,"quote":"\u003cp>\u003cstrong>《如何说孩子才会听 怎么听孩子才肯说》\u003c/strong>\u003c/p>\u003cp>\u003cstrong>赞赏孩子的方法\u003c/strong>\u003c/p>\u003cp>用描述代替评论\u003c/p>\u003cp>（“真好！”“太好了！”“真是绝了！”)\u003c/p>\u003cp>1.描述你所看见的\u003c/p>\u003cp>“地板很干净，床很平整，书都整齐地码放在书架上。”\u003c/p>\u003cp>2.描述你的感受\u003c/p>\u003cp>“走进这间屋子，感觉很舒服。”\u003c/p>\u003cp>3.把孩子值得赞赏的行为总结为一个词\u003c/p>\u003cp>“你把笔都分了类，彩笔、钢笔分别放在不同的盒子里。这就叫作‘有条理’。”\u003c/p>","explains":"\u003ch3>\u003c/h3>\u003ch3>\u003cstrong>五、I 环节：拆书家拆解 \u003c/strong>\u003c/h3>\u003cp>【新技能点：拆书家讲解引导】\u003c/p>\u003cp>好，我看到大家都读完了。下面我就来讲述一下这个拆页。\u003c/p>\u003cp>\u003cstrong>（why)\u003c/strong>\u003c/p>\u003cp>我们都知道，夸奖，赞美，是人际沟通中一个很重要的部分，夸得好，可以活跃气氛，可以拉近和对方的距离，可以鼓励对方，增强对方的自信心，激励对方把事情做得更好。\u003c/p>\u003cp>\u003cstrong>（不这样做的坏处）\u003c/strong>\u003c/p>\u003cp>但如果夸得不好呢，比如，通常人们会夸：“嗯，挺好的”，“不错”，“还行”，对方可能会觉得你不诚恳不走心，不关心不重视他，敷衍他，甚至觉得你在讽刺挖苦他。\u003c/p>\u003cp>那很多时候，我们并不是真的不关心不重视对方，只是不知道该从哪里下手夸？\u003c/p>\u003cp>\u003cstrong>（what) \u003c/strong>\u003c/p>\u003cp>那么今天，我就给大家介绍一个“夸人三步法”。“夸人三步法”是一个可以帮助我们诚恳走心地夸奖别人的技巧。\u003c/p>\u003cp> \u003cstrong>(how)\u003c/strong>\u003c/p>\u003cp>这个办法是这样的 。\u003c/p>\u003cp>\u003cstrong>第一步，描述你所看见的\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第二步，描述你的感受\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第三，把对方值得赞赏的行为总结为一个词\u003c/strong>\u003c/p>\u003cp>（自身案例）\u003c/p>\u003cp>听上去有点简单，真的有用吗？我来给大家讲一个我自己的案例。\u003c/p>\u003cp>\u003cstrong>【举例子-反例】\u003c/strong>\u003c/p>\u003cp>我刚才说过，我家有个 7 岁的儿子，他写完作业不收摊，课本，书，文具铺的满桌子都是，地上也是，一般会在我的强势命令下哭唧唧地收拾干净。\u003c/p>\u003cp>但也会有偶尔懂事的时候，把书桌收拾整齐，然后一脸期待地来找我。那我就像很多妈妈通常夸奖的一样说，”嗯，挺干净，要是每天都这样就好了。“\u003c/p>\u003cp>他本来是满脸期待的，但听我一说就不高兴了。\u003c/p>\u003cp>为什么呢，首先是，我说，嗯，挺干净，显得不太走心，他会觉得我付出了这么多努力，你的夸奖配不上我的努力，挺干净，三个字就把他打发了。\u003c/p>\u003cp>第二是，我后面又加了一句，要是每天都这样就好了。我这样说，当然是希望他每天都能够做到，其实是我夸奖他的目的，但是这给他增加了压力，他估计会想，我整理一次，就让我天天整理，还不如不干了。\u003c/p>\u003cp>那接下来，他就不干了。\u003c/p>\u003cp>\u003cstrong>【加工成正面的例子】\u003c/strong>\u003c/p>\u003cp>那后来呢，学习了这个夸人三步法，我就这么夸了。\u003c/p>\u003cp>\u003cstrong>第一步，描述你所看到的\u003c/strong>\u003c/p>\u003cp>我看到桌子上没有横七竖八的课本，也没有作业本，干干净净的，铅笔都在文具盒里，地上只有一根掉落的铅笔。\u003c/p>\u003cp>\u003cstrong>第二步，描述你的感受\u003c/strong>\u003c/p>\u003cp>看到这些，我感到心里很舒服，一点也不烦躁了。\u003c/p>\u003cp>\u003cstrong>第三步，把对方值得赞赏的行为总结为一个词\u003c/strong>\u003c/p>\u003cp>你在写完作业把课本和文具都放得整整齐齐，桌子上干干净净，下次用也不会找不到了，这就叫做“做事有条理”。\u003c/p>\u003cp>我儿子听了一脸得意，说，看到我把摊收了，你特别高兴吧。后面几天还时不时地拿出来回忆说，那天我把摊收了，你特别高兴吧。可见我是夸到点子上了，增强了他的自信，激励他向这个方向努力。\u003c/p>\u003cp>【新技能点：适用边界】\u003c/p>\u003cp>这个夸人三步法适用于和孩子，朋友、家人、同事之间，期望能够拉近双方关系，激励对方的情况，不适用于商务场合，或者你跟对方不需要建立良好的关系，就不必要用了。\u003c/p>","interaction":"\u003ch3>\u003cstrong>六、A2 环节（催化学习者应用）\u003c/strong>\u003c/h3>\u003cp>【新技能点：激活学习者经验】\u003c/p>\u003cp>现在，我请大家回忆一下，在最近一周或者一个月，有没有遇到过这样的事情，你的同事，家人或者孩子做了一件事，你觉得应该夸夸她，但是不知道该怎样夸，这样的情景。\u003c/p>\u003cp>是在什么时间，在什么地点，他当时做了什么，你当时是什么心情，有把夸奖说出口吗，又是怎样夸的，他的反应如何？\u003c/p>\u003cp>请大家先自己想 1 分钟，写在便签纸上，然后跟小组的成员分享。在你的分享中，要有明确的时间，地点，人物，事情的起因，经过和结果。\u003c/p>\u003cp>组内分享时间是 2 分钟。2 分钟后，我们请一位小伙伴来给大家分享。\u003c/p>\u003cp>\u003cstrong>学习者@刘泽敏：今天在微信上，我这边需要做一个小视频，我在网上找个素材，我需要把这个素材下载下来，就请教我老公，然后我老公告诉我，把屏幕横过来，然后录屏。这个方法倒是不错，虽然不完全是我想要的，我就说，全是实用野路子。表扬他虽然实用，但是没有完全按照我的想法，我觉得好像夸得不是很好。\u003c/strong>\u003c/p>\u003cp>【新技能点：请学习者反思加工经验】\u003c/p>\u003cp>非常感谢这位小伙伴的分享。刚才这位小伙伴分享了自己之前夸人的经历。\u003c/p>\u003cp>今天我们学习了三步夸人法，那么，我们现在来运用一下，回到刚刚你写下的那个场景，你将会如何运用“三步夸人法”来夸奖他呢。\u003c/p>\u003cp>\u003cstrong>学习者@刘泽敏：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第一步描述我所看到的：你给我的办法很实用，我得到了我需要的那部分视频。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第二步描述我的心情是：我现在可以非常安心地工作了。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第三步把对方值得赞赏的行为总结为一个词：老公，你真是我坚强有力的后盾啊！\u003c/strong>\u003c/p>\u003cp>感谢这位小伙伴的分享。\u003c/p>\u003ch3>七、结束语\u003c/h3>\u003cp>夸奖别人是一项重要的沟通技巧，会让我们的社交更顺利，更容易与对方关系融洽，也可以用来增加对方的自信心，激发对方的潜力。希望今天的夸人三步法能够帮助到大家。\u003c/p>\u003cp>我今天的拆书就分享完毕，感谢大家的参与和学习，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1604055817000,"updated_at":1606917008000,"ria":true},{"id":10492,"topic":"如何用正确的方式代替惩罚","learn_goal":"","remark":"每次在小组里讨论是什么触发家长惩罚孩子，你认为受罚的孩子会是什么感受时，我总会问大家:“为什么?我们为什么要惩罚孩子?”家长们讨论得越多，越理解惩罚会带来的感受:敌意、仇恨、抗议、罪恶感、没有价值感、自怜。然而，家长们仍然有担心，惩罚不解决问题，反而影响了孩子对自己的反思，那么我们该用什么来代替惩罚呢?","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"威威","city":"石家庄市"},"club":{"name":"石家庄梧桐分舵","city":"石家庄"},"prologue":"\u003cp>开场:大家好，我是今天的拆书分享者威威，欢迎各位爱读书的小伙伴一起参加本次学习，我今天要过的2-1.\u003c/p>\u003cp>自我介绍:嗨，我是威威。我用三个标签介绍一下自己。\u003c/p>\u003cp>我的第一个标签是，早期教育的家庭规划师，我的第二个标签是，我是一位超人妈妈，我的第三个标签，我是咱们拆书帮的一级拆书家。\u003c/p>\u003cp>分组:为了方便大家讨论分享，下面按照就近原则，根据今天的人数，我们分为一个组，方便大家讨论。\u003c/p>\u003cp>学习目标:在跟随我完成本次RIA现场学习后，学习者能够在出现冲突的时候，不把精力用于彼此的对抗，或者担心谁输输赢。我们把精力放在解决问题上，通过学习具体的代替步骤来解决相关的问题。\u003c/p>\u003cp>图书介绍：\u003c/p>\u003cp>F:核心是“书”，用于满足好奇心。\u003c/p>\u003cp>这本《如何说 孩子才会听 怎么听 孩子才肯说》的书是由两位来自美国的作者共同完成的，他们分别是阿黛尔·法伯和伊莱恩·玛兹丽施，这两位国际著名亲子沟通专家的著作深受家长的欢迎，而且也得到专业权威人士的认可。\u003c/p>\u003cp>A:重点是“比较”，用于建立安全感。\u003c/p>\u003cp>这本书持续创造销售奇迹的家教图书\u003c/p>\u003cp>30年来不断再版并被译为30多种文字风靡全球，销量数百万；中文简体版正帮助越来越多中国父母收获良好的亲子关系和快乐的家庭氛围。\u003c/p>\u003cp>此书的侧重点在于“如何操作”，提供给家长们经验和方法，在家人自学这些技巧的同时，让他们（或者和朋友一起）按照自己的进度去实践，并提供给家长们可以借鉴的众多事例，以便他们能从中找到适合自己的最佳方法。\u003c/p>\u003cp>B:用于引发兴趣。\u003c/p>\u003cp>B1:这本融合爱与沟通技巧的神奇之书，无论在什么文化环境中，都可以让父母学会用有效、愉快的沟通方式与孩子建立亲子关系。\u003c/p>\u003cp>过渡:大家跟随我学习相关片段\u003c/p>\u003cp>B2:在我们深入了解惩罚的后果后，我们通过代替惩罚的方法与孩子建立良好的亲子关系。\u003c/p>","ratings_count":1,"texts":[{"id":14341,"quote":"\u003cp>【R:阅读原文拆页】\u003c/p>\u003cp>《如何说 孩子才会听 怎么听 孩子才肯说》\u003c/p>\u003cp>P114\u003c/p>\u003cp>每次在小组里讨论是什么触发家长惩罚孩子，你认为受罚的孩子会是什么感受时，我总会问大家:“为什么?我们为什么要惩罚孩子?”家长们讨论得越多，越理解惩罚会带来的感受:敌意、仇恨、抗议、罪恶感、没有价值感、自怜。然而，家长们仍然有担心，惩罚不解决问题，反而影响了孩子对自己的反思，那么我们该用什么来代替惩罚呢?\u003c/p>\u003cp>代替惩罚的方法\u003c/p>\u003cp>1.明确表达强烈不同意的立场\u003c/p>\u003cp>“我的新锯被扔在外面，都被雨淋得生锈了，我太生气了！”\u003c/p>\u003cp>2.表明你的期望\u003c/p>\u003cp>“我希望我的工具被借走以后，能完好无损地归还！”\u003c/p>\u003cp>3.告诉孩子怎样弥补自己失误\u003c/p>\u003cp>“现在需要用钢丝球使劲把上面的锈擦掉。”\u003c/p>\u003cp>4.提供选择\u003c/p>\u003cp>“你要么借我的工具及时归还，要么以后再也不能借。你来决定。”\u003c/p>\u003cp>5.采取行动\u003c/p>\u003cp>孩子：爸爸，你的工具箱锁上了！\u003c/p>\u003cp>爸爸：没错。我希望我的工具放在哪儿，还能在那儿找到。\u003c/p>\u003cp>6.解决问题\u003c/p>\u003cp>“我们想个办法，既能让你继续用，又能让我用的时候也能找到。\u003c/p>","explains":"\u003cp>【I：用自己的话描述原文拆页】\u003c/p>\u003cp>What：当我们说孩子做“对”的事情的时候，好像并不管用。他们不当回事儿，甚至会反抗我们。这时候，我们能想到的唯一办法就是惩罚。而代替惩罚的方法是解决问题，影响孩子对自己进去深入思考的七个循序渐进的方法。\u003c/p>\u003cp>Why:对于我们大多数人来说，挖苦、说教、警告、谩骂、威胁的词语已经植入我们的语言当中，因为，我们从小耳濡目染，所以当我们遇到触发的情景时，会想到用“惩罚”的方式来解决问题。我们对孩子的惩罚并不起作用，孩子的精力分散到了如何去报复家长上面，错失了对自己不当行为的反悔以及思考修正错误的机会，而这个过程对孩子又是非常重要的。\u003c/p>\u003cp>How:在遇到生活中触发惩罚的情景时，我们该用什么来代替惩罚?\u003c/p>\u003cp>01：请我们的孩子帮忙，比如，孩子把房间搞得脏乱，我们让自己的语言温和下来，邀请孩子和我们一起收拾，而不是用语言暴力的方式让这个问题继续发生。\u003c/p>\u003cp>02：明确表达我们对孩子的某种行为强烈不同意的立场（但不攻击孩子的人格）\u003c/p>\u003cp>03：表明我们对孩子的期望。\u003c/p>\u003cp>04：提供两种选择。或者和孩子商量多种选择后，让他从中选出更适合自己的方式。\u003c/p>\u003cp>05：告诉我们孩子弥补自己的失误的具体做法。\u003c/p>\u003cp>06：采取行动，帮助孩子拆解行动方案。\u003c/p>\u003cp>07：让我们的孩子体验错误行为的自然后果是什么。\u003c/p>\u003cp>【事例】书中触发惩罚的情景案例：\u003c/p>\u003cp>妈妈带孩子去超市，孩子各种乱拿东西，\u003c/p>\u003cp>妈妈：噢，等爸爸回来，有你好受的！（威胁的语气和懊恼的表情）\u003c/p>\u003cp>看到孩子对母亲语言毫无反应时，母亲继续说，\u003c/p>\u003cp>妈妈：你太鲁莽了。晚上不许看电视！（此时已加上指手画脚的动作）\u003c/p>\u003cp>孩子依旧我行我素，甚至比刚才更加坐立不安。\u003c/p>\u003cp>妈妈：你再乱跑，我就要动手了！\u003c/p>\u003cp>结果可想而知，孩子被妈妈当众打了一顿，孩子处于不明所以的状态中。\u003c/p>\u003cp>【不这样做的坏处】以上的例子告诉我们，\u003c/p>\u003cp>家长面对惩罚孩子的一般做法，会造成学校，家庭，社会方面的片面认识。\u003c/p>\u003cp>01：越是惩罚孩子，易造成孩子面对问题时不知如何解决从而逃避问题和管教。\u003c/p>\u003cp>02：孩子在处理未来的家庭关系时，会认为惩罚是唯一理解的管教方法。\u003c/p>\u003cp>03：孩子容易对家长有怨恨感，又因怨恨升起罪恶感。\u003c/p>\u003cp> 04：孩子会有挫败感，认为父母都是对的，我怎么做都是错的。\u003c/p>\u003cp>05：孩子会对父母的惩罚实施报复性行为，还会继续犯错，只要不被父母抓住。\u003c/p>\u003cp>【这样做的好处】通过学习了代替惩罚的方法，可以带来以下的变化\u003c/p>\u003cp>01：建立与孩子相互良好的亲子关系\u003c/p>\u003cp>02：尊重孩子的个性化差异。\u003c/p>\u003cp>03：我们代替惩罚的方法的运用，孩子也会这样通过模仿处理他的问题。\u003c/p>\u003cp>Where:无论身处困境，也无论是在家里遇到触发情景时，还是将来复杂的社会关系中，这个方法都能让我们与孩子共同受用。\u003c/p>","interaction":"\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>大家回忆一下，有没有类似的童年经历，比如你有没有被父母惩罚的经历?惩罚后你的感受是什么样的?比如父母让你去盛饭，结果你不小心打翻了碗筷，父母开始对你各种责骂，又比如，你想学舞蹈，父母为了节省开支，没给你报，你各种闹，父母对你进行语言暴力，说你压根不是那块料，你是什么样的感受呢?敌意、仇恨，抗议、没有价值感?\u003c/p>\u003cp>然后请大家想一下各自童年的相关经历，你当时的感受是什么，是什么事情，结果如何。\u003c/p>\u003cp>那接下来，我们给大家每人一分钟的讨论，请我们小组选出一位代表来分享一下。\u003c/p>\u003cp>学习者案例记录：学习者曼君分享，她说到在上二年级的时候，她学着蒸馒头，因为没有放碱面，蒸出来的馒头酸涩，她母亲说她，你怎么这么笨呀，你看我蒸了多少次馒头，你还学不会，因为母亲语言暴力相加和被贴上笨的标签后，在她后面的生活和工作中，但凡不顺，她会想起母亲这些话，会有挫败感，认为自己就是不行的感受。\u003c/p>\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>（引导）通过我们刚才的学习分享，大家回忆自己有没有过惩罚孩子的经历，或者在工作中被领导惩罚的经历呢。如果再回到从前，你会怎么做，结合刚刚从拆页中学习到的知识，请写出具体的行动步骤。(指令)\u003c/p>\u003cp>那接下来，给大家每人1-2分钟的时间，以组为讨论单位，谈论完毕我们请小伙伴们给大家分享一下。\u003c/p>\u003cp>学习者案例记录：学习者曼君分享，2018年有次她出差学习，她把老大放在姥姥家，因为老大不喜欢姥姥唠叨，指责的状态加上老大不喜欢姥姥做的饭，导致出差学习期间，曼君家的老大不开心之后，便是没怎么吃饭，等曼君回来对老大说，她不懂事，不知道心疼姥姥。整个训斥的过程是带着指责和抱怨，充斥着语言暴力的，后来老大给曼君写了封信，说，老师教同学们要换位思考，为什么自己的母亲没有做到呢。\u003c/p>\u003cp>曼君通过学习今天的片段:1.曼君请孩子来帮助，让孩子和姥姥之间沟通出，孩子喜欢吃什么可以和姥姥说，而不是赌气。2.明确表明曼君的立场，因为姥姥是曼君的妈妈，曼君希望自己的母亲是被尊重的。3.曼君和孩子沟通，可以和曼君沟通，大家一起商量解决。4问孩子的选择，是因为孩子情绪的问题，还是孩子想和奶奶在一起。5.告诉我们孩子弥补失误的具体做法。根据孩子的选择，帮助孩子分析有哪些失误。6.采取行动，帮助孩子拆解行动方案。看孩子选择哪个，问她为什么这样做的原因。7.孩子若是哪个都不选，可以选择和谁在一起，不想吃饭的话，可以饿着，承担自己错误行为带来的后果。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1600740966000,"updated_at":1602729258000,"ria":true},{"id":6609,"topic":"如何帮助孩子面对感受","learn_goal":"学会帮助孩子面对感受","remark":"","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"冯臻","city":"重庆市"},"club":{"name":"重庆山城分舵","city":"重庆市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;大家好，我是冯臻，学名叫九楠。\r\n寓意，经历九九八十一难，到达彼岸。\r\n现在我的工作是做外贸，比较喜爱国学中的儒释道。\r\n今天很高兴和大家相遇，感谢大家来见证我的1-1打怪之旅。\r\n &nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>\u003cstrong>在坐\u003c/strong>\u003cstrong>的\u003c/strong>\u003cstrong>小伙伴\u003c/strong>\u003cstrong>大部分都喜欢学习\u003c/strong>\u003cstrong>，\u003c/strong>\u003cstrong>但不少人会\u003c/strong>\u003cstrong>常遇到三大问题：\u003c/strong>\u003c/p>\u003cp>1.&nbsp;\u003cstrong>书太多\u003c/strong>\u003cstrong>，没有时间看；\u003c/strong>\u003cstrong>2、专业书籍，内容深奥，又看不懂；3、好不容易\u003c/strong>\u003cstrong>看\u003c/strong>\u003cstrong>完了\u003c/strong>\u003cstrong>一\u003c/strong>\u003cstrong>整本书，过段时间就忘了，记不住，也没能运用；\u003c/strong>\u003cstrong>\u003cbr>\u003c/strong>\u003cstrong>而如果有一种办法可以同时解决这个三个问题，该多好啊！\u003c/strong>\u003c/p>\u003cp>\u003cstrong>在这种背景下，拆书就应运而生了。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>那拆书是什么呢？拆书就是精准的把自认为有用的书中的片段，单独拿出来学习，吸收，转化成自己的能力！\u003c/strong>\u003c/p>\u003cp>\u003cstrong>当然它分为个人和群体两部分：\u003c/strong>\u003c/p>\u003cp>1.&nbsp;\u003cstrong>个人的，是运用\u003c/strong>\u003cstrong>RI\u003c/strong>\u003cstrong>A便签读书法\u003c/strong>\u003cstrong>单独学习，提升自己的能力；\u003c/strong>\u003c/p>\u003cp>2.&nbsp;\u003cstrong>群体的是，一个拆书家带领一群人，利用\u003c/strong>\u003cstrong>RI\u003c/strong>\u003cstrong>A便签读书法\u003c/strong>\u003cstrong>，\u003c/strong>\u003cstrong>把一本书\u003c/strong>\u003cstrong>加工成一场现场学习\u003c/strong>\u003cstrong>，\u003c/strong>\u003cstrong>在\u003c/strong>\u003cstrong>提升\u003c/strong>\u003cstrong>自我能力的同时促进其他学习者共同进步。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>而拆书帮呢?\u003c/strong>\u003c/p>\u003cp>\u003cstrong>就是基于拆书法，在全国各个，一帮爱好学习的公益性的社群，或者称为青年自组织，使命是帮更多学习爱好者成长为拆书家。\u003c/strong>\u003c/p>","ratings_count":1,"texts":[{"id":9942,"quote":null,"explains":"\u003cp>\u003cstrong>好的，大多数小伙伴都已读完片段。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>通常我们指责孩子时，他们经常闹情绪，耍小孩子脾气，实际上是孩子无法面对他们的感受。\u003c/strong>\u003cstrong>那\u003c/strong>\u003cstrong>要怎么才能帮助孩子面对他们的感受\u003c/strong>\u003cstrong>呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>只要\u003c/strong>\u003cstrong>四\u003c/strong>\u003cstrong>个步骤，就\u003c/strong>\u003cstrong>能让你做到\u003c/strong>\u003cstrong>。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第一步：\u003c/strong>\u003cstrong>看着对方的眼睛倾听；\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第二步：\u003c/strong>\u003cstrong>对方每说完一个意思，就\u003c/strong>\u003cstrong>用简单的话语回应他们同频率\u003c/strong>\u003cstrong>；\u003c/strong>\u003cstrong>（用嗯、啊，原来是这样，这种简单话语回应他们。）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第三步：\u003c/strong>\u003cstrong>听完后，用自己的理解\u003c/strong>\u003cstrong>说出他们的感受\u003c/strong>\u003cstrong>；\u003c/strong>\u003cstrong>（\u003c/strong>\u003cstrong>这有点像咱们拆书帮的I\u003c/strong>\u003cstrong>）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第四步：告诉对方自己幻想着实现他们的愿望是什么样子；\u003c/strong>\u003c/p>","interaction":"\u003cp>\u003cstrong>每天我都要叫我的女儿起床，但\u003c/strong>\u003cstrong>她\u003c/strong>\u003cstrong>总是\u003c/strong>\u003cstrong>有起床情绪\u003c/strong>\u003cstrong>。因此每次叫久了\u003c/strong>\u003cstrong>不起来\u003c/strong>\u003cstrong>就没有耐烦心\u003c/strong>\u003cstrong>了。\u003c/strong>\u003cstrong>要么开始威胁她，要么开始吼她，最后就是哭哭啼啼的起床，一整天都不开心。那个时候我也不知道怎么做，并且觉得自己这样做没有问题。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>出现问题的原因是，女儿无法面对必须起床的感受，而我又没有帮她面对她自己的感受。这时她情绪就容易失控，总是哭闹。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>但在学了这个方法后，\u003c/strong>\u003cstrong>如果时光倒流，可以再来一次，\u003c/strong>\u003cstrong>我会这样做：\u003c/strong>\u003c/p>\u003cp>1.&nbsp;\u003cstrong>先问宝宝你怎么还不起床啊，她说我还想睡，不想去上学；\u003c/strong>\u003c/p>\u003cp>2.&nbsp;\u003cstrong>我一边听她说，一边用哦，恩，啊的\u003c/strong>\u003cstrong>简单话语\u003c/strong>\u003cstrong>回应她。\u003c/strong>\u003c/p>\u003cp>3.&nbsp;\u003cstrong>等她说完后，我就说，你是不是太困了，天又冷，所以不想起床，只想睡觉啊？\u003c/strong>\u003c/p>\u003cp>4.&nbsp;\u003cstrong>她听到会说是，然后我就开始和她一起做白日梦，如果我们都可以不起床，都一直睡懒觉，不上班，不上学，那该有多好啊。一起幻想一下，开心一下也是没有问题的。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我想\u003c/strong>\u003cstrong>虽然\u003c/strong>\u003cstrong>开始\u003c/strong>\u003cstrong>不愿起床\u003c/strong>\u003cstrong>，但\u003c/strong>\u003cstrong>在我帮她面对了自己感受之后，心情调整好了，起床也会开心顺利了。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习了\u003c/strong>\u003cstrong>“第一章”提炼出来的这四4个步骤之后，我运用此方法给自己总结了一个帮助孩子面对自己的\u003c/strong>\u003cstrong>感受\u003c/strong>\u003cstrong>的目标；\u003c/strong>\u003c/p>\u003cp>\u003cstrong>在下一周\u003c/strong>\u003cstrong>中，\u003c/strong>\u003cstrong>如果遇到\u003c/strong>\u003cstrong>女儿\u003c/strong>\u003cstrong>玩耍的时候闹情绪，我就会用四步法来帮助\u003c/strong>\u003cstrong>她面对\u003c/strong>\u003cstrong>自己的\u003c/strong>\u003cstrong>感受\u003c/strong>\u003cstrong>：\u003c/strong>\u003c/p>\u003cp>1.&nbsp;\u003cstrong>先问宝宝你怎么玩得不开心啊；\u003c/strong>\u003c/p>\u003cp>2.&nbsp;\u003cstrong>当她回答时，\u003c/strong>\u003cstrong>我就\u003c/strong>\u003cstrong>一\u003c/strong>\u003cstrong>边听\u003c/strong>\u003cstrong>她\u003c/strong>\u003cstrong>说，\u003c/strong>\u003cstrong>一边用\u003c/strong>\u003cstrong>哦，恩，啊\u003c/strong>\u003cstrong>的简单短语\u003c/strong>\u003cstrong>回应她\u003c/strong>\u003cstrong>；\u003c/strong>\u003c/p>\u003cp>3.&nbsp;\u003cstrong>等她说完后，我\u003c/strong>\u003cstrong>用自己的理解，\u003c/strong>\u003cstrong>站在她的角度说出她的感受\u003c/strong>\u003cstrong>；\u003c/strong>\u003c/p>\u003cp>4.&nbsp;\u003cstrong>她听\u003c/strong>\u003cstrong>完并说是一类词，确认我理解她了后，\u003c/strong>\u003cstrong>我就开始和她一起做白日梦，如果\u003c/strong>\u003cstrong>没有这个障碍，\u003c/strong>\u003cstrong>我们可以\u003c/strong>\u003cstrong>怎么样玩\u003c/strong>\u003cstrong>，那该有多好玩啊。\u003c/strong>\u003cstrong>一起\u003c/strong>\u003cstrong>幻想着实现\u003c/strong>\u003cstrong>她\u003c/strong>\u003cstrong>的愿望。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>相信做完这些，她会有感觉，我和她一起面对了她的感受，心理会好受一些了。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>一般情况下，\u003c/strong>\u003cstrong>这个方法是可以用在处理孩子闹情绪\u003c/strong>\u003cstrong>，\u003c/strong>\u003cstrong>难以面对自己感受\u003c/strong>\u003cstrong>的时候\u003c/strong>\u003cstrong>。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>如果遇到特别固执的小孩，那就需要用其它的方法，比如软硬兼施，黄金棍下出好人。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我的分享完了，希望大家在便签上写下对我这次分享的看法和建议。谢谢大家。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003cbr>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003cbr>\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1543545695000,"updated_at":1543547087000},{"id":5863,"topic":"用便签沟通法提升合作度","learn_goal":"学习者学会用便签和他人沟通提升合作度","remark":"","level":"TF3-1","duration":30,"status":29,"type":0,"chaishujia":{"username":"丹丁先生","city":"常州市"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>大家好，我是丁丹，为了方便记忆可以叫丹丁先生——这还是一个影响历史的人物。三个标签：管理顾问是我目前的职业、人力资源是我的专业领域、情怀勇士是我的处世态度。有时做事不为权和利，就为了那点情怀。拆书帮也正是需要这种情怀的组织，我也愿意伴随大家一同学习成长。今天很高兴给大家进行TF3-1的拆书分享。\u003c/p>\u003cp>分组：为了让大家能够进行充分的沟通和智慧连接，根据现场情况我们两两分组。\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，（行为）学习者能够运用便条沟通法（界定）来提升孩子的合作度，从而积极地配合父母，避免暴力沟通。\u003c/p>\u003cp>今天我拆析的书名是《如何说孩子才会听，怎么听孩子才肯说》\u003c/p>\u003cp>本书的作者是两位美国妈妈——阿黛尔•法伯和伊莱恩•玛兹丽施，也是国际著名亲子沟通专家，家庭教育畅销书的作者。\u003c/p>\u003cp>【事件场景】在日常生活中，家长常常会一遍又一遍地教导孩子、要求孩子按照家长的规范或期望做事。回想我们的一天，早上催促着孩子赶紧起床不要赖床；然后催促赶紧吃早餐不要拖拉；路上还得一遍遍要求上课认真听讲；放学后要先做完作业再玩；晚上睡觉前要求整理好书包不要丢三落四。但是孩子对此似乎根本不予理会，或者今天听了，明天又重蹈覆辙。接下来就是父母的抱怨、谩骂、甚至是毒打。\u003c/p>\u003cp>【提问】孩子为什么会这样呢？你是否也遇到过类似的情形？你是如何处理的？处理的结果怎样？到底是家长做错了，还是孩子天生就顽固不听话？\u003c/p>\u003cp>【影响】很多家长都责怪孩子不听话，不合作，但是没有真正意识到是自己教导方式的不恰当。长此以往，孩子与家长因缺少心灵的沟通而造成叛逆，合作程度降低。甚至对抗。跳楼、自杀、弑母的极端案例也屡见不鲜。\u003c/p>\u003cp>【解决】在本书中作者通过大量研究，列举了很多鼓励孩子与家长合作的方法，今天讲解一个我运用最有效的方法——便条沟通法来提升孩子的合作度，从而积极地配合父母，避免暴力沟通。\u003c/p>","ratings_count":3,"texts":[{"id":9077,"quote":"\u003cp>接下来请用2分钟时间阅读我用荧光笔标注上下箭头的拆页部分，请完成的伙伴举手向我示意。\u003c/p>\u003cp>拆页原文：《如何说孩子才会听怎么听孩子才肯说》P85-86\u003c/p>\u003cp>1写便条\u003c/p>\u003cp>不管孩子认不认字,他们都期望收到小便条。年纪小一点的孩子,在收到父母的便条时,会很开心。这样,还可以鼓励他们回复父母的便条。大一点的孩子也喜欢收到便条。一群曾和我们一起合作过的少年告诉我们,收到便条会让他们感觉很好。“就像收到一位朋友来信。\u003c/p>\u003cp>&quot;他们被父母抽时间花精力给他们写便条的行为所打动。一位少,年认为便条最大好处就是:“他们不用大声嚷嚷了。”\u003c/p>\u003cp>家长们也喜欢写便条的方式。省时、便捷,而且有的还很值得回味。\u003c/p>\u003cp>一位母亲告诉我们,她的橱柜上一直放着一沓便笺和装了一打铅,笔的旧咖啡杯。以前,她发现自己经常处于这样的境地:要么她为同一件事,喊好几遍孩子们,要么就是干脆不叫他们,自己做家务了。后来,她发现,拿起笔来写比总张嘴喊省力得多。下面是她写的一些便条;\u003c/p>\u003cp>亲爱的比利:\u003c/p>\u003cp>从今天早上起,我就一直没出去过。让我放松一下。\u003c/p>\u003cp>你的小狗:哈里\u003c/p>\u003cp>亲爱的苏珊:\u003c/p>\u003cp>厨房该规整了。\u003c/p>\u003cp>需要收拾一下:\u003c/p>\u003cp>1.炉子上的书2.门口的靴子3,地板上的夹克4,桌子上的饼干屑\u003c/p>\u003cp>多谢！\u003c/p>\u003cp>妈妈\u003c/p>\u003cp>请注意：\u003c/p>\u003cp>今晚讲故事时间:晚上7:30,欢迎穿睡衣、刷过牙的小孩参加。\u003c/p>\u003cp>爱你们的爸爸、妈妈\u003c/p>\u003cp>虽然轻松的语气加强了效果,但便条上的语气并不一定都是温和的。有的时候,情况可能并没有那么有趣,幽默也不起作用。比如下面这位父亲的经历就是这样:他的女儿把他刻录的新CD弄坏了,并且还扔在了地上。他说,如果不是用写便条的方式发泄他的愤怒,他肯定会惩罚她。\u003c/p>\u003cp>阿莉森:\u003c/p>\u003cp>我气坏了!!!\u003c/p>\u003cp>我的新CD未经允许被拿走,上面都是划痕。不能再听了。\u003c/p>\u003cp>气愤的爸爸\u003c/p>\u003cp>过了一会,父亲收到女儿的回复:\u003c/p>\u003cp>亲爱的爸爸:\u003c/p>\u003cp>真对不起。我这周六给你买个新的。不管多贵,都从我的零花钱里扣。\u003c/p>\u003cp>阿莉森\u003c/p>","explains":"\u003cp>【WHAT+WHY】 在亲子关系中，教导孩子的行为符合社会规范是一项艰巨的工作，这源自于家长和孩子在需求上的矛盾。成人需要的是外表整洁、讲秩序、懂礼貌、按流程办事。孩子可不在意这些。有多少孩子会自觉自愿地去洗澡、去认真看书学习。家长花很多精力调教孩子，让孩子的行为符合规范。但是家长的态度越强烈，孩子越是反抗。因此家长们更需要一种缓和的沟通方式——便条沟通法，以此表达对孩子的理解，让孩子自己认识自己并理解他人，从而自觉改变他的行为。\u003c/p>\u003cp>【WHAT对比】那什么是便条沟通法呢？便条大家都能理解，那什么是沟通呢？百度说：沟通是人们分享信息、思想和情感的任何过程，不仅包含口头语言和书面语言，也包含形体语言、个人的习气和方式、物质环境赋予信息含义的任何东西。接下来我举几个例子，我们详细对比一下。第一周末早上小明还在睡觉，妈妈要外出，给小明留了一个条：“小明，早餐在微波炉里，妈妈。”这个属于便条沟通法吗？不是，因为这个就说明的一个情景而已，没有传达清楚任何思想和感情。好，我们再来，妈妈写到：“起床后记得吃早餐，放在微波炉里！妈妈。”这个属于便条沟通法么？不是，这里充满了命令和说教，没有情感的交互。好，再来一次，“早餐放在微波炉里，妈妈一早就做好了，你早餐能吃得饱饱的，妈妈一定会很高兴，你也会一天很有力量。勤劳的妈妈。”这个是便条沟通法吗？对了，这个就达到了沟通目的，不但说明了情境，传递了感情，同样也说明了期望。为什么有时我们写便条就没有达到预期的结果呢？正因为前两个案例这并没有改变暴力沟通的本质。责备、命令、威胁、说教、警告本质上就不容易让对方接受。因此正确便条沟通法至关重要。\u003c/p>\u003cp>【HOW】那么如何做好便条沟通法呢，我们可以通过以下三个要素：\u003c/p>\u003col>\u003cli>\u003cp>说明情境，用简单的语言描述一下我们目前面临的情境，大家身处情境，因此不用太过于冗繁。\u003c/p>\u003c/li>\u003cli>\u003cp>表达感受，说明你对这个情境的真实感受。比如愉快或生气。\u003c/p>\u003c/li>\u003cli>\u003cp>明确期望，这一要素是最为重要的。提出你对他行为的明确期望，视情况可以增加给予正面评价或鼓励对方给予承诺。\u003c/p>\u003c/li>\u003c/ol>\u003cp>【预防性异议】有人会问：“我们用了这个技巧，孩子们就会一直听我们的吗？”其实我们希望不是这样，孩子不是机器人。我们的目的不是用一套技能去操控孩子，好让孩子言听计从。\u003c/p>\u003cp>【强化概念】我们的目的在于在说明情境中提升孩子的认知度、和责任心。在表达感受中我们想找到一种语言，培养孩子的自尊以及体谅他人需求的能力。在明确期望中我们想建立一种情感的氛围，鼓励孩子与家长合作。【适用范围】家长要树立一个榜样，让孩子在相互尊重的平台上与人沟通。无论是在天真无暇的童年、叛逆的青春期，还是长大成人以后都能受用。\u003c/p>\u003cp>【举例子】寒假中，本想好好休息，而孩子一大早7点醒来就要来打开电视看“跑男”，一集又一集看，直到父母全部起身吃早餐前都依依不舍，慢吞吞起身再洗漱。一连好几天都如此。于是我决定使用书中写便条技能，在他临睡前我写了一个便条，放在他的床头，告诉他明天起床后再看。内容如下：“儿子，假期到了，我希望可以稍微休息一下，但每天早晨你的吵闹让我很讨厌。如果早上醒来早，你可以先自己进行洗漱然后读会书，8点来喊我。希望看到你早上认真读书的背影。爸爸。”第二天，情况就按照我便条上写得那样发生了。\u003c/p>","interaction":"\u003cp>拆书家提问设计（逐字稿）：好，接下来我们一同来练习写便条的方法。首先大家先思考一下，在未来的两周内，我们与孩子或者配偶，也可以是朋友或同事，你希望他配合你完成的一件事情，并将发生的事情在小组内编写一个简短的剧本。说明清楚故事中的时间、人物、地点，事情的起因、经过、结果，最重要的是你如何将今天讲解的3个要素（说明情境、表达感受、明确期望）融会贯通在便条中。故事中要设计一些对话、心里独白或反馈便条的信息。时间5分钟。5分钟后我们请一个小组来讲讲他们的故事。现在开始。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>背景：先生工作比较繁忙，每天晚上睡觉比较晚，希望能早点休息。\u003c/p>\u003cp>人物：妻子和先生\u003c/p>\u003cp>地点：家里\u003c/p>\u003cp>时间：晚上，吃过晚饭\u003c/p>\u003cp>太太：今天我给你写了一个便条，\u003c/p>\u003cp>丈夫：啊？还给我写个便条？\u003c/p>\u003cp>太太：嗯，你待会儿去看下，在你书桌的台灯下面。\u003c/p>\u003cp>丈夫：好的。\u003c/p>\u003cp>便条内容：\u003c/p>\u003cp>每天晚上睡觉很晚，我希望你可以早点休息。每天晚上很晚睡早上催起床让我很讨厌，身体也会吃不消。如果确实要晚，建议不要超过11点，你可以设立一个闹钟，早点休息，第二天早点起来再做。\u003c/p>\u003cp>爱你的太太\u003c/p>\u003cp>丈夫心里想：我这样做确实不太对，每天睡得太晚，而且屡教不改，自己身体拖垮了还影响家人的休息。我准备调整一下自己的生物钟，争取改变这个坏习惯。\u003c/p>\u003cp>【号召鼓掌】大家掌声感谢两位伙伴的分享。【摘要点评】在这个情境中，伙伴们运用了说明情境，睡觉比较晚，第二表达感受，对身体不好影响他人，比较讨厌。然后提出了明确的期望，包括设定闹钟和11点前休息等。都运用到了这三个步骤。做得很好。\u003c/p>\u003cp>写便条提升合作度，就是如此简单，你一定跃跃欲试了吧，今天晚上回家就先实战一下吧。在这本书中还有很有效的方法有待你去学习，我相信你一定能掌握更多“如何说，怎么听”的技巧。以上就是我的TF3-1的分享。感谢大家的参与。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1534774278000,"updated_at":1543070891000,"ria":true},{"id":4496,"topic":"如何提建议","learn_goal":"完成本次学习后，能够运用尊重对方的四个步骤，提供建议","remark":"","level":"TF2-3","duration":30,"status":30,"type":0,"chaishujia":{"username":"姚莉","city":"成都市"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"我们先分组，两人一组。我先给大家一个提示，我今天分享的段子，同时适用于成人和孩子。\r\n大家好，我是姚莉，很高兴和大家分享今天的段子。我有三个标签，第一个是学习，因为我喜欢学习，第二个是亲子教育，因为我有孩子，第三个是写作，我喜欢写文章。\r\n【图书介绍】\r\n今天给大家分享的段子来自于一本书，书名叫做《怎么说 孩子才会听 如何听 孩子才肯说》。【F】本书作者是美国的两位妈妈，也是国际著名的亲子沟通专家。本书讲了六种模式，有助于建立平等、和睦、愉快的亲子关系。【A】与其他同类书不同的是，这本书拥有大量的情景模拟和强大的可操作性，包括了理论讲解、实践操作、使用原则、温馨提示等内容。【B】所以，我们理解并有效使用了本书的理念，可以循序渐进的学会用有效、愉快的沟通方式，与孩子建立亲子关系，并最终帮助孩子成为独立、自强、充满爱心和责任感的人。\r\n【学习目标】\r\n今天，大家在跟随我完成本次RIA现场学习后， 能够理解提出建议的四个步骤“说出想法、重述问题、提供资源、提出建议”，并且在面对求助时，能够运用这四个步骤，为对方提供建议。","ratings_count":1,"texts":[{"id":7510,"quote":"\u003cp>&nbsp; &nbsp; &nbsp;&nbsp;有一次，我们在给家长小组讲“给孩子建议会影响孩子自立”的时候，很多家长立刻举起手来。他们觉得“这太不着边际了！”他们不能理解为什么不能把家长的聪明才智分享给孩子。下面是一位固执己见的母亲的问题以及我们的回答。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; “孩子遇到问题时，我为什么不能给他建议帮助他？例如：我的女儿朱莉叶，犹豫去不去参加她朋友的生日聚会，因为她不喜欢她朋友邀请的那些人，他们经常说别人坏话、骂人。我告诉她：你应该去，要不然朋友该失望了。这有什么错吗？”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 如果你马上给她建议，她要么觉得自己太傻（“我为什么自己没有想到呢？”），或怨恨（“别干涩我的事情！”），要么被激怒（“你真以为我不知道怎么处理吗？”）\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 当孩子自己想清楚该怎么做的时候，他有信心并且愿意为自己的决定负责。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; “照你这么说，孩子遇到问题的时候，我就什么也不管吗？我曾经有几次对朱莉叶说：这是你的问题，你自己处理。她似乎很不开心。”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 家长忽略孩子提出的问题时会让孩子感觉受到伤害，或者被离弃。在忽略孩子的问题和立即给出建议这两个极端之间，家长还可以做很多。 在她完全理清了自己的想法和感受以后，她就能认真倾听你的建议——特别是你用尊重她的方式说出你的建议：\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;“朱莉叶，听你刚才所说的，你的心理很矛盾：一方面，你想参加朋友的聚会，另外一方面，你不喜欢她要求的那些女孩。”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; “所以，现在的问题是：找到一个办法，既能参加生日会，又能躲开那些你不喜欢的女孩。”\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 问完问题后，最好停顿一下，有利于让孩子自己静下心来想出解决办法。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; “我相信有关于青少年如何处理社交问题的网站，看看上面是怎么说的。”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; “你觉得这样好不好。把那盘新的搞笑视频带到生日聚会上。那些女孩也许就光顾着笑，没有时间说别人的坏话了。”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 孩子把自己的问题琢磨透了，才会倾听父母的想法和劝说：\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; “就因为那几个女孩错过了生日聚会多可惜。”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; “我觉得不应该让朋友过生日的时候失望，尽管需要你委曲求全。”\u003c/p>","explains":"\u003cp>好的，我看到绝大部分小伙伴都已经看完段子了，没有看完的伙伴也不用着急，跟着我的节奏就OK。下面我先分享一下我对这个段子的解读：\u003c/p>\u003cp>【WHAT】段子告诉我们，面对孩子的求助，我们要以尊重对方的方式说出自己的建议。\u003c/p>\u003cp>【WHY】因为我们最习惯的两个方式：忽略孩子问题和立刻给出建议，都会给孩子带来负面情绪，前者可能会让孩子感到自己被当成了路人甲，后者会可能让孩子产生自卑自怨，甚至养成依赖性。而尊重对方的方式可以帮助孩子理清自己的想法和感受，认真倾听我们的建议。\u003c/p>\u003cp>【细化行动步骤（一般的行动建议：特别是你用尊重她的方式说出你的建议）】那如何才能够做到呢？我们可以通过四个步骤来实现：\u003c/p>\u003cp>1.说出想法。用“你是不是觉得……”来说出对方心里的想法。\u003c/p>\u003cp>2.重述问题。用“现在的问题是……”来再一次描述问题。\u003c/p>\u003cp>3.提供资源。提供可借用的权威的资源，例如医生、律师、书籍、网络等等。\u003c/p>\u003cp>4.提出建议。用“你觉得……”或者“你想到过……”的方式来叙述建议。\u003c/p>\u003cp>举例：\u003c/p>\u003cp>我给大家举一个职场上很常见的例子：下级给上级布置工作。我以前就常常陷入这种被动局面。一些经验不足的质检员没有信心准确把握合格尺度，于是经常向我求助。通常我的做法是直接到现场，仔细检验，然后告诉他，我的判定结果是什么。这么做很显然我的时间被大量耽误，而质检员始终无法积累工作经验。可是，如果我要求质检员自己下判断，质检员会很不高兴，他们认为我对工作不负责任，那么他们也有可能会草草检验了事。后来我找到机会使用了上述的四个步骤。\u003c/p>\u003cp>质检员说：领导，这批产品的颜色，我拿不准是否合格。我觉得颜色偏红的明显，但是车间主任认为只是微微偏红。\u003c/p>\u003cp>我说：你是不是觉得这批产品已经偏红得不合格了，但车间主任认为是合格的？ 【这是说出想法】\u003c/p>\u003cp>质检员说：对啊，颜色完全凭肉眼看，每个人的眼睛对颜色的敏感度不一样，我觉得已经明显偏红了，可是车间主任认为我判断不准。而且，万一我们放行了，但是客户不接受，我们还是要被投诉的。\u003c/p>\u003cp>我说：那现在的问题就是：我们要找到一个判断依据：这样我们就不用凭个人的主管感觉来判断是否合格，而且还可以统一客户对颜色的要求。【这是重述问题】\u003c/p>\u003cp>质检员说：就是啊。 \u003c/p>\u003cp>我说：我想，同行们也会遇到这个问题的，你可以向他们打听打听他们的处理办法，也可以了解了解客户的要求是什么。【这是提供资源】\u003c/p>\u003cp>质检员：那我们可以去问问同行，还可以找某某地产商，他们对颜色的要求最苛刻，他们觉得不合格颜色的产品，可以做为我们判断依据。\u003c/p>\u003cp>我最后说：你觉得这个办法咋样：我们多收集几份不合格颜色的产品，然后制定一份企业内控标准，把颜色这个指标明确化。并且传达到每个质检员手上，产品销售合同上也要注明这个标准。【这是提出建议】\u003c/p>\u003cp>最终，我用这四个步骤，让质检员高高兴兴的接受了我的建议，并且以后再也没有因为类似的问题而再次找我。\u003c/p>\u003cp>好的，我给大家再总结一下，我们要用尊重对方的方式说出我们的建议，具体四个步骤是“说出想法、重述问题、提供资源、提出建议。”当然，并不是每次都需要把四个步骤都全部用上才效果。\u003c/p>\u003cp>适用边界：\u003c/p>\u003cp>同时，我还有必要给大家一个温馨提示：如果求助者只是想通过求助，达到把问题甩出去的目的，就不适合使用这四个步骤了。\u003c/p>","interaction":"\u003cp>A3促动学习者现场演练：\u003c/p>\u003cp>拆书家提问设计：\u003c/p>\u003cp>好了，我们刚刚学习了如何用尊重对方的方式说出建议。现在我们一起来练习练习，如何使用这四个步骤。\u003c/p>\u003cp>【场景设计】请大家注意听练习内容：近段时间江歌被害案引发了全民大讨论，这个案子提醒我们，找男票女票一定要慎重。而我们一位漂亮妹妹也遇到了类似的问题，她犹豫着要不要和现在的男票分手，于是她找到闺蜜，请闺蜜帮她出出主意。\u003c/p>\u003cp>【小组讨论】我们先在小组内练习，两人组队，一人扮演漂亮妹妹，一人扮演闺蜜。闺蜜使用上面的四个步骤，为漂亮妹妹提供建议。\u003c/p>\u003cp>练习时间10分钟，现在开始。十分钟后，我会请一到两组伙伴现场表演，大家来听听他们怎么说。\u003c/p>\u003cp>【角色扮演】&nbsp;\u003c/p>\u003cp>Ashly组分享：Ashly扮演漂亮妹妹，名字叫小红，王俊扮演闺蜜，名字叫小黑。小红觉得男朋友对自己很好，但是控制欲很强，小红想分手却下不了决心。于是找到小黑，请小黑出主意。小黑说：你是不是觉得很矛盾【说出想法】。小红回答：是。小黑说：现在的问题是，既可以分手，又可以减轻分手的失落感，对吗？【重述问题】小红回答：是。小黑说：那就这样吧，近段时间你多参加拆书帮的活动，可以接触更多的人和更多的想法【提供资源】。小红回答，好的。小黑说：你看这样行不行，你通过拆书帮活动，减少你对男朋友的心理依赖，同时，可以考虑从拆书帮中找到合适的男生【提出建议】。\u003c/p>\u003cp>菜菜组分享：菜菜扮演漂亮妹妹，骆骆扮演闺蜜。菜菜觉得自己男朋友投入很大的精力在工作上，忽视了自己，于是想分手，却下不了决心，于是征求骆骆的建议。第一步，说出想法，骆骆先问：你是不是有想分手的想法【说出想法】，菜菜点头。骆骆说：现在的问题是，你觉得自己的男朋友非常上进，所以工作很认真刻苦，可是照顾家里的时间也很少了【重述问题】，菜菜说：是。骆骆继续说：你可以考虑寻找心理方法的专家，进行咨询。【提供资源】，菜菜继续点头。骆骆最后说：你看这样好不好，心理咨询专家可以帮助你寻找到自己心里真正的需求，如何对待老公的上进和家庭缺失陪伴【提出建议】。\u003c/p>\u003cp>好的，谢谢两组伙伴的分享。大家理解了这四个步骤了吗？它们是“说出想法、重述问题、提供资源、提出建议”。也希望大家在日常生活中能够使用起来这四个步骤，让我们的沟通更通畅，让我们的关系更和谐。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1516030568000,"updated_at":1516356539000,"ria":true},{"id":4405,"topic":"如何赞赏性表扬孩子","learn_goal":"了解赞赏性语言，学会用赞赏性语言表扬孩子","remark":"本书的作者美国的阿黛尔.法伯和伊莱恩.玛兹丽施合著的，二位女士都是国际著名的亲子沟通专家。本书曾经荣登《纽约时报书评》畅销书排行榜第一名！本书的核心是为读者提供一种建立在平等、相互尊重基础上与孩子的交流方式和沟通技巧。","level":"TF1-1","duration":13,"status":0,"type":0,"chaishujia":{"username":"阿贞","city":"常州"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":null,"ratings_count":0,"texts":[{"id":7599,"quote":"\u003col>\u003cli>\u003c/li>\u003c/ol>","explains":null,"interaction":null,"flags":{"r":true,"i":false,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1515245320000,"updated_at":1515245320000},{"id":4403,"topic":"如何描述性赞赏孩子","learn_goal":"学会用描述性语言赞扬孩子、与孩子快乐沟通","remark":"","level":"TF1-1","duration":12,"status":30,"type":0,"chaishujia":{"username":"阿贞","city":"常州"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"各位小伙伴晚上好，今天晚上很高兴有机会给大家做TF1-1的拆书分享。\r\n首先自我介绍一下，我叫阿贞，坚贞不屈的贞,女贞树的贞，木头的孩子,森林中一棵坚强的树。三个标签，心理咨询师，职业培训师，未来的拆书家。\r\n拆书？拆书帮，什么意思？大家心中是不是有很多问号？\r\n1.关于拆，大家看我手，假设这是一小段破旧不堪即将报废的石墙，有一天你突然发现上面有一块小砖头自己很喜欢，你就用手拆下来揣在口袋里带回家，稍微一打磨放在客厅成了一个小艺术品。你这是这是拆墙拆砖。同样的道理\r\n2.拆书，就是你看到书中的一个片段很有感触，就用一定的方法把它记在你的心里，并落实到行动上，也就是将知识转变为内在的能力，从而做到真正的知行合一，这种读书的方法就叫做拆书。所以拆书就是针对成人学习过程中容易出现的没时间、记不住、用不上等问题而产生的一种学习方法。拆书法又叫RIA便签法。\r\n3.拆书分为个人学习的拆书和组织学习的拆书两种。组织学习型拆书就是我们今天现场的这种学习，是拆书家通过一本书加工出一场现场学习，引导和促进所有的参与者将相关的知识拆为己用。","ratings_count":1,"texts":[{"id":7411,"quote":"\u003cp>&nbsp; &nbsp; &nbsp;P182-183\u003c/p>\u003cp>也许你已经感觉到了赞赏性所隐含的问题。除了感觉不错以外，可能还会有以下这些反应：\u003c/p>\u003cp>赞赏可能会让被赞赏的人产生怀疑。（他真觉得我很会做饭？他要么在撒谎，要么就是不懂美食。）\u003c/p>\u003cp>赞赏可能导致否认。（总是光彩夺目？---你没看见我一小时以前的样子。）\u003c/p>\u003cp>赞赏可能会带来压力。（我下次开会该怎么穿呀？）\u003c/p>\u003cp>赞赏可能会让我们关注到自己的弱项。（才华横溢？开玩笑吧？我连把表上的数字加起来都还不会。）\u003c/p>\u003cp>赞赏可能会引起焦虑，干扰他们的行动。（我再打不出那么好的球了，现在我真的有点紧张。）\u003c/p>\u003cp>赞赏还可能会感觉被控制。（这个人想从我这儿得到什么好处吗？）\u003c/p>\u003cp>我记得在赞赏自己孩子似的遭遇。他们拿过来一幅画给我看，问我：“画的好吗？”\u003c/p>\u003cp>我说：“多好的一副画呀！”\u003c/p>\u003cp>他们问：“怎么好了？”\u003c/p>\u003cp>我说：“怎么好？多美啊！---太漂亮了！”\u003c/p>\u003cp>他们说：“你根本不喜欢。”\u003c/p>\u003cp>我越是表达我的赞赏他们越不领情，我真搞不懂他们反应为什么会这样。\u003c/p>\u003cp>参加了基诺特博士的前几次课程后，我开始明白为什么我越表扬孩子，孩子越拒绝。他告诉我评价事物的词语比如“挺好”“真美”“太妙了”会让孩子产生和我们刚才练习里一样的不舒服的感觉。最重要的是我从她那里学到了有益的赞赏来自两个方面：\u003c/p>\u003col>\u003cli>\u003cp>描述他所看到的\u003c/p>\u003c/li>\u003cli>\u003cp>描述他所感受到的\u003c/p>\u003c/li>\u003c/ol>","explains":"\u003cp>&nbsp;&nbsp; &nbsp;今晚上我给大家拆的书叫《如何说,孩子才会听;怎么听孩子才肯说》，本书的作者美国的阿黛尔.法伯和伊莱恩.玛兹丽施合著的，二位女士这都是国际著名的亲子沟通专家。本书曾经荣登《纽约时报书评》畅销书排行榜第一名！本书的核心是为读者提供一种建立在平等、相互尊重基础上与孩子的交流方式和沟通技巧。\u003c/p>\u003cp>&nbsp; &nbsp;&nbsp;现在请大家用3分钟时间，阅读手中的片段（两个标注“箭头”中间的部分）。有读完的伙伴，可向我举手示意。好，时间到，没有读完的伙伴没有关系，跟着我的讲解走就行。\u003c/p>\u003cp>今天分享的便签主题是：如何描述性赞赏孩子？描述性的赞赏胜过评价性的赞赏。因为孩子听到描述性赞赏后就能够欣赏自己。描述性赞赏的步骤：1.描述你所看到的；2.描述你的感受\u003cbr>\u003c/p>","interaction":"\u003cp>&nbsp; &nbsp; &nbsp;看到这个片段，我想起自己自己的儿子小时候比赛跳绳的事情。当时学校让小朋友学习跳绳，我就在家里教他跳，等他能跳五六个时候，我很开心，就给他大拇指：“儿子真棒，一下子能跳这么多，太棒了！”可是第二天从幼儿园回来再也不跳绳了，儿子沮丧地说：“妈妈骗人，别人都比我跳的好”。我当时无言以对。看到专家的建议，我才明白，“非常棒、很好、真美”这类词汇都是评价性的赞赏，会给孩子带来焦虑、压力或者感觉被否认等不良感受。作为父母，要给孩子内心真正的支持，要要将赞赏从评价性改变为描述性赞赏。这样孩子的内心会有很好的感受从而带来良好的行为。\u003c/p>\u003cp>这个周末孩子回来，我很希望他把自己的房间书桌整理干净。我会到他的房间里面，先观察一下，哪里整理的比较好。比如他把废纸、酸奶瓶放在了垃圾桶里，我会说：“儿子，我发现今天你把废纸、酸奶瓶及时扔进了垃圾桶，桌面以前清爽多了，我很开心。”相信孩子听到这样的描述性后，内心就能够真正的赞赏自己。\u003c/p>\u003cp>\u003cstrong>我来小结一下：用描述性赞赏，更能激发孩子内心对自己的赞赏。步骤\u003c/strong>\u003cstrong>1.\u003c/strong>\u003cstrong>描述你所看到的；\u003c/strong>\u003cstrong>2.\u003c/strong>\u003cstrong>描述你的感受。这个方法不仅适合于赞赏孩子，也同样适合于成人沟通，我们回去都试试吧，相信会有惊喜！\u003c/strong>\u003c/p>\u003cp>\u003cstrong>关于RIA的总结。R片段，I，我的总结，A1过去的经验连接，A2将来的行动计划。\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1515244486000,"updated_at":1517038526000,"ria":true},{"id":4392,"topic":"帮助孩子面对感受","learn_goal":"学会4个沟通技巧，运用到育儿及和他人额沟通中","remark":"","level":"TF2-1","duration":20,"status":29,"type":0,"chaishujia":{"username":"孙峰燕","city":"南通"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是你们的老朋友孙峰燕，在今天这个周二的晚上我们如约相聚在这里，今天我将继续定级TF2-1。\r\n 今天我待拆的是一本亲子教育类的书籍，本次的学习目标是学会如何帮助孩子面对他们的感受。\r\n 今天我要拆解的片段来自于《如何说孩子才会听 怎么听孩子才肯说》这本书，这本书是由两位国际著名亲子沟通专家所写，这本书在美国曾被评为“家庭教育年度最佳图书”，全球已有20多万个亲子团队使用本书作为家长的培训教材！\r\n这本书的特点是，我认为作者本身就具有很好的拆书思维，书中不仅举了大量的例子帮助我们理解书籍内容，而且还巧妙地设计了练习环节，很容易理解并立刻帮助家长运用到平时与孩子及他人的沟通中。\r\n读这本书的好处，可以立刻让父母们付诸实践，解决生活中常见的遇到的问题，帮助孩子最终成为独立、自强、充满爱心和具有责任感的人。","ratings_count":2,"texts":[{"id":7397,"quote":null,"explains":"\u003cp>这段话讲了四个技巧:1、认真倾听，让孩子感受到你在认真听的讲，如果是边看手机边听肯定是不行的；2、用哦、嗯来回应他们，这样让他们知道你确实是全神贯注地倾听；3、说出他们的感受，不仅仅是用哦、嗯来回应而已，还要体会到他们的感受比如开心？难过，说出来4用幻象的方式去实现他们的愿望。为了帮大家理解，我举2个例子，大家看看运用了哪个技巧？\u003c/p>\u003cp>1、 女儿告诉爸爸：我的小海龟今天早上死了，爸爸听到后说：哦，是吗？真没想到。女儿说：我还教她玩游戏，爸爸说：你们在一起\u003cstrong>挺开心\u003c/strong>的。女儿继续说：它是我的好朋友，爸爸回答到：失去朋友是\u003cstrong>挺难过\u003c/strong>的。\u003c/p>\u003cp>2、小明嚷嚷着要吃棒棒糖，妈妈说：真希望咱家里有。儿子说：我就要，妈妈说：听得出你很想吃，我真希望能变成一盒来。儿子想了想说：那我就吃点这个奶糖吧。\u003c/p>\u003cp>如果不按照这些技巧来做会有什么坏处呢？就拿第一个例子来看，当女儿很伤心地告诉爸爸她的小海龟死，通常家长会怎么回答？别难过了，宝贝，不就是只小海龟吗，或者还会说：别哭，我在给你买一个。结果怎么样，设身处地如果你是孩子，是不是会觉得很烦躁，因为对方没有体会你真正的感受。\u003c/p>","interaction":"\u003cp>【A1】请认真思考一下最近一段时间，有没有在和孩子沟通过程因为一件很小的事情，但是却导致不开心这样的结果？或者同事或朋友遇到烦心事找你诉苦，你给了她建议或者谈了你的看法等等，但对方并不买账？ 注意这里只要告诉我你遇到的事情即可，不需要考虑应该怎么做。\u003c/p>\u003cp>小伙伴A举了例子：1、孩子月考之前告诉妈妈好紧张，妈妈告诉孩子“有什么紧张的呀，就当和平时考试一样考呀，不需要紧张；2、为了出国，需要考英语，如何辅导孩子英文面试，孩子非常紧张，朋友劝她不用紧张不用紧张；这些其实都是没有理解孩子的感受\u003c/p>\u003cp>因为要答辩，答辩之前告诉朋友自己非常紧张，而朋友告诉她：没什么好紧张的呀；\u003c/p>\u003cp>小伙伴B举例：上次去答辩之前因为紧张不停地去上厕所，旁边的考生说“干嘛要紧张，能过就过”。\u003c/p>\u003cp>【A1+】很高兴你们有激活自己的相关经验，再遇到这样的情况，你可以怎样应用刚才学的方法去回应？小组内分享。\u003c/p>\u003cp>伙伴分享内容：1、认真倾听对方，回答：看来你很重视这次考试，所以你才会觉得紧张，重点是表示理解对方感受；2、尝试用幻想的方式实现他们的愿望，可以现象自己成为superwoman英语面试等考试so easy非常顺利通过后明年直接奔赴美利坚，利用通过考试的美好愿景缓解紧张。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1515064339000,"updated_at":1515064427000}]};